-- DB2 text-search projections. Views expose (rowid, source cols, fts_tsv) so
-- the DB2 rewriter can translate MATCH / bm25. memories_code_fts uses pg_trgm
-- (match_text + gin_trgm_ops) because trigram has no tsvector analogue. The
-- extension create is wrapped in a DO block that tolerates
-- insufficient_privilege so managed DB2 deployments without the extension
-- pre-enabled degrade to seq-scan rather than failing schema apply.
DO $trgm_ext$ BEGIN
   BEGIN
      CREATE EXTENSION IF NOT EXISTS pg_trgm;
   EXCEPTION WHEN OTHERS THEN
      RAISE NOTICE 'pg_trgm not enabled (%); memories_code_fts falls back to sequential scan', SQLERRM;
   END;
END $trgm_ext$;

ALTER TABLE memories
   ADD COLUMN IF NOT EXISTS provenance_category TEXT NOT NULL DEFAULT 'user_stated',
   ADD COLUMN IF NOT EXISTS use_cases TEXT NOT NULL DEFAULT '';

ALTER TABLE memories
   ADD COLUMN IF NOT EXISTS memories_fts_tsv tsvector GENERATED ALWAYS AS (
      to_tsvector('simple', coalesce(key, '') || ' ' || coalesce(content, ''))) STORED,
   ADD COLUMN IF NOT EXISTS memory_negation_fts_tsv tsvector GENERATED ALWAYS AS (
      to_tsvector('simple', coalesce(negation_tokens, ''))) STORED,
   ADD COLUMN IF NOT EXISTS memories_code_fts_text text GENERATED ALWAYS AS (
      coalesce(key, '') || ' ' || coalesce(content, '')) STORED;
CREATE INDEX IF NOT EXISTS memories_fts_gin ON memories USING GIN (memories_fts_tsv);
CREATE INDEX IF NOT EXISTS memory_negation_fts_gin ON memories USING GIN (memory_negation_fts_tsv);
DO $trgm_idx$ BEGIN
   BEGIN
      CREATE INDEX IF NOT EXISTS memories_code_fts_trgm_gin
         ON memories USING GIN (memories_code_fts_text gin_trgm_ops);
   EXCEPTION WHEN OTHERS THEN
      RAISE NOTICE 'memories_code_fts_trgm_gin skipped (%)', SQLERRM;
   END;
END $trgm_idx$;

-- ingest-lab: strategy metadata and enrichment fields (no embedding bytes in canonical rows)
ALTER TABLE kb_documents
   ADD COLUMN IF NOT EXISTS chunk_strategy TEXT NOT NULL DEFAULT 'heading',
   ADD COLUMN IF NOT EXISTS doc_kind TEXT NOT NULL DEFAULT '',
   ADD COLUMN IF NOT EXISTS chunk_context TEXT NOT NULL DEFAULT '';

ALTER TABLE kb_documents
   ADD COLUMN IF NOT EXISTS kb_fts_tsv tsvector GENERATED ALWAYS AS (
      to_tsvector('simple', coalesce(content, '') || ' ' || coalesce(heading_path, ''))) STORED;
CREATE INDEX IF NOT EXISTS kb_fts_gin ON kb_documents USING GIN (kb_fts_tsv);

-- structured-pdf Phase 1: per-chunk page span (cache of MIN/MAX(page_no) over the
-- chunk's kb_doc_regions rows, set in the ingest txn so it cannot drift). NULL for
-- non-PDF chunks; always set (>=1) for doc_kind='pdf'.
ALTER TABLE kb_documents
   ADD COLUMN IF NOT EXISTS page_start BIGINT DEFAULT NULL,
   ADD COLUMN IF NOT EXISTS page_end BIGINT DEFAULT NULL;

-- structured-pdf Phase 1: one row per extracted PDF line — the precise coordinate
-- evidence index. bbox is four REAL columns (no per-row TEXT parse); normalized
-- per page to [0,1], top-left origin. document_key (= kb_documents.file_path) is
-- denormalized so access-control filtering needs no join. content_type ∈ {text}
-- in Phase 1 (table_cell/figure_caption arrive with §3/§4).
CREATE TABLE IF NOT EXISTS kb_doc_regions (
   id            BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
   chunk_id      BIGINT NOT NULL,
   document_key  TEXT NOT NULL DEFAULT '',
   page_no       BIGINT NOT NULL DEFAULT 0,
   x0            REAL NOT NULL DEFAULT 0,
   y0            REAL NOT NULL DEFAULT 0,
   x1            REAL NOT NULL DEFAULT 0,
   y1            REAL NOT NULL DEFAULT 0,
   quote         TEXT NOT NULL DEFAULT '',
   line_index    BIGINT NOT NULL DEFAULT 0,
   content_type  TEXT NOT NULL DEFAULT 'text',
   FOREIGN KEY (chunk_id) REFERENCES kb_documents(id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_kb_doc_regions_chunk ON kb_doc_regions (chunk_id, line_index);
CREATE INDEX IF NOT EXISTS idx_kb_doc_regions_dockey ON kb_doc_regions (document_key, page_no);

-- structured-pdf Phase 1b: §6 sensitivity + quarantine. sensitivity_class is the
-- uploader-declared class (public|internal|restricted), validated at the upload surface
-- and stamped on the chunk AND copied to every region so retrieval filters without a join.
-- quarantine_state holds 'pending' for a restricted document (withheld) or '' otherwise.
-- Empty default is for the non-PDF rows that never carry these; PDF rows always get a
-- validated class at ingest.
ALTER TABLE kb_documents
   ADD COLUMN IF NOT EXISTS sensitivity_class TEXT NOT NULL DEFAULT '',
   ADD COLUMN IF NOT EXISTS quarantine_state TEXT NOT NULL DEFAULT '';
ALTER TABLE kb_doc_regions
   ADD COLUMN IF NOT EXISTS sensitivity_class TEXT NOT NULL DEFAULT '';

-- structured-pdf Phase B: per-document TSR outcome, drives lookup_table's tsr_status marker
-- so a caller can tell "TSR ran, no table" (no_table) from "TSR never ran" (''/unavailable)
-- from "TSR ran, cells present" (ran). Set at ingest; '' means the capability was off/absent.
ALTER TABLE kb_documents
   ADD COLUMN IF NOT EXISTS tsr_state TEXT NOT NULL DEFAULT '';

-- kb_table_cells: structured table cells recognised by the optional TSR sidecar
-- (structured-PDF Phase B). Cells are stored ONLY here — deliberately NOT in the shared
-- typed_facts table: typed_facts has no document_key / quarantine column, so a cell row
-- there would leak a withheld document's data through general fact readers
-- (db2_typed_fact_recall / _by_relation apply no source/quarantine filter). Keeping cells
-- in their own access-gated relation makes the isolation STRUCTURAL (RT-Perf: table-cell
-- facts cannot bloat the general fact indexes) and makes region re-extraction a clean
-- cascade with no orphaned parent row. document_key + sensitivity_class are denormalised
-- for filtering exactly as kb_doc_regions does; the LIVE document_key ACL + quarantine_state
-- on kb_documents is the authority. region_id links each cell to its source kb_doc_regions
-- row (page_no / bbox / document_key); ON DELETE CASCADE so a re-ingest drops cells cleanly.
-- subject/relation/object are the optional entity-linkable triple (populated when the TSR
-- contract supplies a header/key interpretation; empty otherwise — the cell is still
-- retrievable by (row,col,text)). source_type is fixed 'table_cell' so lookup_table returns
-- only cells.
CREATE TABLE IF NOT EXISTS kb_table_cells (
   id                BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
   region_id         BIGINT NOT NULL,
   document_key      TEXT NOT NULL DEFAULT '',
   page_no           BIGINT NOT NULL DEFAULT 0,
   cell_row          BIGINT NOT NULL DEFAULT 0,
   cell_col          BIGINT NOT NULL DEFAULT 0,
   cell_text         TEXT NOT NULL DEFAULT '',
   subject           TEXT NOT NULL DEFAULT '',
   relation          TEXT NOT NULL DEFAULT '',
   object            TEXT NOT NULL DEFAULT '',
   tsr_confidence    BIGINT NOT NULL DEFAULT 0,
   source_type       TEXT NOT NULL DEFAULT 'table_cell',
   sensitivity_class TEXT NOT NULL DEFAULT '',
   created_at        TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS')),
   FOREIGN KEY (region_id) REFERENCES kb_doc_regions(id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_kb_table_cells_dockey ON kb_table_cells (document_key, page_no);
CREATE INDEX IF NOT EXISTS idx_kb_table_cells_region ON kb_table_cells (region_id);

-- kb_doc_assets: visual crops (figures/tables/pages) rendered from a PDF (structured-PDF
-- Phase C). The crop BYTES live in the content-addressed blob store (one file per sha256);
-- blob_ref is that sha256 — a KB-INTERNAL identifier never returned to a client, never in a
-- URL/log/error, and the blob dir is served by no file route. The sole client read path is
-- open_asset, keyed on the OPAQUE row id (kb_doc_assets.id, never sha256-derived), which
-- applies the caller's auth + the live document_key ACL + an access audit-log entry before
-- streaming bytes. document_key is the logical document identity + access key (RT-D1): one
-- document has N asset rows, no single-document row exists to FK against, so access control
-- filters on document_key exactly as chunks do (via a join to the authoritative kb_documents
-- row for the live quarantine_state). sensitivity_class is denormalised for filtering; the
-- live ACL is the authority. Content-addressed dedup is safe: two docs sharing a byte-
-- identical crop share one blob but each keeps its OWN row + document_key + class, and
-- open_asset gates the ROW, never the blob — dedup never widens access.
CREATE TABLE IF NOT EXISTS kb_doc_assets (
   id                BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
   project           TEXT NOT NULL DEFAULT '',
   generation        BIGINT NOT NULL DEFAULT 1 CHECK (generation > 0),
   document_key      TEXT NOT NULL DEFAULT '',
   page_no           BIGINT NOT NULL DEFAULT 0,
   x0                REAL NOT NULL DEFAULT 0,
   y0                REAL NOT NULL DEFAULT 0,
   x1                REAL NOT NULL DEFAULT 0,
   y1                REAL NOT NULL DEFAULT 0,
   kind              TEXT NOT NULL DEFAULT '',
   caption           TEXT NOT NULL DEFAULT '',
   content_type      TEXT NOT NULL DEFAULT 'image/png',
   blob_ref          TEXT NOT NULL DEFAULT '',
   sensitivity_class TEXT NOT NULL DEFAULT '',
   created_at        TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS'))
);
ALTER TABLE kb_doc_assets ADD COLUMN IF NOT EXISTS project TEXT NOT NULL DEFAULT '';
DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns
         WHERE table_schema=current_schema() AND table_name='kb_doc_assets'
           AND column_name='generation'
    ) THEN
        ALTER TABLE kb_doc_assets ADD COLUMN generation BIGINT NOT NULL DEFAULT 1
            CHECK (generation > 0);
        UPDATE kb_doc_assets a SET generation=p.current_generation
          FROM projects p WHERE p.name=a.project;
    END IF;
END $$;
-- Legacy rows predate explicit ownership. Backfill only when the document key
-- maps to exactly one project; ambiguous rows remain unowned and are never
-- selected by a project purge.
UPDATE kb_doc_assets a
   SET project = d.project
  FROM (SELECT file_path, MIN(project) AS project
          FROM kb_documents GROUP BY file_path HAVING COUNT(DISTINCT project) = 1) d
 WHERE a.project = '' AND a.document_key = d.file_path;
CREATE INDEX IF NOT EXISTS idx_kb_doc_assets_project ON kb_doc_assets (project, document_key);
CREATE INDEX IF NOT EXISTS idx_kb_doc_assets_dockey ON kb_doc_assets (document_key);
CREATE INDEX IF NOT EXISTS idx_kb_doc_assets_blob ON kb_doc_assets (blob_ref);

ALTER TABLE memory_chunks
   ADD COLUMN IF NOT EXISTS memory_chunks_fts_tsv tsvector GENERATED ALWAYS AS (
      to_tsvector('simple', coalesce(chunk_text, ''))) STORED;
CREATE INDEX IF NOT EXISTS memory_chunks_fts_gin ON memory_chunks USING GIN (memory_chunks_fts_tsv);

ALTER TABLE memory_units
   ADD COLUMN IF NOT EXISTS memory_units_fts_tsv tsvector GENERATED ALWAYS AS (
      to_tsvector('simple', coalesce(unit_key, '') || ' ' || coalesce(unit_text, ''))) STORED;
CREATE INDEX IF NOT EXISTS memory_units_fts_gin ON memory_units USING GIN (memory_units_fts_tsv);

ALTER TABLE prospective_memories
   ADD COLUMN IF NOT EXISTS prospective_memories_fts_tsv tsvector GENERATED ALWAYS AS (
      to_tsvector('simple', coalesce(trigger_text, ''))) STORED;
CREATE INDEX IF NOT EXISTS prospective_memories_fts_gin ON prospective_memories USING GIN (prospective_memories_fts_tsv);

ALTER TABLE epistemic_directives
   ADD COLUMN IF NOT EXISTS epistemic_directives_fts_tsv tsvector GENERATED ALWAYS AS (
      to_tsvector('simple', coalesce(question, '') || ' ' || coalesce(topic, ''))) STORED;
CREATE INDEX IF NOT EXISTS epistemic_directives_fts_gin ON epistemic_directives USING GIN (epistemic_directives_fts_tsv);

ALTER TABLE file_contents
   ADD COLUMN IF NOT EXISTS code_fts_tsv tsvector GENERATED ALWAYS AS (
      to_tsvector('simple', coalesce(content, ''))) STORED;
CREATE INDEX IF NOT EXISTS code_fts_gin ON file_contents USING GIN (code_fts_tsv);
ALTER TABLE kb_file_index ADD COLUMN IF NOT EXISTS content TEXT DEFAULT NULL;

CREATE TABLE IF NOT EXISTS kb_code_unit_jobs (  id BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,  project TEXT NOT NULL DEFAULT '',  generation BIGINT NOT NULL DEFAULT 1 CHECK (generation > 0),  file_path TEXT NOT NULL DEFAULT '',  symbol TEXT NOT NULL DEFAULT '',  kind TEXT NOT NULL DEFAULT 'function',  line INTEGER NOT NULL DEFAULT 0,  status TEXT NOT NULL DEFAULT 'pending',  attempts INTEGER NOT NULL DEFAULT 0,  last_error TEXT NOT NULL DEFAULT '',  claimed_by TEXT NOT NULL DEFAULT '',  claimed_at TEXT NOT NULL DEFAULT '',  created_at TEXT NOT NULL DEFAULT (pg_now_text()),  updated_at TEXT NOT NULL DEFAULT (pg_now_text()),  next_attempt_at TEXT NOT NULL DEFAULT '',  UNIQUE(project, generation, file_path, symbol));
-- Retry backoff: pre-existing DBs predate next_attempt_at, and CREATE TABLE IF NOT
-- EXISTS is a no-op for them, so the column is added here for upgrades. Must stay
-- AFTER the CREATE above -- ordered before it, this ALTER aborts schema apply on a
-- fresh database with "relation kb_code_unit_jobs does not exist".
ALTER TABLE kb_code_unit_jobs ADD COLUMN IF NOT EXISTS next_attempt_at TEXT NOT NULL DEFAULT '';
DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns
         WHERE table_schema=current_schema() AND table_name='kb_code_unit_jobs'
           AND column_name='generation'
    ) THEN
        ALTER TABLE kb_code_unit_jobs ADD COLUMN generation BIGINT NOT NULL DEFAULT 1
           CHECK (generation > 0);
        UPDATE kb_code_unit_jobs j SET generation=p.current_generation
          FROM projects p WHERE p.name=j.project;
    END IF;
END $$;
ALTER TABLE kb_code_unit_jobs DROP CONSTRAINT IF EXISTS kb_code_unit_jobs_project_file_path_symbol_key;
CREATE UNIQUE INDEX IF NOT EXISTS idx_kb_code_unit_jobs_project_generation_symbol
    ON kb_code_unit_jobs(project, generation, file_path, symbol);
CREATE INDEX IF NOT EXISTS idx_kb_code_unit_jobs_status ON kb_code_unit_jobs(status, id);

CREATE OR REPLACE VIEW memories_fts AS
   SELECT id AS rowid, key, content,
          memories_fts_tsv || to_tsvector('simple', coalesce(use_cases, '')) AS fts_tsv
     FROM memories;
CREATE OR REPLACE VIEW memory_negation_fts AS
   SELECT id AS rowid, negation_tokens, memory_negation_fts_tsv AS fts_tsv FROM memories;
CREATE OR REPLACE VIEW memories_code_fts AS
   SELECT id AS rowid, key, content, memories_code_fts_text AS match_text FROM memories;
CREATE OR REPLACE VIEW kb_fts AS
   SELECT id AS rowid, content, heading_path, kb_fts_tsv AS fts_tsv FROM kb_documents;
CREATE OR REPLACE VIEW memory_chunks_fts AS
   SELECT id AS rowid, chunk_text, memory_chunks_fts_tsv AS fts_tsv FROM memory_chunks;
CREATE OR REPLACE VIEW memory_units_fts AS
   SELECT id AS rowid, unit_key, unit_text, memory_units_fts_tsv AS fts_tsv FROM memory_units;
CREATE OR REPLACE VIEW prospective_memories_fts AS
   SELECT id AS rowid, trigger_text, prospective_memories_fts_tsv AS fts_tsv FROM prospective_memories;
CREATE OR REPLACE VIEW epistemic_directives_fts AS
   SELECT id AS rowid, question, topic, epistemic_directives_fts_tsv AS fts_tsv FROM epistemic_directives;
CREATE OR REPLACE VIEW code_fts AS
   SELECT file_id AS rowid, content, code_fts_tsv AS fts_tsv FROM file_contents;

-- Approximate sketch persistence (Bloom, MinHash-LSH, Count-Min, HyperLogLog).
-- One row per (sketch_kind, scope_kind, scope_id, feature_family).
-- See docs/proposals/done/approximate-sketches-for-ingest-prefiltering.md
CREATE TABLE IF NOT EXISTS sketch_store (
    id             BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
    sketch_kind    TEXT NOT NULL,
    scope_kind     TEXT NOT NULL,
    scope_id       TEXT NOT NULL DEFAULT '',
    feature_family TEXT NOT NULL,
    state_bytes    BYTEA NOT NULL,
    item_count     BIGINT NOT NULL DEFAULT 0,
    params_json    JSONB NOT NULL DEFAULT '{}',
    created_at     TEXT NOT NULL,
    updated_at     TEXT NOT NULL,
    UNIQUE (sketch_kind, scope_kind, scope_id, feature_family)
);
CREATE TABLE IF NOT EXISTS kb_minhash_signatures (  project TEXT NOT NULL, generation BIGINT NOT NULL DEFAULT 1 CHECK (generation > 0),  file_path TEXT NOT NULL,  file_hash TEXT NOT NULL DEFAULT '',  signature_bytes BYTEA NOT NULL,  updated_at TEXT NOT NULL DEFAULT (pg_now_text()),  PRIMARY KEY (project, generation, file_path));
CREATE INDEX IF NOT EXISTS idx_kb_minhash_signatures_project ON kb_minhash_signatures(project);
CREATE TABLE IF NOT EXISTS kb_lsh_buckets (  project TEXT NOT NULL, generation BIGINT NOT NULL DEFAULT 1 CHECK (generation > 0),  band INTEGER NOT NULL,  band_hash TEXT NOT NULL,  file_path TEXT NOT NULL,  updated_at TEXT NOT NULL DEFAULT (pg_now_text()),  PRIMARY KEY (project, generation, band, band_hash, file_path));
CREATE INDEX IF NOT EXISTS idx_kb_lsh_buckets_lookup ON kb_lsh_buckets(project, band, band_hash);
DO $$
DECLARE t TEXT;
BEGIN
    FOREACH t IN ARRAY ARRAY['kb_minhash_signatures','kb_lsh_buckets'] LOOP
        IF NOT EXISTS (
            SELECT 1 FROM information_schema.columns
             WHERE table_schema=current_schema() AND table_name=t AND column_name='generation'
        ) THEN
            EXECUTE format('ALTER TABLE %I ADD COLUMN generation BIGINT NOT NULL DEFAULT 1 CHECK (generation > 0)',t);
            EXECUTE format('UPDATE %I x SET generation=p.current_generation FROM projects p WHERE p.name=x.project',t);
        END IF;
    END LOOP;
END $$;
DO $$
BEGIN
    IF EXISTS (
        SELECT 1 FROM pg_constraint
         WHERE conrelid='kb_minhash_signatures'::regclass
           AND conname='kb_minhash_signatures_pkey'
           AND pg_get_constraintdef(oid) NOT LIKE '%generation%'
    ) THEN
        ALTER TABLE kb_minhash_signatures DROP CONSTRAINT kb_minhash_signatures_pkey;
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint
         WHERE conrelid='kb_minhash_signatures'::regclass
           AND conname='kb_minhash_signatures_pkey'
    ) THEN
        ALTER TABLE kb_minhash_signatures ADD CONSTRAINT kb_minhash_signatures_pkey
            PRIMARY KEY (project, generation, file_path);
    END IF;
    IF EXISTS (
        SELECT 1 FROM pg_constraint
         WHERE conrelid='kb_lsh_buckets'::regclass
           AND conname='kb_lsh_buckets_pkey'
           AND pg_get_constraintdef(oid) NOT LIKE '%generation%'
    ) THEN
        ALTER TABLE kb_lsh_buckets DROP CONSTRAINT kb_lsh_buckets_pkey;
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint
         WHERE conrelid='kb_lsh_buckets'::regclass
           AND conname='kb_lsh_buckets_pkey'
    ) THEN
        ALTER TABLE kb_lsh_buckets ADD CONSTRAINT kb_lsh_buckets_pkey
            PRIMARY KEY (project, generation, band, band_hash, file_path);
    END IF;
END $$;

-- Charter artifact tables: candidate and committed artifacts, citations,
-- links, and audit events.  Created exactly once across cross-source-learning-
-- substrate and deep-curator; all charter-instance proposals share them.
-- See docs/proposals/done/cross-source-learning-substrate.md
CREATE TABLE IF NOT EXISTS artifacts (
    id                 TEXT NOT NULL PRIMARY KEY,
    kind               TEXT NOT NULL,
    state              TEXT NOT NULL DEFAULT 'proposed',
    scope_kind         TEXT NOT NULL DEFAULT 'user',
    scope_id           TEXT NOT NULL DEFAULT '',
    operator_id        TEXT NOT NULL DEFAULT '',
    confidence         DOUBLE PRECISION NOT NULL DEFAULT 1.0,
    attempt_count      INT NOT NULL DEFAULT 1,
    source_bundle_hash TEXT NOT NULL DEFAULT '',
    model_version      TEXT NOT NULL DEFAULT '',
    prompt_version     TEXT NOT NULL DEFAULT '',
    target_surface     TEXT NOT NULL DEFAULT '',
    created_at         TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS')),
    committed_at       TEXT NOT NULL DEFAULT '',
    retired_at         TEXT NOT NULL DEFAULT '',
    superseded_by      TEXT NOT NULL DEFAULT '',
    payload            JSONB NOT NULL DEFAULT '{}'
);
CREATE INDEX IF NOT EXISTS idx_artifacts_kind_state ON artifacts (kind, state);
CREATE INDEX IF NOT EXISTS idx_artifacts_scope ON artifacts (scope_kind, scope_id);
CREATE INDEX IF NOT EXISTS idx_artifacts_retrieval_attr ON artifacts (kind, scope_id) WHERE kind = 'retrieval_attribution';
CREATE INDEX IF NOT EXISTS idx_artifacts_demotion_profile ON artifacts (kind, target_surface, scope_kind, scope_id) WHERE kind = 'demotion_profile';

-- evidence_index_ops / learning_synth_ops: embed-ops queues keyed on artifacts.
-- Must follow the artifacts table above — they carry a foreign key into it, so
-- a fresh-database single-pass schema apply fails if they precede it.
-- See docs/proposals/pending/cross-source-learning-pipeline.md
CREATE TABLE IF NOT EXISTS evidence_index_ops (  artifact_id TEXT PRIMARY KEY REFERENCES artifacts(id) ON DELETE CASCADE,  collection TEXT NOT NULL DEFAULT 'evidence',  status TEXT NOT NULL DEFAULT 'pending',  attempts BIGINT NOT NULL DEFAULT 0,  last_error TEXT NOT NULL DEFAULT '',  updated_at TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS')));
CREATE INDEX IF NOT EXISTS idx_evidence_index_ops_status ON evidence_index_ops(status);
CREATE TABLE IF NOT EXISTS learning_synth_ops (  artifact_id TEXT PRIMARY KEY REFERENCES artifacts(id) ON DELETE CASCADE,  status TEXT NOT NULL DEFAULT 'pending',  attempts BIGINT NOT NULL DEFAULT 0,  last_error TEXT NOT NULL DEFAULT '',  updated_at TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS')));
CREATE INDEX IF NOT EXISTS idx_learning_synth_ops_status ON learning_synth_ops(status);

CREATE TABLE IF NOT EXISTS artifact_citations (
    artifact_id  TEXT NOT NULL REFERENCES artifacts (id) ON DELETE CASCADE,
    source_kind  TEXT NOT NULL,
    source_id    TEXT NOT NULL,
    span_start   INT NOT NULL DEFAULT 0,
    span_end     INT NOT NULL DEFAULT 0,
    PRIMARY KEY (artifact_id, source_kind, source_id, span_start, span_end)
);

CREATE TABLE IF NOT EXISTS artifact_links (
    from_id  TEXT NOT NULL REFERENCES artifacts (id) ON DELETE CASCADE,
    to_id    TEXT NOT NULL REFERENCES artifacts (id) ON DELETE CASCADE,
    kind     TEXT NOT NULL,
    PRIMARY KEY (from_id, to_id, kind)
);

CREATE TABLE IF NOT EXISTS audit_events (
    id                  TEXT NOT NULL PRIMARY KEY,
    source_artifact_id  TEXT NOT NULL REFERENCES artifacts (id) ON DELETE CASCADE,
    target_surface      TEXT NOT NULL,
    target_id           TEXT NOT NULL,
    operator_id         TEXT NOT NULL DEFAULT '',
    scope_kind          TEXT NOT NULL DEFAULT '',
    scope_id            TEXT NOT NULL DEFAULT '',
    before_snapshot     JSONB,
    after_snapshot      JSONB,
    applied_at          TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS')),
    applied_confidence  DOUBLE PRECISION NOT NULL DEFAULT 1.0,
    flagged_for_review  BOOLEAN NOT NULL DEFAULT FALSE,
    reviewed_at         TEXT NOT NULL DEFAULT '',
    verdict             TEXT NOT NULL DEFAULT '',
    verdict_tag         TEXT NOT NULL DEFAULT '',
    verdict_scope       TEXT NOT NULL DEFAULT '',
    counter_example     TEXT NOT NULL DEFAULT '',
    verdict_note        TEXT NOT NULL DEFAULT ''
);
CREATE INDEX IF NOT EXISTS idx_audit_events_artifact ON audit_events (source_artifact_id);
CREATE INDEX IF NOT EXISTS idx_audit_events_surface ON audit_events (target_surface, applied_at);

CREATE TABLE IF NOT EXISTS feature_rows (
    subject_id          TEXT NOT NULL,
    subject_kind        TEXT NOT NULL,
    scope_kind          TEXT NOT NULL DEFAULT '',
    scope_id            TEXT NOT NULL DEFAULT '',
    feature_set_version TEXT NOT NULL,
    features            JSONB NOT NULL DEFAULT '{}',
    computed_at         TEXT NOT NULL,
    PRIMARY KEY (subject_id, subject_kind, feature_set_version)
);
CREATE INDEX IF NOT EXISTS idx_feature_rows_kind_ts ON feature_rows (subject_kind, computed_at);

CREATE TABLE IF NOT EXISTS report_enrichments (
    subject_type        TEXT NOT NULL,
    subject_id          TEXT NOT NULL,
    enrichment_kind     TEXT NOT NULL,
    source              TEXT NOT NULL DEFAULT '',
    schema_version      TEXT NOT NULL,
    payload_json        JSONB NOT NULL DEFAULT '{}',
    input_hash          TEXT NOT NULL DEFAULT '',
    computed_at         TEXT NOT NULL,
    expires_at          TEXT NOT NULL DEFAULT '',
    PRIMARY KEY (subject_type, subject_id, enrichment_kind, source, schema_version)
);
CREATE INDEX IF NOT EXISTS idx_report_enrichments_subject
    ON report_enrichments (subject_type, subject_id);
CREATE INDEX IF NOT EXISTS idx_report_enrichments_kind_ts
    ON report_enrichments (enrichment_kind, computed_at);

-- Contextual bandit: per-decision log for propensity-weighted replay.
-- See docs/proposals/accepted/contextual-bandits-and-counterfactual-replay.md
CREATE TABLE IF NOT EXISTS bandit_decisions (
    id              TEXT NOT NULL PRIMARY KEY,
    decision_point  TEXT NOT NULL,
    arm_id          TEXT NOT NULL,
    context_hash    TEXT NOT NULL DEFAULT '',
    propensity      DOUBLE PRECISION NOT NULL DEFAULT 1.0,
    reward          DOUBLE PRECISION,
    decided_at      TEXT NOT NULL,
    closed_at       TEXT NOT NULL DEFAULT '',
    is_exploration  BOOLEAN NOT NULL DEFAULT FALSE
);
-- Additive migration: prior deployments that pre-date is_exploration.
ALTER TABLE bandit_decisions ADD COLUMN IF NOT EXISTS is_exploration BOOLEAN NOT NULL DEFAULT FALSE;
CREATE INDEX IF NOT EXISTS idx_bandit_decisions_point ON bandit_decisions (decision_point, arm_id, decided_at);
CREATE INDEX IF NOT EXISTS idx_bandit_decisions_explore ON bandit_decisions (decision_point, decided_at, is_exploration);

-- Per-arm posterior statistics (materialized by the offline updater).
CREATE TABLE IF NOT EXISTS bandit_arm_stats (
    decision_point    TEXT NOT NULL,
    arm_id            TEXT NOT NULL,
    n_decisions       BIGINT NOT NULL DEFAULT 0,
    n_rewards         BIGINT NOT NULL DEFAULT 0,
    sum_reward        DOUBLE PRECISION NOT NULL DEFAULT 0.0,
    sum_reward_sq     DOUBLE PRECISION NOT NULL DEFAULT 0.0,
    posterior_alpha   DOUBLE PRECISION NOT NULL DEFAULT 1.0,
    posterior_beta    DOUBLE PRECISION NOT NULL DEFAULT 1.0,
    updated_at        TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS')),
    PRIMARY KEY (decision_point, arm_id)
);

-- Promoted (production-default) arm per decision point: the arm an operator has
-- locked in via `aimee optimize promote --apply`. Consumers use it as the default
-- when live bandit sampling is off; rollback_arm records the prior default.
CREATE TABLE IF NOT EXISTS bandit_promotions (
    decision_point  TEXT NOT NULL PRIMARY KEY,
    arm_id          TEXT NOT NULL,
    rollback_arm    TEXT NOT NULL DEFAULT '',
    promoted_at     TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS'))
);

-- KB temporal confidence decay: access tracking + maintenance audit
ALTER TABLE artifacts ADD COLUMN IF NOT EXISTS last_accessed_at TIMESTAMPTZ DEFAULT NULL;
ALTER TABLE artifacts ADD COLUMN IF NOT EXISTS last_decay_at TEXT DEFAULT NULL;
UPDATE artifacts SET last_accessed_at = COALESCE(NULLIF(committed_at,'')::timestamptz, created_at::timestamptz) WHERE last_accessed_at IS NULL;
CREATE TABLE IF NOT EXISTS kb_maintenance_runs (
    id           TEXT NOT NULL PRIMARY KEY,
    rows_decayed INTEGER NOT NULL DEFAULT 0,
    orphans_pruned INTEGER NOT NULL DEFAULT 0,
    elapsed_ms   BIGINT NOT NULL DEFAULT 0,
    lambda       DOUBLE PRECISION NOT NULL DEFAULT 0.005,
    confidence_floor DOUBLE PRECISION NOT NULL DEFAULT 0.10,
    dry_run      INTEGER NOT NULL DEFAULT 0,
    run_at       TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS'))
);
CREATE INDEX IF NOT EXISTS idx_kb_maintenance_runs_at ON kb_maintenance_runs (run_at DESC);

-- Cross-source learning review surface: reflection scheduling + review query index
ALTER TABLE artifacts ADD COLUMN IF NOT EXISTS reflected_at TEXT DEFAULT NULL;
CREATE INDEX IF NOT EXISTS idx_artifacts_review
    ON artifacts (state, target_surface, confidence DESC)
    WHERE state = 'proposed';

-- auditable-correctness (§Layer 2 / D14): the caller-visible per-turn id that
-- keys a retrieval_event so an audit trace can reconstruct what grounded a turn.
-- Nullable (legacy/proactive events have none); a partial unique index makes one
-- turn map to one event (and enables the P1.5 idempotent two-writer merge).
ALTER TABLE artifacts ADD COLUMN IF NOT EXISTS turn_id TEXT DEFAULT NULL
    CHECK (turn_id IS NULL OR length(turn_id) <= 128);
CREATE UNIQUE INDEX IF NOT EXISTS idx_artifacts_turn_event
    ON artifacts (turn_id) WHERE kind = 'retrieval_event' AND turn_id IS NOT NULL;

-- KB ingest API and corpus staging: doc upload, review queue, release lifecycle.
-- See docs/proposals/pending/aimee-kb-ingest-api-and-corpus-staging.md
CREATE TABLE IF NOT EXISTS docs (
    id               BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
    content_hash     TEXT NOT NULL,
    filename         TEXT NOT NULL DEFAULT '',
    scope            TEXT NOT NULL DEFAULT 'global',
    converter        TEXT NOT NULL DEFAULT 'passthrough',
    converter_version TEXT NOT NULL DEFAULT '',
    normalized_text  TEXT NOT NULL DEFAULT '',
    state            TEXT NOT NULL DEFAULT 'staged',
    review_needed    BOOLEAN NOT NULL DEFAULT FALSE,
    review_reason    TEXT NOT NULL DEFAULT '',
    created_at       TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS')),
    updated_at       TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS')),
    UNIQUE (content_hash, converter, converter_version, scope)
);
CREATE INDEX IF NOT EXISTS idx_docs_state_review ON docs (state, review_needed);
CREATE INDEX IF NOT EXISTS idx_docs_content_hash ON docs (content_hash);
ALTER TABLE docs ADD COLUMN IF NOT EXISTS doc_type TEXT NOT NULL DEFAULT '';
ALTER TABLE docs ADD COLUMN IF NOT EXISTS doc_type_confidence DOUBLE PRECISION NOT NULL DEFAULT 0.0;
CREATE INDEX IF NOT EXISTS idx_docs_doc_type ON docs (doc_type);

CREATE TABLE IF NOT EXISTS document_sections (
    id           BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
    doc_id       BIGINT NOT NULL REFERENCES docs(id) ON DELETE CASCADE,
    parent_id    BIGINT REFERENCES document_sections(id) ON DELETE CASCADE,
    ordinal      BIGINT NOT NULL DEFAULT 0,
    depth        BIGINT NOT NULL DEFAULT 0,
    heading      TEXT NOT NULL DEFAULT '',
    heading_path TEXT NOT NULL DEFAULT '',
    span_start   BIGINT NOT NULL DEFAULT 0,
    span_end     BIGINT NOT NULL DEFAULT 0,
    content_hash TEXT NOT NULL DEFAULT '',
    created_at   TEXT NOT NULL DEFAULT (pg_now_text()),
    UNIQUE (doc_id, heading_path, ordinal)
);
CREATE INDEX IF NOT EXISTS idx_document_sections_doc ON document_sections (doc_id, ordinal);
CREATE INDEX IF NOT EXISTS idx_document_sections_parent ON document_sections (parent_id);

CREATE TABLE IF NOT EXISTS document_references (
    id              BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
    from_doc_id     BIGINT NOT NULL REFERENCES docs(id) ON DELETE CASCADE,
    from_section_id BIGINT REFERENCES document_sections(id) ON DELETE SET NULL,
    ref_type        TEXT NOT NULL DEFAULT 'mentions',
    raw_target      TEXT NOT NULL DEFAULT '',
    to_doc_id       BIGINT REFERENCES docs(id) ON DELETE SET NULL,
    resolution      TEXT NOT NULL DEFAULT 'unresolved',
    confidence      DOUBLE PRECISION NOT NULL DEFAULT 1.0,
    created_at      TEXT NOT NULL DEFAULT (pg_now_text()),
    UNIQUE (from_doc_id, ref_type, raw_target)
);
CREATE INDEX IF NOT EXISTS idx_doc_refs_from ON document_references (from_doc_id);
CREATE INDEX IF NOT EXISTS idx_doc_refs_to ON document_references (to_doc_id) WHERE to_doc_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_doc_refs_resolution ON document_references (resolution);

CREATE TABLE IF NOT EXISTS corpus_processing_jobs (
    doc_id       BIGINT PRIMARY KEY REFERENCES docs(id) ON DELETE CASCADE,
    content_hash TEXT NOT NULL DEFAULT '',
    stage        TEXT NOT NULL DEFAULT 'ingested',
    stage_status TEXT NOT NULL DEFAULT 'pending',
    attempts     BIGINT NOT NULL DEFAULT 0,
    lease_owner  TEXT NOT NULL DEFAULT '',
    lease_until  TEXT NOT NULL DEFAULT '',
    last_error   TEXT NOT NULL DEFAULT '',
    created_at   TEXT NOT NULL DEFAULT (pg_now_text()),
    updated_at   TEXT NOT NULL DEFAULT (pg_now_text())
);
CREATE INDEX IF NOT EXISTS idx_corpus_jobs_status ON corpus_processing_jobs (stage_status, stage, doc_id);

CREATE TABLE IF NOT EXISTS corpus_stage_events (
    id         BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
    doc_id     BIGINT NOT NULL REFERENCES docs(id) ON DELETE CASCADE,
    from_stage TEXT NOT NULL DEFAULT '',
    to_stage   TEXT NOT NULL DEFAULT '',
    outcome    TEXT NOT NULL DEFAULT '',
    detail     TEXT NOT NULL DEFAULT '',
    worker     TEXT NOT NULL DEFAULT '',
    created_at TEXT NOT NULL DEFAULT (pg_now_text())
);
CREATE INDEX IF NOT EXISTS idx_corpus_stage_events_doc ON corpus_stage_events (doc_id, id);

CREATE TABLE IF NOT EXISTS document_versions (
    id           BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
    doc_key      TEXT NOT NULL,
    doc_id       BIGINT NOT NULL REFERENCES docs(id) ON DELETE CASCADE,
    content_hash TEXT NOT NULL DEFAULT '',
    version_no   BIGINT NOT NULL DEFAULT 1,
    source_mtime TEXT NOT NULL DEFAULT '',
    source_time  TEXT NOT NULL DEFAULT '',
    source_time_provenance TEXT NOT NULL DEFAULT 'unknown',
    is_current   BOOLEAN NOT NULL DEFAULT TRUE,
    superseded_at TEXT NOT NULL DEFAULT '',
    created_at   TEXT NOT NULL DEFAULT (pg_now_text()),
    UNIQUE (doc_key, content_hash)
);
CREATE INDEX IF NOT EXISTS idx_document_versions_current ON document_versions (doc_key, is_current);

CREATE TABLE IF NOT EXISTS doc_releases (
    id           BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
    name         TEXT NOT NULL UNIQUE,
    state        TEXT NOT NULL DEFAULT 'pending',
    promoted_at  TEXT NOT NULL DEFAULT '',
    retired_at   TEXT NOT NULL DEFAULT '',
    created_at   TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS'))
);
CREATE INDEX IF NOT EXISTS idx_doc_releases_state ON doc_releases (state);

CREATE TABLE IF NOT EXISTS release_docs (
    release_id  BIGINT NOT NULL REFERENCES doc_releases(id) ON DELETE CASCADE,
    doc_id      BIGINT NOT NULL REFERENCES docs(id) ON DELETE CASCADE,
    accepted_at TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS')),
    PRIMARY KEY (release_id, doc_id)
);
CREATE INDEX IF NOT EXISTS idx_release_docs_doc_id ON release_docs (doc_id);

-- pgvector embedding tables (memory_embeddings, kb_embeddings).
-- Wrapped in a DO block so schema apply degrades gracefully when pgvector is
-- not yet installed; operators will see a NOTICE and vector search returns no
-- results rather than crashing.
DO $pgvec_setup$ DECLARE v_ok BOOLEAN := FALSE; BEGIN
    BEGIN
        CREATE EXTENSION IF NOT EXISTS vector;
        v_ok := TRUE;
    EXCEPTION WHEN OTHERS THEN
        RAISE NOTICE 'pgvector not available (%), embedding tables skipped', SQLERRM;
    END;
    IF NOT v_ok THEN RETURN; END IF;

    EXECUTE $T$
        CREATE TABLE IF NOT EXISTS memory_embeddings (
            point_id      BIGINT PRIMARY KEY,
            embedding     halfvec(__EMBED_DIM__),
            record_type   TEXT NOT NULL DEFAULT '',
            primary_scope TEXT NOT NULL DEFAULT '',
            workspace     TEXT NOT NULL DEFAULT '',
            project       TEXT NOT NULL DEFAULT '',
            kind          TEXT NOT NULL DEFAULT '',
            payload_json  TEXT NOT NULL DEFAULT ''
        )
    $T$;

    EXECUTE $T$
        CREATE TABLE IF NOT EXISTS kb_embeddings (
            point_id     BIGINT PRIMARY KEY,
            embedding    halfvec(__EMBED_DIM__),
            project      TEXT NOT NULL DEFAULT '',
            payload_json TEXT NOT NULL DEFAULT ''
        )
    $T$;

    -- kb_pdf_embeddings: PDF chunk vectors live in a DEDICATED relation that the
    -- general /v1/search transport NEVER reads (structured-PDF Phase A1). This is
    -- *structural* isolation, not a runtime WHERE doc_kind='pdf' filter on the
    -- shared kb_embeddings table: a query-time predicate is a data-classification
    -- filter, not an access boundary, and a future code path that forgets it would
    -- leak withheld PDF content into general vector search. By giving PDF vectors
    -- their own relation, the isolation is enforced by the schema/module boundary.
    -- point_id = the kb_documents.id of the PDF chunk (same identity space as
    -- kb_embeddings, but a disjoint table). The quarantine_state<>'pending'
    -- predicate rides INSIDE the PDF search surface (kb_payload.c) as
    -- defense-in-depth. ENGINE-LEVEL BACKSTOP (RT2-S1, deploy-gate): in a hardened
    -- deploy the general-search DB role should hold no grant on this relation (and/
    -- or a row-security policy enforces tenancy) so the boundary survives a
    -- mis-written JOIN even if the app layer fails. aimee-kb today connects as a
    -- single owner role, so that GRANT/RLS split is provisioned at deploy, not here;
    -- the structural separation above is the in-code, test-covered control.
    EXECUTE $T$
        CREATE TABLE IF NOT EXISTS kb_pdf_embeddings (
            point_id     BIGINT PRIMARY KEY,
            embedding    halfvec(__EMBED_DIM__),
            project      TEXT NOT NULL DEFAULT '',
            payload_json TEXT NOT NULL DEFAULT ''
        )
    $T$;

    -- curator_entity_vectors: pgvector embeddings for deep-curator entity
    -- resolution (resolve_entities pass). Mirrors kb_embeddings with the
    -- additional scope_kind / scope_id / canonical_name columns the curator
    -- needs for filtering candidate entities, plus artifact_id so a matched
    -- point_id can be reverse-mapped to its source entity artifact (used by
    -- the resolve_entities judge band and fuzzy contradiction mining).
    EXECUTE $T$
        CREATE TABLE IF NOT EXISTS curator_entity_vectors (
            point_id       BIGINT PRIMARY KEY,
            embedding      halfvec(__EMBED_DIM__),
            scope_kind     TEXT NOT NULL DEFAULT '',
            scope_id       TEXT NOT NULL DEFAULT '',
            canonical_name TEXT NOT NULL DEFAULT '',
            artifact_id    TEXT NOT NULL DEFAULT '',
            payload_json   TEXT NOT NULL DEFAULT ''
        )
    $T$;
    -- Back-fill the artifact_id column on databases created before it existed.
    EXECUTE $T$ ALTER TABLE curator_entity_vectors
                ADD COLUMN IF NOT EXISTS artifact_id TEXT NOT NULL DEFAULT '' $T$;

    -- curator_narrative_vectors: pgvector embeddings for deep-curator
    -- narrative store (one point per doc_summary / synthesis / open_question
    -- artifact) used for filter-first doc retrieval. Mirrors kb_embeddings
    -- with the additional artifact_id / kind / doc_id / status / priority
    -- columns the curator needs for filtering candidate documents.
    EXECUTE $T$
        CREATE TABLE IF NOT EXISTS curator_narrative_vectors (
            point_id     BIGINT PRIMARY KEY,
            embedding    halfvec(__EMBED_DIM__),
            artifact_id  TEXT NOT NULL DEFAULT '',
            kind         TEXT NOT NULL DEFAULT '',
            doc_id       TEXT NOT NULL DEFAULT '',
            status       TEXT NOT NULL DEFAULT '',
            priority     TEXT NOT NULL DEFAULT '',
            payload_json TEXT NOT NULL DEFAULT ''
        )
    $T$;

    -- curator_claim_vectors: pgvector embeddings for deep-curator claims
    -- store (one point per resolved claim artifact) used by detect_contradictions
    -- to match on subject+attribute (subj_attr_vec) and anti-match on the
    -- claim's value (value_vec). Two named vector columns per row, with
    -- artifact_id / subject / attribute / value / claim_kind for filtering
    -- and provenance.
    EXECUTE $T$
        CREATE TABLE IF NOT EXISTS curator_claim_vectors (
            point_id      BIGINT PRIMARY KEY,
            subj_attr_vec halfvec(__EMBED_DIM__),
            value_vec     halfvec(__EMBED_DIM__),
            artifact_id   TEXT NOT NULL DEFAULT '',
            subject       TEXT NOT NULL DEFAULT '',
            attribute     TEXT NOT NULL DEFAULT '',
            value         TEXT NOT NULL DEFAULT '',
            claim_kind    TEXT NOT NULL DEFAULT '',
            payload_json  TEXT NOT NULL DEFAULT ''
        )
    $T$;

    -- curator_code_unit_vectors: pgvector embeddings for deep-curator
    -- per-definition semantic code store. One point per resolved code
    -- definition (function/struct/typedef/etc.) with three named vector
    -- columns: intent_vec (what the definition is trying to do),
    -- signature_vec (the parameter/return shape), and body_vec (the
    -- implementation semantics). artifact_id / file_path / def_kind /
    -- signature / body_hash / payload_json carry provenance and lookup
    -- keys for the search path.
    EXECUTE $T$
        CREATE TABLE IF NOT EXISTS curator_code_unit_vectors (
            point_id      BIGINT PRIMARY KEY,
            intent_vec    halfvec(__EMBED_DIM__),
            signature_vec halfvec(__EMBED_DIM__),
            body_vec      halfvec(__EMBED_DIM__),
            artifact_id   TEXT NOT NULL DEFAULT '',
            file_path     TEXT NOT NULL DEFAULT '',
            def_kind      TEXT NOT NULL DEFAULT '',
            signature     TEXT NOT NULL DEFAULT '',
            body_hash     TEXT NOT NULL DEFAULT '',
            payload_json  TEXT NOT NULL DEFAULT ''
        )
    $T$;

    -- The embedding columns are halfvec(N) — fp16 — where N is the deployment's
    -- configured embedding_dim (a placeholder token in the column defs above is
    -- substituted at schema-apply time): 1024 for the default pplx-embed-v1-0.6b,
    -- 2560 for the pplx-embed-v1-4b. One embedder per deployment, so every column
    -- shares that one dimension. A fresh database gets it straight from the
    -- CREATE TABLE definitions above. We deliberately do NOT auto-alter an
    -- existing differently-typed column here (a routine schema-apply must never
    -- reshape the corpus); instead we surface a NOTICE:
    --   * a column still vector(N) (pre-halfvec) just needs an in-place cast —
    --     run deploy/migrations/2026-embed-halfvec.sql (no re-embed);
    --   * a column with a different DIMENSION (e.g. switching 0.6b<->4b, or old
    --     vector(384) all-MiniLM) additionally needs a re-embed at the new dim.
    -- Vector ops degrade (not crash) until then.
    DECLARE
        cur_type text;
    BEGIN
        SELECT format_type(atttypid, atttypmod) INTO cur_type
          FROM pg_attribute
         WHERE attrelid = 'memory_embeddings'::regclass
           AND attname = 'embedding' AND NOT attisdropped;
        IF cur_type IS NOT NULL AND cur_type <> 'halfvec(__EMBED_DIM__)' THEN
            RAISE NOTICE 'aimee: embedding columns are "%" but expected halfvec(__EMBED_DIM__). Run deploy/migrations/2026-embed-halfvec.sql to cast (no re-embed); if the dimension also differs, re-embed at the configured embedding_dim. Vector ops degraded until then — back up DB2 first.', cur_type;
        END IF;
    EXCEPTION WHEN OTHERS THEN
        RAISE NOTICE 'embedding dimension check skipped (%)', SQLERRM;
    END;

    EXECUTE $T$
        CREATE INDEX IF NOT EXISTS idx_memory_embeddings_record_type
            ON memory_embeddings (record_type)
    $T$;
    EXECUTE $T$
        CREATE INDEX IF NOT EXISTS idx_memory_embeddings_scope
            ON memory_embeddings (primary_scope, workspace, project)
    $T$;
    EXECUTE $T$
        CREATE INDEX IF NOT EXISTS idx_kb_embeddings_project
            ON kb_embeddings (project)
    $T$;
    EXECUTE $T$
        CREATE INDEX IF NOT EXISTS idx_kb_pdf_embeddings_project
            ON kb_pdf_embeddings (project)
    $T$;
    EXECUTE $T$
        CREATE INDEX IF NOT EXISTS idx_curator_entity_vectors_scope
            ON curator_entity_vectors (scope_kind, scope_id)
    $T$;
    EXECUTE $T$
        CREATE INDEX IF NOT EXISTS idx_curator_narrative_vectors_kind
            ON curator_narrative_vectors (kind, status, priority)
    $T$;
    EXECUTE $T$
        CREATE INDEX IF NOT EXISTS idx_curator_claim_vectors_kind
            ON curator_claim_vectors (claim_kind)
    $T$;
    EXECUTE $T$
        CREATE INDEX IF NOT EXISTS idx_curator_code_unit_vectors_kind
            ON curator_code_unit_vectors (def_kind)
    $T$;

    BEGIN
        EXECUTE $T$
            CREATE INDEX IF NOT EXISTS idx_memory_embeddings_hnsw
                ON memory_embeddings USING hnsw (embedding halfvec_cosine_ops)
        $T$;
    EXCEPTION WHEN OTHERS THEN
        RAISE NOTICE 'memory_embeddings HNSW index skipped (%)', SQLERRM;
    END;
    BEGIN
        EXECUTE $T$
            CREATE INDEX IF NOT EXISTS idx_kb_embeddings_hnsw
                ON kb_embeddings USING hnsw (embedding halfvec_cosine_ops)
        $T$;
    EXCEPTION WHEN OTHERS THEN
        RAISE NOTICE 'kb_embeddings HNSW index skipped (%)', SQLERRM;
    END;
    BEGIN
        EXECUTE $T$
            CREATE INDEX IF NOT EXISTS idx_kb_pdf_embeddings_hnsw
                ON kb_pdf_embeddings USING hnsw (embedding halfvec_cosine_ops)
        $T$;
    EXCEPTION WHEN OTHERS THEN
        RAISE NOTICE 'kb_pdf_embeddings HNSW index skipped (%)', SQLERRM;
    END;
    BEGIN
        EXECUTE $T$
            CREATE INDEX IF NOT EXISTS idx_curator_entity_vectors_hnsw
                ON curator_entity_vectors USING hnsw (embedding halfvec_cosine_ops)
        $T$;
    EXCEPTION WHEN OTHERS THEN
        RAISE NOTICE 'curator_entity_vectors HNSW index skipped (%)', SQLERRM;
    END;
    BEGIN
        EXECUTE $T$
            CREATE INDEX IF NOT EXISTS idx_curator_narrative_vectors_hnsw
                ON curator_narrative_vectors USING hnsw (embedding halfvec_cosine_ops)
        $T$;
    EXCEPTION WHEN OTHERS THEN
        RAISE NOTICE 'curator_narrative_vectors HNSW index skipped (%)', SQLERRM;
    END;
    BEGIN
        EXECUTE $T$
            CREATE INDEX IF NOT EXISTS idx_curator_claim_vectors_subj_attr_hnsw
                ON curator_claim_vectors USING hnsw (subj_attr_vec halfvec_cosine_ops)
        $T$;
    EXCEPTION WHEN OTHERS THEN
        RAISE NOTICE 'curator_claim_vectors subj_attr HNSW index skipped (%)', SQLERRM;
    END;
    BEGIN
        EXECUTE $T$
            CREATE INDEX IF NOT EXISTS idx_curator_claim_vectors_value_hnsw
                ON curator_claim_vectors USING hnsw (value_vec halfvec_cosine_ops)
        $T$;
    EXCEPTION WHEN OTHERS THEN
        RAISE NOTICE 'curator_claim_vectors value HNSW index skipped (%)', SQLERRM;
    END;
    BEGIN
        EXECUTE $T$
            CREATE INDEX IF NOT EXISTS idx_curator_code_unit_vectors_intent_hnsw
                ON curator_code_unit_vectors USING hnsw (intent_vec halfvec_cosine_ops)
        $T$;
    EXCEPTION WHEN OTHERS THEN
        RAISE NOTICE 'curator_code_unit_vectors intent HNSW index skipped (%)', SQLERRM;
    END;
    BEGIN
        EXECUTE $T$
            CREATE INDEX IF NOT EXISTS idx_curator_code_unit_vectors_signature_hnsw
                ON curator_code_unit_vectors USING hnsw (signature_vec halfvec_cosine_ops)
        $T$;
    EXCEPTION WHEN OTHERS THEN
        RAISE NOTICE 'curator_code_unit_vectors signature HNSW index skipped (%)', SQLERRM;
    END;
    BEGIN
        EXECUTE $T$
            CREATE INDEX IF NOT EXISTS idx_curator_code_unit_vectors_body_hnsw
                ON curator_code_unit_vectors USING hnsw (body_vec halfvec_cosine_ops)
        $T$;
    EXCEPTION WHEN OTHERS THEN
        RAISE NOTICE 'curator_code_unit_vectors body HNSW index skipped (%)', SQLERRM;
    END;

    -- exemplar_vectors: pgvector embeddings for case artifact exemplar recall.
    -- See docs/proposals/accepted/graph-reasoning-case-based-recall-and-contradiction-logic.md
    BEGIN
        EXECUTE $T$
            CREATE TABLE IF NOT EXISTS exemplar_vectors (
                id          BIGSERIAL PRIMARY KEY,
                artifact_id TEXT      NOT NULL REFERENCES artifacts(id) ON DELETE CASCADE,
                collection  TEXT      NOT NULL DEFAULT 'case_exemplars',
                embedding   halfvec(__EMBED_DIM__),
                created_at  TEXT      NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS'))
            )
        $T$;
        EXECUTE $T$
            CREATE INDEX IF NOT EXISTS idx_exemplar_vectors_artifact_id
                ON exemplar_vectors (artifact_id)
        $T$;
        EXECUTE $T$
            CREATE INDEX IF NOT EXISTS idx_exemplar_vectors_collection
                ON exemplar_vectors (collection)
        $T$;
    EXCEPTION WHEN OTHERS THEN
        RAISE NOTICE 'exemplar_vectors table skipped (%)', SQLERRM;
    END;

    -- evidence_vectors: pgvector embeddings over the non-doc evidence layer
    -- (session/feedback/tool-outcome/guardrail rows) for the learning
    -- neighbourhood builder. The embed-ops queue is evidence_index_ops (plain).
    -- See docs/proposals/pending/cross-source-learning-pipeline.md
    BEGIN
        EXECUTE $T$
            CREATE TABLE IF NOT EXISTS evidence_vectors (
                id          BIGSERIAL PRIMARY KEY,
                artifact_id TEXT      NOT NULL REFERENCES artifacts(id) ON DELETE CASCADE,
                collection  TEXT      NOT NULL DEFAULT 'evidence',
                embedding   halfvec(__EMBED_DIM__),
                created_at  TEXT      NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS'))
            )
        $T$;
        EXECUTE $T$
            CREATE INDEX IF NOT EXISTS idx_evidence_vectors_artifact_id
                ON evidence_vectors (artifact_id)
        $T$;
        EXECUTE $T$
            CREATE INDEX IF NOT EXISTS idx_evidence_vectors_collection
                ON evidence_vectors (collection)
        $T$;
    EXCEPTION WHEN OTHERS THEN
        RAISE NOTICE 'evidence_vectors table skipped (%)', SQLERRM;
    END;
    -- Phase 5: code_embeddings — code-unit vector table for code vector recall.
    BEGIN
        EXECUTE $T$
            CREATE TABLE IF NOT EXISTS code_embeddings (
                point_id     BIGINT PRIMARY KEY,
                embedding    halfvec(__EMBED_DIM__),
                project      TEXT NOT NULL DEFAULT '',
                generation   BIGINT NOT NULL DEFAULT 1 CHECK (generation > 0),
                node_key     TEXT NOT NULL DEFAULT '',
                file_path    TEXT NOT NULL DEFAULT '',
                symbol       TEXT NOT NULL DEFAULT '',
                record_type  TEXT NOT NULL DEFAULT 'code_unit',
                content_hash TEXT NOT NULL DEFAULT '',
                body_hash    TEXT NOT NULL DEFAULT '',
                source_hash  TEXT NOT NULL DEFAULT '',
                payload_json TEXT NOT NULL DEFAULT '',
                updated_at   TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS'))
            )
        $T$;
        EXECUTE $T$
            ALTER TABLE code_embeddings ADD COLUMN IF NOT EXISTS body_hash TEXT NOT NULL DEFAULT ''
        $T$;
        IF NOT EXISTS (
            SELECT 1 FROM information_schema.columns
             WHERE table_schema = current_schema() AND table_name = 'code_embeddings'
               AND column_name = 'generation'
        ) THEN
            EXECUTE $T$
                ALTER TABLE code_embeddings ADD COLUMN generation BIGINT NOT NULL DEFAULT 1
                  CHECK (generation > 0)
            $T$;
            EXECUTE $T$
                UPDATE code_embeddings ce SET generation = p.current_generation
                  FROM projects p WHERE p.name = ce.project
            $T$;
        END IF;
        EXECUTE $T$
            CREATE INDEX IF NOT EXISTS idx_code_embeddings_project
                ON code_embeddings(project)
        $T$;
        EXECUTE 'DROP INDEX IF EXISTS idx_code_embeddings_node';
        EXECUTE $T$
            CREATE INDEX IF NOT EXISTS idx_code_embeddings_node
                ON code_embeddings(project, generation, node_key)
        $T$;
        EXECUTE 'DROP INDEX IF EXISTS idx_code_embeddings_hash';
        EXECUTE $T$
            CREATE UNIQUE INDEX IF NOT EXISTS idx_code_embeddings_hash
                ON code_embeddings(project, generation, node_key, content_hash)
        $T$;
        EXECUTE $T$
            CREATE INDEX IF NOT EXISTS idx_code_embeddings_body_hash
                ON code_embeddings(project, body_hash)
        $T$;
    EXCEPTION WHEN OTHERS THEN
        RAISE NOTICE 'code_embeddings table skipped (%)', SQLERRM;
    END;
    BEGIN
        EXECUTE $T$
            CREATE INDEX IF NOT EXISTS idx_code_embeddings_hnsw
                ON code_embeddings USING hnsw (embedding halfvec_cosine_ops)
        $T$;
    EXCEPTION WHEN OTHERS THEN
        RAISE NOTICE 'code_embeddings HNSW index skipped (%)', SQLERRM;
    END;
END $pgvec_setup$;

/* ---- graph reasoning: ruleset registry and case view ---- */
CREATE TABLE IF NOT EXISTS reasoning_rulesets (
    id           TEXT NOT NULL PRIMARY KEY,
    version      INT NOT NULL DEFAULT 1,
    name         TEXT NOT NULL DEFAULT '',
    content_hash TEXT NOT NULL DEFAULT '',
    active       BOOLEAN NOT NULL DEFAULT TRUE,
    rules        JSONB NOT NULL DEFAULT '[]',
    created_at   TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS'))
);
CREATE INDEX IF NOT EXISTS idx_reasoning_rulesets_active ON reasoning_rulesets (active, name);

CREATE OR REPLACE VIEW cases AS
    SELECT * FROM artifacts WHERE kind = 'case';

-- Phase 0: effectiveness-weighted code vector graph shadow-delta table.
-- Stores bounded top-K rank deltas for shadow-mode fused scoring vs baseline.
-- Retention capped at 10,000 rows or 14 days (whichever is smaller) by a
-- periodic maintenance job. delta_json contains compact deltas only: result
-- id/key, baseline rank, fused rank, score delta, and reason flags.
CREATE TABLE IF NOT EXISTS memory_recall_shadow_deltas (
    id           BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
    query_hash   TEXT NOT NULL,
    project      TEXT NOT NULL DEFAULT '',
    mode         TEXT NOT NULL DEFAULT 'shadow',
    result_count BIGINT NOT NULL DEFAULT 0,
    delta_json   TEXT NOT NULL DEFAULT '{}',
    created_at   TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS'))
);
CREATE INDEX IF NOT EXISTS idx_mrsd_query_created
    ON memory_recall_shadow_deltas(query_hash, created_at);
CREATE INDEX IF NOT EXISTS idx_mrsd_project_created
    ON memory_recall_shadow_deltas(project, created_at);

-- Phase 1: entity edge uniqueness migration — new columns on entity_edges.
-- utility_touched_at: wall-clock timestamp of last utility_score change.
-- structural_weight:  trust weight from deterministic code-index extraction.
-- edge_origin:        provenance tag ('session', 'code_projection', etc.).
ALTER TABLE entity_edges ADD COLUMN IF NOT EXISTS utility_touched_at TEXT NOT NULL DEFAULT '';
ALTER TABLE entity_edges ADD COLUMN IF NOT EXISTS structural_weight INTEGER NOT NULL DEFAULT 0;
ALTER TABLE entity_edges ADD COLUMN IF NOT EXISTS edge_origin TEXT NOT NULL DEFAULT 'session';
-- edge_class: discriminates typed-fact 'semantic' edges from legacy 'cooccurrence'
-- rows that share this table (typed-fact §1 / P1, R1-A1 storage boundary). Recall
-- paths filter on it; the typed write gate sets it to 'semantic'.
ALTER TABLE entity_edges ADD COLUMN IF NOT EXISTS edge_class TEXT NOT NULL DEFAULT 'cooccurrence';
-- typed-fact §4/§5 (P3): provenance-keyed confidence class (A/B/C) + numeric band,
-- and bitemporal transaction-time on semantic edges (asserted_at..superseded_at;
-- superseded_at='' = currently believed) plus a hard_delete tombstone (suppressed).
-- valid_from/valid_until (already present) carry valid-time. Defaults match a
-- Class C speculation so untyped/legacy rows read as the most conservative class.
ALTER TABLE entity_edges ADD COLUMN IF NOT EXISTS confidence_class TEXT NOT NULL DEFAULT 'C'
  CHECK (confidence_class IN ('A', 'B', 'C'));
ALTER TABLE entity_edges ADD COLUMN IF NOT EXISTS confidence DOUBLE PRECISION NOT NULL DEFAULT 0.4;
ALTER TABLE entity_edges ADD COLUMN IF NOT EXISTS asserted_at TEXT NOT NULL DEFAULT '';
ALTER TABLE entity_edges ADD COLUMN IF NOT EXISTS superseded_at TEXT NOT NULL DEFAULT '';
ALTER TABLE entity_edges ADD COLUMN IF NOT EXISTS suppressed BIGINT NOT NULL DEFAULT 0;

-- rel_types: the typed-relationship ontology (typed-fact §1 / P1). The live
-- overlay of the in-code SEED_ONTOLOGY; carries promoted/provisional (§2) types.
CREATE TABLE IF NOT EXISTS rel_types (
  id BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  rel_type TEXT NOT NULL UNIQUE,
  head_kinds TEXT NOT NULL DEFAULT '',
  tail_kinds TEXT NOT NULL DEFAULT '',
  is_symmetric BIGINT NOT NULL DEFAULT 0,
  inverse_rel_type TEXT NOT NULL DEFAULT '',
  correction_behavior TEXT NOT NULL DEFAULT 'supersede',
  category TEXT NOT NULL DEFAULT '',
  sensitivity TEXT NOT NULL DEFAULT 'pii',
  is_hierarchy_rel BIGINT NOT NULL DEFAULT 0,
  status TEXT NOT NULL DEFAULT 'active');

-- ontology_evaluations: self-extending ontology promotion pipeline (typed-fact
-- §2 / P4). Each novel rel_type the gate sees increments occurrence_count; once
-- it crosses a threshold the model evaluates it and the decision is recorded
-- here (approved -> rel_type promoted to active; mapped -> aliased onto mapped_to;
-- rejected). mapped_to holds the canonical rel_type when status='mapped'.
CREATE TABLE IF NOT EXISTS ontology_evaluations (
  id BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  rel_type TEXT NOT NULL UNIQUE,
  occurrence_count BIGINT NOT NULL DEFAULT 0,
  status TEXT NOT NULL DEFAULT 'pending'
    CHECK (status IN ('pending', 'approved', 'mapped', 'rejected')),
  mapped_to TEXT NOT NULL DEFAULT '',
  decided_at TEXT NOT NULL DEFAULT '',
  created_at TEXT NOT NULL DEFAULT '');

-- entity_registry / entity_aliases: surrogate-id entity canonicalization
-- (typed-fact §3 / P2). canonical_id is a globally-unique surrogate PK; aliases
-- map a normalized display name -> canonical id (single-hop, UNIQUE name_norm).
CREATE TABLE IF NOT EXISTS entity_registry (
  canonical_id BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  kind BIGINT NOT NULL DEFAULT 99,
  status TEXT NOT NULL DEFAULT 'active',
  merged_into BIGINT NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS entity_aliases (
  id BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  name TEXT NOT NULL DEFAULT '',
  name_norm TEXT NOT NULL UNIQUE,
  canonical_id BIGINT NOT NULL,
  is_preferred BIGINT NOT NULL DEFAULT 0,
  suppressed BIGINT NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS idx_entity_aliases_cid ON entity_aliases(canonical_id);

-- entity_merges / entity_name_conflicts: merge audit (enables unmerge) + the
-- true-ambiguity queue (typed-fact §3 / P2b).
CREATE TABLE IF NOT EXISTS entity_merges (
  id BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  from_id BIGINT NOT NULL,
  into_id BIGINT NOT NULL,
  undone BIGINT NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS entity_name_conflicts (
  id BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  name_norm TEXT NOT NULL UNIQUE,
  status TEXT NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'resolved', 'failed')),
  priority BIGINT NOT NULL DEFAULT 1,
  retries BIGINT NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL DEFAULT '');

-- Phase 2: canonical graph node dictionary and legacy alias bridge.
CREATE TABLE IF NOT EXISTS entity_nodes (
    node_key     TEXT PRIMARY KEY,
    node_kind    INTEGER NOT NULL DEFAULT 0,
    project      TEXT NOT NULL DEFAULT '',
    display_name TEXT NOT NULL DEFAULT '',
    full_key     TEXT NOT NULL DEFAULT '',
    file_path    TEXT NOT NULL DEFAULT '',
    symbol       TEXT NOT NULL DEFAULT '',
    node_origin  TEXT NOT NULL DEFAULT '',
    last_seen_generation_id BIGINT NOT NULL DEFAULT 0,
    created_at   TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS')),
    updated_at   TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS'))
);
CREATE INDEX IF NOT EXISTS idx_entity_nodes_project ON entity_nodes(project);
CREATE INDEX IF NOT EXISTS idx_entity_nodes_kind ON entity_nodes(node_kind);

CREATE TABLE IF NOT EXISTS entity_node_aliases (
    alias       TEXT NOT NULL,
    node_key    TEXT NOT NULL REFERENCES entity_nodes(node_key) ON DELETE CASCADE,
    alias_kind  TEXT NOT NULL DEFAULT '',
    project     TEXT NOT NULL DEFAULT '',
    last_seen_generation_id BIGINT NOT NULL DEFAULT 0,
    created_at  TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS')),
    PRIMARY KEY (alias, node_key)
);
CREATE INDEX IF NOT EXISTS idx_entity_node_aliases_alias
    ON entity_node_aliases(alias);
CREATE INDEX IF NOT EXISTS idx_entity_node_aliases_project_alias
    ON entity_node_aliases(project, alias);

-- Phase 3: code graph projection ledger.
-- code_projection_generations tracks one generation per project:
--   pending -> visible (on publish), pending -> aborted (on failure),
--   visible -> superseded (on next publish). At most one 'visible' per project.
CREATE TABLE IF NOT EXISTS code_projection_generations (
    id          BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
    project     TEXT NOT NULL,
    state       TEXT NOT NULL DEFAULT 'pending'
                    CHECK (state IN ('pending','visible','superseded','aborted')),
    source_hash TEXT NOT NULL DEFAULT '',
    edge_count  BIGINT NOT NULL DEFAULT 0,
    node_count  BIGINT NOT NULL DEFAULT 0,
    started_at  TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS')),
    visible_at  TEXT NOT NULL DEFAULT '',
    aborted_at  TEXT NOT NULL DEFAULT '',
    error       TEXT NOT NULL DEFAULT '',
    -- graph-feedback S2: the aimee build that produced this generation, so the
    -- snapshot-diff route can refuse to compare two generations whose extractor
    -- differs (a parser change would read as a structural change). Empty on
    -- generations created before this column existed.
    extractor_version TEXT NOT NULL DEFAULT '',
    pipeline_version  TEXT NOT NULL DEFAULT ''
);
CREATE INDEX IF NOT EXISTS idx_cpg_project_state
    ON code_projection_generations(project, state);
CREATE UNIQUE INDEX IF NOT EXISTS idx_cpg_one_visible_project
    ON code_projection_generations(project)
    WHERE state = 'visible';

-- Mutation bookkeeping: projected-edge membership per generation.
-- Not joined in hot recall path; used for publish, rollback, and cleanup.
CREATE TABLE IF NOT EXISTS code_projection_edges (
    generation_id BIGINT NOT NULL REFERENCES code_projection_generations(id)
        ON DELETE CASCADE,
    project       TEXT NOT NULL,
    source        TEXT NOT NULL,
    relation      TEXT NOT NULL,
    target        TEXT NOT NULL,
    source_hash   TEXT NOT NULL DEFAULT '',
    PRIMARY KEY (generation_id, source, relation, target)
);
CREATE INDEX IF NOT EXISTS idx_cpe_project_triple
    ON code_projection_edges(project, source, relation, target);

-- graph-feedback S-community: deterministic community membership per generation.
-- Persisted for EVERY generated projection (keyed by generation_id, not only the
-- visible one) so a later slice can diff arbitrary generations. community_id is
-- the min-member node id (lex) and is GENERATION-LOCAL by contract (cross-gen
-- stable remap is a later slice). Retention follows the generation cleanup
-- schedule via ON DELETE CASCADE.
CREATE TABLE IF NOT EXISTS code_projection_communities (
    generation_id BIGINT NOT NULL REFERENCES code_projection_generations(id)
        ON DELETE CASCADE,
    project       TEXT NOT NULL,
    node_id       TEXT NOT NULL,
    community_id  TEXT NOT NULL,
    PRIMARY KEY (generation_id, node_id)
);
CREATE INDEX IF NOT EXISTS idx_cpc_gen_community
    ON code_projection_communities(generation_id, community_id);

-- ── graph-feedback S3: retrieval-outcome ledger ─────────────────────────────
-- Records which of the graph's own answers earned trust (proposal §3). ISOLATED
-- from the memory-fact graph on purpose: the lessons_ prefix is skipped by
-- db2_memory_find_facts_like and the fact decay/prune sweep — enforced by
-- scripts/check-lessons-isolation.py — so outcomes never leak into normal recall
-- or get pruned out from under the learning loop. Immutable + append-only: the
-- trigger forbids DELETE/TRUNCATE and forbids UPDATE of everything except the
-- confirmation columns (confirmed/confirmed_by/confirmed_at). The trigger permits
-- ANY caller to flip `confirmed` — the *authority* gate ("only a user/reviewer
-- confirmation is durable") is an application-layer check in S3c, not DB-enforced,
-- because the DB can't see the actor's role; an agent-set confirmation stays inert
-- until S3c's actor model accepts it.
CREATE TABLE IF NOT EXISTS lessons_outcome_ledger (
    id              BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
    session_id      TEXT NOT NULL DEFAULT '',
    turn_id         TEXT NOT NULL DEFAULT '',
    project_id      TEXT NOT NULL DEFAULT '',
    generation_id   BIGINT NOT NULL DEFAULT 0,   -- branch/generation the answer was against
    answer_outcome  TEXT NOT NULL
                        CHECK (answer_outcome IN ('useful','dead_end','corrected')),
    correction_text TEXT NOT NULL DEFAULT '',
    finding_id      TEXT NOT NULL DEFAULT '',     -- §1<->§3 loop: verdict on an audit finding
    actor_id        TEXT NOT NULL DEFAULT '',
    actor_source    TEXT NOT NULL DEFAULT 'agent'
                        CHECK (actor_source IN ('user','reviewer','agent')),
    confirmed       INTEGER NOT NULL DEFAULT 0,   -- 0/1; gates durable negative trust (S3c)
    confirmed_by    TEXT NOT NULL DEFAULT '',
    confirmed_at    TEXT NOT NULL DEFAULT '',
    ts              TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS'))
);
CREATE INDEX IF NOT EXISTS idx_lessons_ledger_project ON lessons_outcome_ledger(project_id);
CREATE INDEX IF NOT EXISTS idx_lessons_ledger_finding ON lessons_outcome_ledger(finding_id);

-- Per-citation dispositions (the cited_node_ids[] + per_citation_disposition[] of
-- the §3 record). Insert-only; cascades are inert because the ledger can't be
-- deleted (belt-and-suspenders).
CREATE TABLE IF NOT EXISTS lessons_outcome_citations (
    outcome_id  BIGINT NOT NULL REFERENCES lessons_outcome_ledger(id) ON DELETE CASCADE,
    node_id     TEXT NOT NULL,
    disposition TEXT NOT NULL DEFAULT 'unused'
                    CHECK (disposition IN ('useful','stale','unused')),
    PRIMARY KEY (outcome_id, node_id)
);

CREATE OR REPLACE FUNCTION lessons_ledger_immutable() RETURNS trigger AS $$
BEGIN
  IF (TG_OP = 'DELETE' OR TG_OP = 'TRUNCATE') THEN
    RAISE EXCEPTION 'lessons_outcome_ledger is append-only (% forbidden)', TG_OP;
  END IF;
  -- UPDATE: everything but the confirmation columns is immutable.
  IF ROW(NEW.id, NEW.session_id, NEW.turn_id, NEW.project_id, NEW.generation_id,
         NEW.answer_outcome, NEW.correction_text, NEW.finding_id, NEW.actor_id,
         NEW.actor_source, NEW.ts)
     IS DISTINCT FROM
     ROW(OLD.id, OLD.session_id, OLD.turn_id, OLD.project_id, OLD.generation_id,
         OLD.answer_outcome, OLD.correction_text, OLD.finding_id, OLD.actor_id,
         OLD.actor_source, OLD.ts) THEN
    RAISE EXCEPTION 'lessons_outcome_ledger is append-only (only confirmation may change)';
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_lessons_ledger_immutable ON lessons_outcome_ledger;
CREATE TRIGGER trg_lessons_ledger_immutable
  BEFORE UPDATE OR DELETE ON lessons_outcome_ledger
  FOR EACH ROW EXECUTE FUNCTION lessons_ledger_immutable();
-- TRUNCATE fires a statement-level trigger, not the row-level one above — guard it
-- separately or a TRUNCATE would silently wipe the append-only ledger.
DROP TRIGGER IF EXISTS trg_lessons_ledger_no_truncate ON lessons_outcome_ledger;
CREATE TRIGGER trg_lessons_ledger_no_truncate
  BEFORE TRUNCATE ON lessons_outcome_ledger
  FOR EACH STATEMENT EXECUTE FUNCTION lessons_ledger_immutable();

-- Phase 3: projection_generation_id on entity_edges links each code-origin
-- edge to its owning generation so recall can filter by visible generation.
ALTER TABLE entity_edges
    ADD COLUMN IF NOT EXISTS projection_generation_id BIGINT NOT NULL DEFAULT 0;
ALTER TABLE entity_edges
    ADD COLUMN IF NOT EXISTS structural_updated_at TEXT NOT NULL DEFAULT '';

-- Phase 4: composite indexes for utility-aware two-hop CTE expansion.
CREATE INDEX IF NOT EXISTS idx_ee_source_relation ON entity_edges(source, relation);
CREATE INDEX IF NOT EXISTS idx_ee_target_relation ON entity_edges(target, relation);
CREATE INDEX IF NOT EXISTS idx_ee_origin_source ON entity_edges(edge_origin, source);
CREATE INDEX IF NOT EXISTS idx_ee_projection_generation ON entity_edges(projection_generation_id, source, relation);

-- Cross-repo dependency graph (proposal docs/proposals/pending/cross-repo-dependency-graph.md).
-- S1 foundation: per-repo trust, a global version/epoch store, the corpus-derived blocked-symbol
-- set, the AMBIGUOUS review queue, and the trust-change audit log. Resolver/stats/orchestration
-- land in later slices. Dialect parity with src/db2/schema_sqlite.sql is at the table-set level
-- (schema-sync-check); intentional per-dialect deltas: timestamp exprs (to_char vs datetime('now')),
-- JSONB (Postgres) vs TEXT (sqlite) for `evidence`, identity vs AUTOINCREMENT primary keys.
--
-- Per-repo trust (§0): operator-registered repos default 'trusted'; any future non-operator
-- ingestion path (community ingest, bulk import, fixture/repair scripts) MUST insert 'untrusted'
-- explicitly -- the 'trusted' default is fail-open and only application discipline guards it today.
-- The CHECK keeps the column a closed enum (named for stable, idempotent migration); it is part of
-- the ADD COLUMN so the whole statement is guarded idempotently by IF NOT EXISTS.
ALTER TABLE projects
    ADD COLUMN IF NOT EXISTS trust TEXT NOT NULL DEFAULT 'trusted'
        CONSTRAINT projects_trust_chk CHECK (trust IN ('trusted', 'untrusted'));
CREATE INDEX IF NOT EXISTS idx_projects_trust ON projects(trust);

-- cross_repo_meta (§4.1): single-row global version/epoch store backing the input-freshness stamp
-- (canonical_index_generation [from code_projection_generations], repo_set_hash, trust_epoch).
-- trust_epoch is the monotonic counter S7 atomically reads + bumps (UPDATE ... SET trust_epoch =
-- trust_epoch + 1 in one txn) on any projects.trust change; blocked_symbols_version is bumped by S3's
-- blocked_symbols recompute. The counters are NOT NULL DEFAULT 0 with a >= 0 CHECK so a NULL or
-- negative value can never silently break the monotonic-bump invariant. CHECK (id = 1) pins one row.
CREATE TABLE IF NOT EXISTS cross_repo_meta (
    id                      INTEGER PRIMARY KEY CHECK (id = 1),
    trust_epoch             BIGINT NOT NULL DEFAULT 0 CHECK (trust_epoch >= 0),
    repo_set_hash           TEXT NOT NULL DEFAULT '',
    blocked_symbols_version BIGINT NOT NULL DEFAULT 0 CHECK (blocked_symbols_version >= 0),
    updated_at              TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS'))
);
-- DO NOTHING is deliberate: it only guarantees the singleton row exists. On schema re-apply it must
-- NOT clobber the live runtime-mutated counters (trust_epoch/repo_set_hash/blocked_symbols_version);
-- a DO UPDATE that reset them to defaults would destroy monotonicity. All columns are runtime-owned
-- after creation, so there is nothing seed-owned to refresh.
INSERT INTO cross_repo_meta (id) VALUES (1) ON CONFLICT (id) DO NOTHING;
-- S4b: cumulative count of AMBIGUOUS review-queue rows evicted on overflow (§3.8),
-- surfaced as overflow.dropped. ALTER (not in the CREATE) so it lands on the
-- existing single-row table from S1.
ALTER TABLE cross_repo_meta
    ADD COLUMN IF NOT EXISTS review_overflow_dropped BIGINT NOT NULL DEFAULT 0;

-- blocked_symbols (§3.3): corpus-derived non-distinctive set, recomputed over trusted repos only.
-- Replaces the static blocklist; `version` lets a tier decision replay against the exact frequency
-- model (blocked_symbols_version, see cross_repo_meta) that produced it. `lang` '' = all languages
-- (a per-language entry uses the concrete lang tag). created_at/updated_at support stale cleanup.
CREATE TABLE IF NOT EXISTS blocked_symbols (
    word       TEXT NOT NULL,
    lang       TEXT NOT NULL DEFAULT '',
    reason     TEXT NOT NULL DEFAULT '',
    version    BIGINT NOT NULL DEFAULT 0,
    created_at TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS')),
    updated_at TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS')),
    PRIMARY KEY (word, lang)
);
CREATE INDEX IF NOT EXISTS idx_blocked_symbols_version ON blocked_symbols(version);

-- cross_repo_review_queue (§3.8): AMBIGUOUS candidates surfaced (not dropped). The fingerprint
-- (repo_set_hash, symbol, caller_repo, candidate_definer) is UNIQUE so re-resolution upserts the
-- evidence rather than duplicating -- all four are NOT NULL (Postgres treats NULLs as distinct, so
-- a nullable fingerprint column would silently defeat the constraint). Eviction on overflow is
-- deterministic by (evidence_score ASC, arrival_seq ASC) over status='open'. review_class is a
-- closed enum: 'ambiguous' (default) or 'ffi' (the §3.7 cross-language discriminator); cross_lang
-- is a 0/1 boolean flag (BIGINT for sqlite-dialect parity). evidence is JSONB on Postgres for
-- insert-time validation + field-level S3/S4 queries (TEXT in the sqlite shim). No FKs to projects:
-- caller_repo/candidate_definer are repo *names*, not ids, so queue + audit rows survive a repo
-- deletion (orphans are tolerated and pruned on the next re-resolution of that repo_set_hash).
CREATE TABLE IF NOT EXISTS cross_repo_review_queue (
    id                BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
    repo_set_hash     TEXT NOT NULL DEFAULT '',
    symbol            TEXT NOT NULL,
    caller_repo       TEXT NOT NULL,
    candidate_definer TEXT NOT NULL DEFAULT '',
    evidence          JSONB NOT NULL DEFAULT '{}'::jsonb,
    evidence_score    DOUBLE PRECISION NOT NULL DEFAULT 0.0,
    arrival_seq       BIGINT NOT NULL DEFAULT 0,
    status            TEXT NOT NULL DEFAULT 'open'
                          CHECK (status IN ('open', 'accepted', 'rejected')),
    review_class      TEXT NOT NULL DEFAULT 'ambiguous'
                          CHECK (review_class IN ('ambiguous', 'ffi')),
    cross_lang        BIGINT NOT NULL DEFAULT 0,
    created_at        TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS')),
    updated_at        TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS')),
    UNIQUE (repo_set_hash, symbol, caller_repo, candidate_definer)
);
-- Partial index for the queue-worker / eviction scan (WHERE status='open' ORDER BY evidence_score,
-- arrival_seq); the low-cardinality standalone status index is intentionally omitted. idx_crrq_caller
-- covers "open entries for a caller" (the --review-by-project path).
CREATE INDEX IF NOT EXISTS idx_crrq_evict_open ON cross_repo_review_queue(evidence_score, arrival_seq)
    WHERE status = 'open';
CREATE INDEX IF NOT EXISTS idx_crrq_caller ON cross_repo_review_queue(caller_repo, status);

-- cross_repo_trust_audit (§0 authz): durable audit of every projects.trust change (admin-gated,
-- CAP_INDEX_ADMIN). Records actor, prior->new trust, trust_epoch before/after, repo_set_hash,
-- request id, timestamp for post-incident attribution of this security-relevant state change.
-- prior_trust allows '' for the first-set case (no prior value); new_trust mirrors the enum.
CREATE TABLE IF NOT EXISTS cross_repo_trust_audit (
    id                 BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
    project            TEXT NOT NULL,
    actor              TEXT NOT NULL DEFAULT '',
    prior_trust        TEXT NOT NULL DEFAULT '' CHECK (prior_trust IN ('', 'trusted', 'untrusted')),
    new_trust          TEXT NOT NULL DEFAULT '' CHECK (new_trust IN ('', 'trusted', 'untrusted')),
    trust_epoch_before BIGINT NOT NULL DEFAULT 0,
    trust_epoch_after  BIGINT NOT NULL DEFAULT 0,
    repo_set_hash      TEXT NOT NULL DEFAULT '',
    request_id         TEXT NOT NULL DEFAULT '',
    created_at         TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS'))
);
CREATE INDEX IF NOT EXISTS idx_crta_project ON cross_repo_trust_audit(project, created_at);

-- cross_repo_identity (H0c, precision-hardening §1.5): the identities each repo PROVIDES — the
-- package/module/build-target names a cross-repo import/link directive resolves against. Built at
-- index time from manifests (Cargo/go.mod/package.json/pyproject/CMakeLists/*.pc). kind in
-- {crate,gomod,npm,pypi,cmake_project,cmake_target,pkgconfig}; idx_cri_lookup serves the
-- directive->repo reverse lookup (H1 structural-edge resolution).
CREATE TABLE IF NOT EXISTS cross_repo_identity (
    id      BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
    project TEXT NOT NULL,
    kind    TEXT NOT NULL,
    value   TEXT NOT NULL,
    UNIQUE (project, kind, value)
);
CREATE INDEX IF NOT EXISTS idx_cri_lookup ON cross_repo_identity(kind, value);

-- cross_repo_route (H0d, precision-hardening §1): the inter-repo STRUCTURAL-EDGE adjacency — for an
-- ordered pair (caller -> definer) it records that caller A has an import/include/link directive that
-- resolves into definer repo B. H1 makes "A has a route to B" a hard prerequisite for any non-LOW
-- cross-repo edge. kind: 'import_module' (a module/package specifier matched to B's cross_repo_identity
-- — manifest-authoritative, HIGH) or 'import_header' (a C/C++ #include matched to a B file basename —
-- MEDIUM until H1's repo-unique refinement). Built at index time from file_imports + cross_repo_identity
-- + files; vendored definers excluded (H0b flag).
CREATE TABLE IF NOT EXISTS cross_repo_route (
    id              BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
    caller_project  TEXT NOT NULL,
    definer_project TEXT NOT NULL,
    kind            TEXT NOT NULL,
    confidence      TEXT NOT NULL DEFAULT 'medium',
    evidence        TEXT NOT NULL DEFAULT '',
    UNIQUE (caller_project, definer_project, kind, evidence)
);
CREATE INDEX IF NOT EXISTS idx_crr_caller ON cross_repo_route(caller_project);
CREATE INDEX IF NOT EXISTS idx_crr_definer ON cross_repo_route(definer_project);

-- cross_repo_build_dep (recall-recovery R2): build-DECLARED cross-repo deps — A's build files declare a
-- dependency on corpus repo B (CMake FetchContent GIT_REPOSITORY, git submodule, Cargo git/path). A
-- separate evidence class from cross_repo_route (the symbol-graph): the resolver merges these as
-- evidence_type=build_declared, NOT via the H1 symbol-route gate. build_kind:
-- 'fetchcontent'|'submodule'|'manifest'. parse_confidence 'high' (resolved URL/path) | 'low'
-- (${VAR}/generator-expr). Built at index time from indexed manifest file_contents (R2a).
CREATE TABLE IF NOT EXISTS cross_repo_build_dep (
    id               BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
    caller_project   TEXT NOT NULL,
    definer_project  TEXT NOT NULL,
    build_kind       TEXT NOT NULL DEFAULT '',
    parse_confidence TEXT NOT NULL DEFAULT 'high',
    evidence         TEXT NOT NULL DEFAULT '',
    UNIQUE (caller_project, definer_project, build_kind, evidence)
);
CREATE INDEX IF NOT EXISTS idx_crbd_caller ON cross_repo_build_dep(caller_project);

-- CSS migration assistant (WP-B): the style graph. css_rules holds one row per
-- selector (comma lists already split by the analyzer) with computed
-- specificity + at-rule context; css_declarations holds each property/value
-- bound to its rule. Both cascade on file delete so a re-index fully replaces a
-- file's graph (delete-then-insert, mirroring the code-index file refresh).
CREATE TABLE IF NOT EXISTS css_rules (  id BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,  file_id BIGINT NOT NULL REFERENCES files(id) ON DELETE CASCADE,  selector TEXT NOT NULL DEFAULT '',  spec_a BIGINT NOT NULL DEFAULT 0,  spec_b BIGINT NOT NULL DEFAULT 0,  spec_c BIGINT NOT NULL DEFAULT 0,  spec_uncertain BIGINT NOT NULL DEFAULT 0,  at_context TEXT NOT NULL DEFAULT '',  line BIGINT NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS css_declarations (  id BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,  rule_id BIGINT NOT NULL REFERENCES css_rules(id) ON DELETE CASCADE,  property TEXT NOT NULL DEFAULT '',  value TEXT NOT NULL DEFAULT '',  important BIGINT NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS idx_css_rules_file ON css_rules(file_id);
CREATE INDEX IF NOT EXISTS idx_css_rules_selector ON css_rules(selector);
CREATE INDEX IF NOT EXISTS idx_css_decl_rule ON css_declarations(rule_id);
CREATE INDEX IF NOT EXISTS idx_css_decl_property ON css_declarations(property);

-- CSS migration assistant (WP-D): component -> style join. One row per static
-- class token a component (TSX/JSX) uses; rule_id is the matched css_rules.id or
-- -1 when unresolved (dynamic class, CSS-in-JS, or a class with no rule yet).
-- Enables cross-file dead-rule detection (a class rule no component references).
CREATE TABLE IF NOT EXISTS css_component_styles (  id BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,  component_file_id BIGINT NOT NULL REFERENCES files(id) ON DELETE CASCADE,  class_token TEXT NOT NULL DEFAULT '',  rule_id BIGINT NOT NULL DEFAULT -1,  resolved BIGINT NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS idx_css_comp_file ON css_component_styles(component_file_id);
CREATE INDEX IF NOT EXISTS idx_css_comp_token ON css_component_styles(class_token);

-- CSS migration assistant (WP-F): per-unit pipeline state. One row per
-- conversion unit (a component); the driver enumerates units from the component
-- join, tracks state through the pipeline, and records the WP-E oracle verdict
-- and WP-D resolver coverage that gate auto-accept vs human/roundtable review.
CREATE TABLE IF NOT EXISTS css_migration_units (  id BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,  project TEXT NOT NULL DEFAULT '',  generation BIGINT NOT NULL DEFAULT 1 CHECK (generation > 0),  unit_path TEXT NOT NULL DEFAULT '',  state TEXT NOT NULL DEFAULT 'pending',  total_tokens BIGINT NOT NULL DEFAULT 0,  resolved_tokens BIGINT NOT NULL DEFAULT 0,  oracle_equivalent BIGINT NOT NULL DEFAULT -1,  note TEXT NOT NULL DEFAULT '',  updated_at TEXT NOT NULL DEFAULT '',  UNIQUE(project, generation, unit_path));
DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns
         WHERE table_schema=current_schema() AND table_name='css_migration_units'
           AND column_name='generation'
    ) THEN
        ALTER TABLE css_migration_units ADD COLUMN generation BIGINT NOT NULL DEFAULT 1
           CHECK (generation > 0);
        UPDATE css_migration_units u SET generation=p.current_generation
          FROM projects p WHERE p.name=u.project;
    END IF;
END $$;
ALTER TABLE css_migration_units DROP CONSTRAINT IF EXISTS css_migration_units_project_unit_path_key;
CREATE UNIQUE INDEX IF NOT EXISTS idx_css_migration_units_project_generation_path
    ON css_migration_units(project, generation, unit_path);
CREATE INDEX IF NOT EXISTS idx_css_migration_project ON css_migration_units(project, state);
-- #4-full rendered-oracle evidence: per-unit before/after computed-style snapshots
-- (the captured render JSON is the retained origin artifact; diffs read it, never re-derive).
CREATE TABLE IF NOT EXISTS css_render_snapshots (  id BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,  project TEXT NOT NULL DEFAULT '',  generation BIGINT NOT NULL DEFAULT 1 CHECK (generation > 0),  unit_path TEXT NOT NULL DEFAULT '',  phase TEXT NOT NULL DEFAULT '',  snapshot TEXT NOT NULL DEFAULT '',  content_hash TEXT NOT NULL DEFAULT '',  captured_at TEXT NOT NULL DEFAULT '',  UNIQUE(project, generation, unit_path, phase));
DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns
         WHERE table_schema=current_schema() AND table_name='css_render_snapshots'
           AND column_name='generation'
    ) THEN
        ALTER TABLE css_render_snapshots ADD COLUMN generation BIGINT NOT NULL DEFAULT 1
           CHECK (generation > 0);
        UPDATE css_render_snapshots s SET generation=p.current_generation
          FROM projects p WHERE p.name=s.project;
    END IF;
END $$;
ALTER TABLE css_render_snapshots DROP CONSTRAINT IF EXISTS css_render_snapshots_project_unit_path_phase_key;
CREATE UNIQUE INDEX IF NOT EXISTS idx_css_render_snapshots_project_generation_phase
    ON css_render_snapshots(project, generation, unit_path, phase);
CREATE INDEX IF NOT EXISTS idx_css_render_snapshots_unit ON css_render_snapshots(project, unit_path);

-- Typed-fact knowledge layer (first slice; backs the CSS migration assistant's
-- #2 convention model upgrade). A typed (subject, relation, object) proposition
-- with kinds, provenance, confidence (0-100), and correctable history: a
-- contradicting assert supersedes the prior active row (active=0, superseded_by)
-- rather than deleting it (always-retain-origin). Write-gated against a seed
-- ontology in typed_facts.c. The broader proposal integrates this with
-- entity_edges; this slice uses a dedicated table for a clean, shippable base.
CREATE TABLE IF NOT EXISTS typed_facts (  id BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,  subject TEXT NOT NULL DEFAULT '',  subject_kind TEXT NOT NULL DEFAULT '',  relation TEXT NOT NULL DEFAULT '',  object TEXT NOT NULL DEFAULT '',  object_kind TEXT NOT NULL DEFAULT '',  confidence BIGINT NOT NULL DEFAULT 50,  source TEXT NOT NULL DEFAULT '',  asserted_at TEXT NOT NULL DEFAULT '',  active BIGINT NOT NULL DEFAULT 1,  superseded_by BIGINT NOT NULL DEFAULT -1);
CREATE INDEX IF NOT EXISTS idx_typed_facts_subject ON typed_facts(subject, relation, active);
CREATE INDEX IF NOT EXISTS idx_typed_facts_relation ON typed_facts(relation, active);

-- ============================================================================
-- P1 TENANCY + IDENTITY (tiered-llm-p1). Team/project entities, identity->team
-- membership, org-admin grants, fleet-wide JWKS, and the team-scoped RLS that
-- makes cross-tenant isolation a DB-layer control (invariant #10). The three-role
-- split that makes this load-bearing lives in schema_roles.sql (applied out of
-- band by the migration path). Tenant-scoped access at runtime is set ONLY via
-- set_tenant_context() below, fed the authenticated principal (never a request
-- string) by the C choke point (kb_http_auth_context / kb_identity_resolve).
-- ============================================================================

-- Team = the org tier tenant. No user table: users are external identities.
CREATE TABLE IF NOT EXISTS kb_team (  id BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,  name TEXT NOT NULL UNIQUE,  created_at TEXT NOT NULL DEFAULT (pg_now_text()),  operator_id TEXT NOT NULL DEFAULT '');
-- Project belongs to exactly one team (parent). access_mode: team-open | restricted.
CREATE TABLE IF NOT EXISTS kb_project (  id BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,  parent BIGINT NOT NULL REFERENCES kb_team(id) ON DELETE CASCADE,  name TEXT NOT NULL,  access_mode TEXT NOT NULL DEFAULT 'team-open' CHECK (access_mode IN ('team-open','restricted')),  created_at TEXT NOT NULL DEFAULT (pg_now_text()),  operator_id TEXT NOT NULL DEFAULT '',  UNIQUE(parent, name));

-- identity_key is the CANONICAL immutable identity: for OIDC 'oidc:<iss>:<sub>',
-- for machines 'cert:<issuer>:<serial>'. Never a bare sub or email. is_default:
-- at most one default per identity_key (partial unique index below).
CREATE TABLE IF NOT EXISTS kb_team_membership (  id BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,  identity_key TEXT NOT NULL CHECK (char_length(identity_key) BETWEEN 1 AND 600),  team BIGINT NOT NULL REFERENCES kb_team(id) ON DELETE CASCADE,  is_default BIGINT NOT NULL DEFAULT 0,  created_at TEXT NOT NULL DEFAULT (pg_now_text()),  UNIQUE(identity_key, team));
CREATE UNIQUE INDEX IF NOT EXISTS idx_kbmember_default ON kb_team_membership(identity_key) WHERE is_default = 1;
CREATE INDEX IF NOT EXISTS idx_kbmember_team ON kb_team_membership(team);

-- Explicit project membership; governs 'restricted' projects only.
CREATE TABLE IF NOT EXISTS kb_project_membership (  id BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,  project BIGINT NOT NULL REFERENCES kb_project(id) ON DELETE CASCADE,  identity_key TEXT NOT NULL CHECK (char_length(identity_key) BETWEEN 1 AND 600),  created_at TEXT NOT NULL DEFAULT (pg_now_text()),  UNIQUE(project, identity_key));
CREATE INDEX IF NOT EXISTS idx_kbprojmember_id ON kb_project_membership(identity_key);

-- Org-admin capability grant. source: oidc | cert | owner. Revocable (revoked_at).
CREATE TABLE IF NOT EXISTS kb_admin_grant (  id BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,  identity_key TEXT NOT NULL CHECK (char_length(identity_key) BETWEEN 1 AND 600),  source TEXT NOT NULL DEFAULT '',  granted_at TEXT NOT NULL DEFAULT (pg_now_text()),  granted_by TEXT NOT NULL DEFAULT '',  revoked_at TEXT NOT NULL DEFAULT '',  UNIQUE(identity_key));

-- Fleet-wide trusted JWKS (I10): org-global (NOT team-scoped), so every stateless
-- kb instance agrees on trusted keys and IdP rotation converges within TTL.
CREATE TABLE IF NOT EXISTS kb_oidc_jwks (  id BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,  issuer TEXT NOT NULL,  kid TEXT NOT NULL,  jwk_json TEXT NOT NULL,  added_at TEXT NOT NULL DEFAULT (pg_now_text()),  retired_at TEXT NOT NULL DEFAULT '',  UNIQUE(issuer, kid));
CREATE INDEX IF NOT EXISTS idx_kbjwks_issuer ON kb_oidc_jwks(issuer) WHERE retired_at = '';

-- I5: immutable (cert_issuer, cert_serial_norm) revocation key on enrollments.
-- CN stays the policy label only. Eager backfill (no key-less window) runs in the
-- migration path (backfill_enrollment_cert_keys()), not lazily at next handshake.
ALTER TABLE kb_enrollments ADD COLUMN IF NOT EXISTS cert_issuer TEXT NOT NULL DEFAULT '';
ALTER TABLE kb_enrollments ADD COLUMN IF NOT EXISTS cert_serial_norm TEXT NOT NULL DEFAULT '';
CREATE UNIQUE INDEX IF NOT EXISTS idx_kbenroll_issuer_serial ON kb_enrollments(cert_issuer, cert_serial_norm) WHERE cert_serial_norm <> '';

-- I12: separate immutable identity fields on the WORM audit store (never a
-- collapsed user:<sub>). Added additively; existing WORM triggers/role unchanged.
ALTER TABLE kb_audit_event ADD COLUMN IF NOT EXISTS actor_issuer TEXT NOT NULL DEFAULT '';
ALTER TABLE kb_audit_event ADD COLUMN IF NOT EXISTS actor_subject TEXT NOT NULL DEFAULT '';
ALTER TABLE kb_audit_event ADD COLUMN IF NOT EXISTS transport_cn TEXT NOT NULL DEFAULT '';
ALTER TABLE kb_audit_event ADD COLUMN IF NOT EXISTS team_id BIGINT NOT NULL DEFAULT 0;
ALTER TABLE kb_audit_event ADD COLUMN IF NOT EXISTS selected_default_from TEXT NOT NULL DEFAULT '';

-- set_tenant_context(principal, team): the ONLY runtime path that sets the tenant
-- GUCs. SECURITY DEFINER, EXECUTE granted to the runtime role only (B4/N4). It sets
-- aimee.principal first, then validates that the (principal, team) membership row
-- exists, then sets aimee.team. A team not in the principal's memberships raises
-- (insufficient_privilege), fail-closed. Provisioning MUST own this function by the
-- non-superuser aimee_kb_owner role so the SECURITY DEFINER context is itself
-- subject to RLS (least privilege); the membership existence check is correct in
-- either case because it filters on the passed (principal, team) pair — a superuser
-- owner would see all rows but still only answers "does THIS pair exist".
CREATE OR REPLACE FUNCTION set_tenant_context(p_principal TEXT, p_team BIGINT)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF p_principal IS NULL OR p_principal = '' THEN
    RAISE EXCEPTION 'set_tenant_context: empty principal' USING ERRCODE = '42501';
  END IF;
  PERFORM set_config('aimee.principal', p_principal, true);  -- transaction-local
  IF p_team IS NOT NULL AND p_team > 0 THEN
    IF NOT EXISTS (SELECT 1 FROM kb_team_membership
                   WHERE identity_key = p_principal AND team = p_team) THEN
      RAISE EXCEPTION 'set_tenant_context: team % not in principal memberships', p_team
        USING ERRCODE = '42501';
    END IF;
    PERFORM set_config('aimee.team', p_team::text, true);
  ELSE
    PERFORM set_config('aimee.team', '', true);
  END IF;
END
$$;

-- Enable + FORCE RLS so even the table owner cannot bypass the predicate; the
-- runtime role is non-owner + NOBYPASSRLS (schema_roles.sql). missing_ok=true on
-- current_setting so an unset GUC yields NULL -> no rows (fail-closed), never an error.
DO $$
DECLARE t TEXT;
BEGIN
  FOREACH t IN ARRAY ARRAY['kb_team','kb_project','kb_team_membership','kb_project_membership','kb_admin_grant']
  LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t);
  END LOOP;
END
$$;

-- POLICIES ARE READ-ONLY (FOR SELECT). Writes to tenant tables have NO permissive
-- policy, so under FORCE RLS every INSERT/UPDATE/DELETE by the runtime role is
-- DENIED at the DB layer — a runtime role that holds table-level DML grants still
-- cannot self-enroll into a team or self-grant admin. Authorized writes (team/
-- project/member creation) land in a later slice as admin-gated SECURITY DEFINER
-- paths that validate the org-admin capability before writing; they are the only
-- way rows are created, and they run with a checked authorization, not on the bare
-- runtime role's own-row predicate.
--
-- TRUST BOUNDARY (documented): the RLS predicates read current_setting('aimee.*'),
-- which the runtime role can set directly in SQL. RLS therefore defends against a
-- mis-written JOIN / injected predicate leaking cross-tenant rows — it does NOT
-- defend against a caller that can already execute arbitrary SQL as the runtime
-- role (such a caller has fully compromised the app tier). The tenant GUCs are set
-- ONLY from the authenticated principal by the C choke point (set_tenant_context,
-- fed a verifier-produced kb_principal_t — never a request string). RLS + "GUCs set
-- only by vetted code" together are the isolation control.

-- Bootstrap / identity policies: a principal reads ONLY its own rows (FOR SELECT).
-- This breaks the RLS circularity (resolve teams before a team GUC exists) WITHOUT
-- letting a SET aimee.principal read every team's membership, and without allowing
-- self-write (no WITH CHECK / write policy exists).
DROP POLICY IF EXISTS p_member_self ON kb_team_membership;
CREATE POLICY p_member_self ON kb_team_membership
  FOR SELECT USING (identity_key = current_setting('aimee.principal', true));
-- P5-B2b's fixed owner-definer may inspect and create only canonical certificate
-- memberships.  This is deliberately GUC-free; runtime still has no direct table
-- privilege and reaches it only through the fixed activation facade.
DROP POLICY IF EXISTS p_member_management_definer_read ON kb_team_membership;
CREATE POLICY p_member_management_definer_read ON kb_team_membership
  FOR SELECT
  USING (current_user='aimee_kb_owner' AND identity_key LIKE 'cert:%');
DROP POLICY IF EXISTS p_member_management_definer_insert ON kb_team_membership;
CREATE POLICY p_member_management_definer_insert ON kb_team_membership
  FOR INSERT
  WITH CHECK (current_user='aimee_kb_owner' AND identity_key LIKE 'cert:%' AND is_default=0);
DROP POLICY IF EXISTS p_projmember_self ON kb_project_membership;
CREATE POLICY p_projmember_self ON kb_project_membership
  FOR SELECT USING (identity_key = current_setting('aimee.principal', true));
DROP POLICY IF EXISTS p_admingrant_self ON kb_admin_grant;
CREATE POLICY p_admingrant_self ON kb_admin_grant
  FOR SELECT USING (identity_key = current_setting('aimee.principal', true));

-- Tenant-data policies: a caller sees a team/project ONLY when the row's team is in
-- the principal's own memberships. These do NOT trust aimee.team for read scope
-- (defense-in-depth: a wrong/forgotten aimee.team cannot widen access); aimee.team
-- is validated to be one of the caller's teams at set time and used downstream for
-- billing/attribution (P3/P4).
DROP POLICY IF EXISTS p_team_member ON kb_team;
CREATE POLICY p_team_member ON kb_team
  FOR SELECT USING (id IN (SELECT team FROM kb_team_membership
                WHERE identity_key = current_setting('aimee.principal', true)));
-- Project reads honor the full access model: (a) the parent team must be one of
-- the principal's teams (isolation); (b) when a billing team is selected
-- (aimee.team set) the row must belong to it, so a single-team request cannot read
-- the caller's OTHER teams' projects even if a query omits the predicate; (c) a
-- 'restricted' project is visible only to an explicit kb_project_membership member,
-- while 'team-open' is visible to the whole parent team.
DROP POLICY IF EXISTS p_project_member ON kb_project;
CREATE POLICY p_project_member ON kb_project
  FOR SELECT USING (
    parent IN (SELECT team FROM kb_team_membership
               WHERE identity_key = current_setting('aimee.principal', true))
    AND (current_setting('aimee.team', true) IS NULL
         OR current_setting('aimee.team', true) = ''
         OR parent = current_setting('aimee.team', true)::bigint)
    AND (access_mode = 'team-open'
         OR id IN (SELECT project FROM kb_project_membership
                   WHERE identity_key = current_setting('aimee.principal', true))));

-- ---------------------------------------------------------------------------
-- CONTENT SCOPE, part 1: the referent and the predicate. Neither enforces
-- anything on its own; the policies that read them land with the backfill.
-- See docs/proposals/pending/per-user-content-scope-visibility.md.
--
-- WHY A COLUMN ON `projects` AND NOT ON EACH CONTENT TABLE. kb_documents,
-- kb_file_index, kb_embeddings and kb_pdf_embeddings all carry `project`, which
-- holds projects.name (bound at ingest in kb_payload.c). projects.name is
-- globally UNIQUE, so it identifies exactly one row; one link here therefore
-- gives every content table a route to tenancy.
--
-- AND WHY NOT BY NAME. kb_project is UNIQUE(parent, name): two teams may each
-- own a project called `aimee`, so a name identifies NOTHING on its own.
-- Resolving content to tenancy by name lets a member of one team read another
-- team's content, which is a cross-tenant leak introduced by the control meant
-- to prevent one. Reproduced in
-- docs/validation/per-user-content-scope-prototype.md; do not "simplify" this
-- into a name match.
--
-- NULL means unattributed, and kb_project_visible() denies it. Nothing reads
-- that yet, so an existing deployment is unaffected until the policies land.
ALTER TABLE projects ADD COLUMN IF NOT EXISTS kb_project BIGINT REFERENCES kb_project(id);
CREATE INDEX IF NOT EXISTS idx_projects_kb_project ON projects(kb_project);

-- May the current principal see this tenancy project? The rule is
-- p_project_member's, said ONCE so every content policy calls it rather than
-- carrying its own copy: (a) the parent team is one of the principal's teams;
-- (b) a selected billing team narrows it further; (c) a `restricted` project
-- needs an explicit membership where `team-open` does not.
--
-- STABLE, not IMMUTABLE: it reads current_setting and the membership tables.
-- SECURITY INVOKER (the default) on purpose -- it must see exactly what the
-- caller sees, and a definer function here would hand back rows the caller's
-- own RLS denies.
CREATE OR REPLACE FUNCTION kb_project_visible(p BIGINT) RETURNS boolean
LANGUAGE sql STABLE AS $$
  SELECT p IS NOT NULL AND EXISTS (
    SELECT 1 FROM kb_project k
     WHERE k.id = p
       AND k.parent IN (SELECT team FROM kb_team_membership
                        WHERE identity_key = current_setting('aimee.principal', true))
       AND (current_setting('aimee.team', true) IS NULL
            OR current_setting('aimee.team', true) = ''
            OR k.parent = current_setting('aimee.team', true)::bigint)
       AND (k.access_mode = 'team-open'
            OR k.id IN (SELECT project FROM kb_project_membership
                        WHERE identity_key = current_setting('aimee.principal', true))));
$$;

-- CONTENT SCOPE, part 2: the policies, DEFINED BUT NOT ENABLED.
--
-- A policy is inert until RLS is enabled on its table, so applying this file
-- changes nothing about what anyone can read. That is the whole design: the
-- migrate step re-runs this file on every deployment, and a policy that switched
-- itself on here would hide every row that has not been attributed yet -- an
-- outage delivered by an upgrade.
--
-- Enabling is therefore an ACT, not a migration: attribute the rows, check the
-- counts, then call kb_content_scope_enable(). See the proposal for the two
-- orderings and why this is the one without a window where the control is
-- advertised and absent.
DROP POLICY IF EXISTS p_documents_project ON kb_documents;
CREATE POLICY p_documents_project ON kb_documents
  FOR SELECT USING (EXISTS (SELECT 1 FROM projects p
                            WHERE p.name = kb_documents.project
                              AND kb_project_visible(p.kb_project)));

DROP POLICY IF EXISTS p_file_index_project ON kb_file_index;
CREATE POLICY p_file_index_project ON kb_file_index
  FOR SELECT USING (EXISTS (SELECT 1 FROM projects p
                            WHERE p.name = kb_file_index.project
                              AND kb_project_visible(p.kb_project)));

-- Turn content scoping on, once the rows carry a kb_project.
--
-- FORCE as well as ENABLE: without FORCE the table OWNER bypasses its own
-- policies, and the owner is who the application connects as in a good many
-- deployments, which would leave the control on paper only.
--
-- Refuses while any content is unattributed, and says how much. Enabling over
-- unattributed rows is not a smaller version of the control: those rows become
-- invisible to everyone, which is an outage that looks like data loss. The
-- caller is told to finish the backfill instead.
CREATE OR REPLACE FUNCTION kb_content_scope_enable() RETURNS text
LANGUAGE plpgsql AS $$
DECLARE
  orphan_docs BIGINT;
  orphan_files BIGINT;
  reader_ready TEXT;
BEGIN
  -- THE READER SIDE MUST EXIST FIRST, and today it does not.
  --
  -- aimee.principal is transaction-scoped and reset on pooled connections
  -- (db2_tenant.c), and it is set only inside db2_tenant_scope_begin. Every one
  -- of that function's callers is a governance, management or vault path: the
  -- content readers -- kb_payload.c, memory_query.c, kb_service_backend.c --
  -- open NO tenant scope at all. The service also connects as a non-owner with
  -- NOBYPASSRLS, by design, so nothing rescues it.
  --
  -- So enabling before the read paths carry a principal does not hide
  -- unattributed rows. It returns NOTHING to EVERY content read, for everyone,
  -- which is a total outage wearing the costume of a security control.
  --
  -- The marker is written by the change that threads the principal through
  -- those reads. Until then this refuses, because a comment in a proposal is not
  -- a safeguard and this is exactly the mistake an operator cannot un-make in a
  -- hurry.
  SELECT value INTO reader_ready FROM kb_meta WHERE key = 'content_scope_reader_ready';
  IF reader_ready IS DISTINCT FROM '1' THEN
    RAISE EXCEPTION 'refusing to enable content scope: the content read paths do not set '
                    'aimee.principal yet, so every content read would return nothing for '
                    'everyone. The change that threads the principal through those reads sets '
                    'kb_meta.content_scope_reader_ready=1; enable after it ships.';
  END IF;
  SELECT count(*) INTO orphan_docs FROM kb_documents d
    WHERE NOT EXISTS (SELECT 1 FROM projects p
                      WHERE p.name = d.project AND p.kb_project IS NOT NULL);
  SELECT count(*) INTO orphan_files FROM kb_file_index f
    WHERE NOT EXISTS (SELECT 1 FROM projects p
                      WHERE p.name = f.project AND p.kb_project IS NOT NULL);
  IF orphan_docs > 0 OR orphan_files > 0 THEN
    RAISE EXCEPTION 'refusing to enable content scope: % document rows and % file-index rows '
                    'have no kb_project, and would become invisible to everyone. Attribute them '
                    '(projects.kb_project) and call again.', orphan_docs, orphan_files;
  END IF;
  ALTER TABLE kb_documents ENABLE ROW LEVEL SECURITY;
  ALTER TABLE kb_documents FORCE ROW LEVEL SECURITY;
  ALTER TABLE kb_file_index ENABLE ROW LEVEL SECURITY;
  ALTER TABLE kb_file_index FORCE ROW LEVEL SECURITY;
  RETURN 'content scope enabled on kb_documents, kb_file_index';
END;
$$;

-- The way back. An operator who enables this and finds a surface they had not
-- accounted for needs a door that is not "restore from backup".
CREATE OR REPLACE FUNCTION kb_content_scope_disable() RETURNS text
LANGUAGE plpgsql AS $$
BEGIN
  ALTER TABLE kb_documents NO FORCE ROW LEVEL SECURITY;
  ALTER TABLE kb_documents DISABLE ROW LEVEL SECURITY;
  ALTER TABLE kb_file_index NO FORCE ROW LEVEL SECURITY;
  ALTER TABLE kb_file_index DISABLE ROW LEVEL SECURITY;
  RETURN 'content scope disabled';
END;
$$;

-- Admin-gated tenant WRITES (slice 4). Writes are permitted only when the current
-- principal holds an active org-admin grant, OR is the bootstrap owner. The admin
-- check keys on the principal's OWN grant row (own-rows policy on kb_admin_grant),
-- so it cannot be spoofed by naming another principal; the bootstrap-owner flag is
-- set only by set_tenant_context from the verified 'owner' principal. This keeps the
-- capability enforced at the DB layer (not just the app) without a 4th DB role.
CREATE OR REPLACE FUNCTION kb_principal_is_admin() RETURNS boolean
LANGUAGE sql STABLE AS $$
  SELECT current_setting('aimee.principal', true) = 'owner'
      OR EXISTS (SELECT 1 FROM public.kb_admin_grant
                 WHERE identity_key = current_setting('aimee.principal', true)
                   AND revoked_at = '');
$$;

DROP POLICY IF EXISTS p_team_admin_write ON kb_team;
CREATE POLICY p_team_admin_write ON kb_team FOR INSERT WITH CHECK (kb_principal_is_admin());
DROP POLICY IF EXISTS p_team_admin_mod ON kb_team;
CREATE POLICY p_team_admin_mod ON kb_team FOR UPDATE USING (kb_principal_is_admin());
DROP POLICY IF EXISTS p_team_admin_del ON kb_team;
CREATE POLICY p_team_admin_del ON kb_team FOR DELETE USING (kb_principal_is_admin());

DROP POLICY IF EXISTS p_project_admin_write ON kb_project;
CREATE POLICY p_project_admin_write ON kb_project FOR INSERT WITH CHECK (
  kb_principal_is_admin()
  AND parent IN (SELECT team FROM kb_team_membership
                 WHERE identity_key = current_setting('aimee.principal', true))
);
DROP POLICY IF EXISTS p_project_admin_mod ON kb_project;
CREATE POLICY p_project_admin_mod ON kb_project FOR UPDATE USING (kb_principal_is_admin());
DROP POLICY IF EXISTS p_project_admin_del ON kb_project;
CREATE POLICY p_project_admin_del ON kb_project FOR DELETE USING (kb_principal_is_admin());

-- Membership writes: admin-gated, and the target team must exist (FK enforces it).
DROP POLICY IF EXISTS p_member_admin_write ON kb_team_membership;
CREATE POLICY p_member_admin_write ON kb_team_membership FOR INSERT WITH CHECK (kb_principal_is_admin());
DROP POLICY IF EXISTS p_member_admin_del ON kb_team_membership;
CREATE POLICY p_member_admin_del ON kb_team_membership FOR DELETE USING (kb_principal_is_admin());
DROP POLICY IF EXISTS p_projmember_admin_write ON kb_project_membership;
CREATE POLICY p_projmember_admin_write ON kb_project_membership FOR INSERT WITH CHECK (kb_principal_is_admin());
DROP POLICY IF EXISTS p_projmember_admin_del ON kb_project_membership;
CREATE POLICY p_projmember_admin_del ON kb_project_membership FOR DELETE USING (kb_principal_is_admin());

-- Admin-grant writes: only an existing admin or the bootstrap owner can grant/revoke
-- (the bootstrap owner mints the first admin grant, resolving the chicken-and-egg).
DROP POLICY IF EXISTS p_admingrant_admin_write ON kb_admin_grant;
CREATE POLICY p_admingrant_admin_write ON kb_admin_grant FOR INSERT WITH CHECK (kb_principal_is_admin());
DROP POLICY IF EXISTS p_admingrant_admin_mod ON kb_admin_grant;
CREATE POLICY p_admingrant_admin_mod ON kb_admin_grant FOR UPDATE USING (kb_principal_is_admin());

-- The context setter is never exposed to PUBLIC. This is role-free and safe on
-- every db2_init (dev + hardened). Runtime-role grants (which reference roles that
-- exist only on a hardened tier) live in schema_grants.sql, applied out of band
-- AFTER this schema by the migration path — so schema.sql itself references no role
-- and applies unchanged in dev/single-owner mode.
REVOKE ALL ON FUNCTION set_tenant_context(TEXT, BIGINT) FROM PUBLIC;

-- ============================================================================
-- P3a COST ATTRIBUTION (tiered-llm-p3a). Authoritative versioned pricing +
-- per-request org cost ledger + (team,project,model,day) rollup. Reuses the P1
-- tenancy substrate (kb_team/kb_project, kb_principal_is_admin, aimee.principal).
--
-- RLS posture (deliberate, differs from P1 tenant tables): pricing/ledger/rollup
-- use ENABLE (NOT FORCE) ROW LEVEL SECURITY. Writes are privileged server-internal
-- metering, done ONLY through the SECURITY DEFINER functions below (owned by the
-- schema owner, which bypasses ENABLE-not-FORCE RLS); the non-owner NOBYPASSRLS
-- runtime role has NO direct INSERT/UPDATE grant and its READS stay RLS-filtered
-- (admin OR team-lead of the row's team). This is why a set_config GUC is never
-- trusted for the pricing boundary — the boundary is role+grant+SECURITY DEFINER,
-- not a caller-writable session value. kb_team_lead is a human-admin-written grant
-- so it follows P1's FORCE pattern instead.
-- ============================================================================

-- Generic WORM raiser (append-only / immutable tables). Message names the table.
CREATE OR REPLACE FUNCTION org_worm_block() RETURNS trigger AS $$
BEGIN RAISE EXCEPTION 'WORM: % is immutable/append-only', TG_TABLE_NAME USING ERRCODE = '42501'; END;
$$ LANGUAGE plpgsql;

-- org_model_pricing: Postgres-authoritative, versioned, IMMUTABLE price rows. A
-- price change is a NEW (billable_model, version+1) row, never an in-place mutate.
CREATE TABLE IF NOT EXISTS org_model_pricing (
  id BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  provider TEXT NOT NULL DEFAULT '',
  billable_model TEXT NOT NULL CHECK (char_length(billable_model) BETWEEN 1 AND 200),
  version BIGINT NOT NULL CHECK (version >= 1),
  input_usd_per_mtok NUMERIC(20,10) NOT NULL CHECK (input_usd_per_mtok >= 0),
  output_usd_per_mtok NUMERIC(20,10) NOT NULL CHECK (output_usd_per_mtok >= 0),
  cache_read_usd_per_mtok NUMERIC(20,10) NOT NULL DEFAULT 0 CHECK (cache_read_usd_per_mtok >= 0),
  cache_write_usd_per_mtok NUMERIC(20,10) NOT NULL DEFAULT 0 CHECK (cache_write_usd_per_mtok >= 0),
  effective_at TEXT NOT NULL DEFAULT (pg_now_text()),
  created_at TEXT NOT NULL DEFAULT (pg_now_text()),
  UNIQUE(billable_model, version)
);
DROP TRIGGER IF EXISTS org_pricing_no_update ON org_model_pricing;
CREATE TRIGGER org_pricing_no_update BEFORE UPDATE ON org_model_pricing FOR EACH ROW EXECUTE FUNCTION org_worm_block();
DROP TRIGGER IF EXISTS org_pricing_no_delete ON org_model_pricing;
CREATE TRIGGER org_pricing_no_delete BEFORE DELETE ON org_model_pricing FOR EACH ROW EXECUTE FUNCTION org_worm_block();
DROP TRIGGER IF EXISTS org_pricing_no_truncate ON org_model_pricing;
CREATE TRIGGER org_pricing_no_truncate BEFORE TRUNCATE ON org_model_pricing FOR EACH STATEMENT EXECUTE FUNCTION org_worm_block();

-- Per-model current-version pointer. Advanced atomically with the new price row
-- inside org_pricing_add_version(); FK guarantees it points at a real version.
CREATE TABLE IF NOT EXISTS org_model_pricing_current (
  billable_model TEXT PRIMARY KEY,
  version BIGINT NOT NULL,
  updated_at TEXT NOT NULL DEFAULT (pg_now_text()),
  FOREIGN KEY (billable_model, version) REFERENCES org_model_pricing(billable_model, version)
);

-- kb_team_lead: an identity is a lead of a specific team (read authority over that
-- team's cost ledger/rollup). identity_key = the P1 canonical key (oidc:/cert:/owner).
CREATE TABLE IF NOT EXISTS kb_team_lead (
  id BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  identity_key TEXT NOT NULL CHECK (char_length(identity_key) BETWEEN 1 AND 600),
  team BIGINT NOT NULL REFERENCES kb_team(id) ON DELETE CASCADE,
  granted_at TEXT NOT NULL DEFAULT (pg_now_text()),
  granted_by TEXT NOT NULL DEFAULT '',
  revoked_at TEXT NOT NULL DEFAULT '',
  UNIQUE(identity_key, team)
);
CREATE INDEX IF NOT EXISTS idx_kbteamlead_id ON kb_team_lead(identity_key);

-- org_token_audit: per-request org cost ledger. WORM (append + one settle). The
-- idempotency key is composite (origin_cert_cn, request_id): the SAME request_id
-- from a DIFFERENT origin is a DISTINCT valid row by design (avoids cross-origin
-- collision), NOT a replay. billable_model is the token_billable_model result (the
-- priced identity), separate from served_model (what actually answered).
CREATE TABLE IF NOT EXISTS org_token_audit (
  id BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  request_id TEXT NOT NULL CHECK (char_length(request_id) BETWEEN 1 AND 200),
  origin_cert_cn TEXT NOT NULL CHECK (char_length(origin_cert_cn) BETWEEN 1 AND 400),
  actor_issuer TEXT NOT NULL DEFAULT '',
  actor_subject TEXT NOT NULL DEFAULT '',
  team_id BIGINT NOT NULL REFERENCES kb_team(id),
  project_id BIGINT REFERENCES kb_project(id),
  billable_model TEXT NOT NULL CHECK (char_length(billable_model) BETWEEN 1 AND 200),
  served_model TEXT NOT NULL DEFAULT '',
  pricing_version BIGINT NOT NULL,
  prompt_tokens BIGINT NOT NULL DEFAULT 0 CHECK (prompt_tokens >= 0),
  completion_tokens BIGINT NOT NULL DEFAULT 0 CHECK (completion_tokens >= 0),
  cache_read_tokens BIGINT NOT NULL DEFAULT 0 CHECK (cache_read_tokens >= 0),
  cache_write_tokens BIGINT NOT NULL DEFAULT 0 CHECK (cache_write_tokens >= 0),
  estimated_cost_usd NUMERIC(20,10) NOT NULL DEFAULT 0 CHECK (estimated_cost_usd >= 0),
  state TEXT NOT NULL DEFAULT 'started'
    CHECK (state IN ('started','settled_success','settled_denied','settled_failed','indeterminate')),
  session_id TEXT NOT NULL DEFAULT '',
  delegation_id TEXT NOT NULL DEFAULT '',
  created_at TEXT NOT NULL DEFAULT (pg_now_text()),
  settled_at TEXT NOT NULL DEFAULT '',
  UNIQUE(origin_cert_cn, request_id),
  FOREIGN KEY (billable_model, pricing_version) REFERENCES org_model_pricing(billable_model, version)
);
CREATE INDEX IF NOT EXISTS idx_org_audit_team ON org_token_audit(team_id);
CREATE INDEX IF NOT EXISTS idx_org_audit_state ON org_token_audit(state);
CREATE INDEX IF NOT EXISTS idx_org_audit_created ON org_token_audit(created_at);
ALTER TABLE org_token_audit ALTER COLUMN estimated_cost_usd TYPE NUMERIC(38,10);

-- project->team consistency: a non-null project's parent MUST equal team_id. A
-- plain FK can't express the cross-column rule, so a BEFORE INSERT trigger does.
CREATE OR REPLACE FUNCTION org_audit_project_team_check() RETURNS trigger AS $$
BEGIN
  IF NEW.project_id IS NOT NULL THEN
    IF (SELECT parent FROM kb_project WHERE id = NEW.project_id) IS DISTINCT FROM NEW.team_id THEN
      RAISE EXCEPTION 'org_token_audit: project % not owned by team %', NEW.project_id, NEW.team_id
        USING ERRCODE = '23514';
    END IF;
  END IF;
  RETURN NEW;
END; $$ LANGUAGE plpgsql;
DROP TRIGGER IF EXISTS org_audit_project_team ON org_token_audit;
CREATE TRIGGER org_audit_project_team BEFORE INSERT ON org_token_audit
  FOR EACH ROW EXECUTE FUNCTION org_audit_project_team_check();

-- Settle guard: the ONLY legal UPDATE. Rejects any change to an immutable column;
-- permits only the state-machine transitions started -> settled_*|indeterminate and
-- indeterminate -> settled_* (writing settled_at, realized tokens, cost, served_model).
-- A second settle of an already-terminal row raises (no legal transition matches).
CREATE OR REPLACE FUNCTION org_audit_settle_guard() RETURNS trigger AS $$
BEGIN
  IF NEW.id              IS DISTINCT FROM OLD.id
  OR NEW.request_id      IS DISTINCT FROM OLD.request_id
  OR NEW.origin_cert_cn  IS DISTINCT FROM OLD.origin_cert_cn
  OR NEW.actor_issuer    IS DISTINCT FROM OLD.actor_issuer
  OR NEW.actor_subject   IS DISTINCT FROM OLD.actor_subject
  OR NEW.team_id         IS DISTINCT FROM OLD.team_id
  OR NEW.project_id      IS DISTINCT FROM OLD.project_id
  OR NEW.billable_model  IS DISTINCT FROM OLD.billable_model
  OR NEW.pricing_version IS DISTINCT FROM OLD.pricing_version
  OR NEW.session_id      IS DISTINCT FROM OLD.session_id
  OR NEW.delegation_id   IS DISTINCT FROM OLD.delegation_id
  OR NEW.created_at      IS DISTINCT FROM OLD.created_at THEN
    RAISE EXCEPTION 'WORM: org_token_audit immutable column change' USING ERRCODE = '42501';
  END IF;
  IF NOT (
       (OLD.state = 'started'       AND NEW.state IN ('settled_success','settled_denied','settled_failed','indeterminate'))
    OR (OLD.state = 'indeterminate' AND NEW.state IN ('settled_success','settled_denied','settled_failed'))
  ) THEN
    RAISE EXCEPTION 'WORM: org_token_audit illegal state transition % -> %', OLD.state, NEW.state
      USING ERRCODE = '42501';
  END IF;
  -- A settled_* terminal row must carry a settlement timestamp (blocks a direct
  -- owner-level UPDATE from marking a row settled without recording when).
  IF NEW.state LIKE 'settled_%' AND (NEW.settled_at IS NULL OR NEW.settled_at = '') THEN
    RAISE EXCEPTION 'WORM: org_token_audit settled row requires settled_at' USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END; $$ LANGUAGE plpgsql;
DROP TRIGGER IF EXISTS org_audit_settle ON org_token_audit;
CREATE TRIGGER org_audit_settle BEFORE UPDATE ON org_token_audit
  FOR EACH ROW EXECUTE FUNCTION org_audit_settle_guard();
DROP TRIGGER IF EXISTS org_audit_no_delete ON org_token_audit;
CREATE TRIGGER org_audit_no_delete BEFORE DELETE ON org_token_audit FOR EACH ROW EXECUTE FUNCTION org_worm_block();
DROP TRIGGER IF EXISTS org_audit_no_truncate ON org_token_audit;
CREATE TRIGGER org_audit_no_truncate BEFORE TRUNCATE ON org_token_audit FOR EACH STATEMENT EXECUTE FUNCTION org_worm_block();

-- org_spend_rollup: incremental (team, project, model, day) aggregate, maintained
-- in the SAME txn as the terminal settle. Null-safe unique key via COALESCE(project,0).
CREATE TABLE IF NOT EXISTS org_spend_rollup (
  id BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  team_id BIGINT NOT NULL REFERENCES kb_team(id) ON DELETE CASCADE,
  project_id BIGINT REFERENCES kb_project(id) ON DELETE CASCADE,
  billable_model TEXT NOT NULL,
  day TEXT NOT NULL,
  prompt_tokens BIGINT NOT NULL DEFAULT 0,
  completion_tokens BIGINT NOT NULL DEFAULT 0,
  cache_read_tokens BIGINT NOT NULL DEFAULT 0,
  cache_write_tokens BIGINT NOT NULL DEFAULT 0,
  cost_usd NUMERIC(20,10) NOT NULL DEFAULT 0,
  row_count BIGINT NOT NULL DEFAULT 0,
  updated_at TEXT NOT NULL DEFAULT (pg_now_text())
);
CREATE UNIQUE INDEX IF NOT EXISTS idx_org_rollup_key
  ON org_spend_rollup(team_id, (COALESCE(project_id, 0)), billable_model, day);
ALTER TABLE org_spend_rollup ALTER COLUMN cost_usd TYPE NUMERIC(38,10);
DROP TRIGGER IF EXISTS org_rollup_no_delete ON org_spend_rollup;
CREATE TRIGGER org_rollup_no_delete BEFORE DELETE ON org_spend_rollup FOR EACH ROW EXECUTE FUNCTION org_worm_block();
DROP TRIGGER IF EXISTS org_rollup_no_truncate ON org_spend_rollup;
CREATE TRIGGER org_rollup_no_truncate BEFORE TRUNCATE ON org_spend_rollup FOR EACH STATEMENT EXECUTE FUNCTION org_worm_block();

-- is_team_lead(team): true iff the current principal holds an active kb_team_lead
-- grant for the team. Reads its OWN grant rows (kb_team_lead self-read policy), so
-- no SECURITY DEFINER needed (mirrors kb_principal_is_admin).
CREATE OR REPLACE FUNCTION is_team_lead(p_team BIGINT) RETURNS boolean
LANGUAGE sql STABLE AS $$
  SELECT EXISTS (SELECT 1 FROM kb_team_lead
                 WHERE identity_key = current_setting('aimee.principal', true)
                   AND team = p_team
                   AND revoked_at = '');
$$;

-- Row-level security. Pricing/ledger/rollup: ENABLE (not FORCE) so owner-scoped
-- SECURITY DEFINER writers operate while runtime reads stay filtered. kb_team_lead:
-- FORCE (P1 pattern; human-admin writes).
ALTER TABLE org_model_pricing ENABLE ROW LEVEL SECURITY;
ALTER TABLE org_model_pricing_current ENABLE ROW LEVEL SECURITY;
ALTER TABLE org_token_audit ENABLE ROW LEVEL SECURITY;
ALTER TABLE org_spend_rollup ENABLE ROW LEVEL SECURITY;
ALTER TABLE kb_team_lead ENABLE ROW LEVEL SECURITY;
ALTER TABLE kb_team_lead FORCE ROW LEVEL SECURITY;

-- Pricing reads: org-admins only (negotiated prices are competitive signal). The
-- egress path never reads prices directly — it calls org_token_estimate_cost, which
-- returns only the computed cost. No set_config trust anywhere.
DROP POLICY IF EXISTS p_pricing_admin_read ON org_model_pricing;
CREATE POLICY p_pricing_admin_read ON org_model_pricing FOR SELECT USING (kb_principal_is_admin());
DROP POLICY IF EXISTS p_pricing_cur_admin_read ON org_model_pricing_current;
CREATE POLICY p_pricing_cur_admin_read ON org_model_pricing_current FOR SELECT USING (kb_principal_is_admin());

-- Ledger + rollup reads: org-admin OR team-lead of the row's team.
DROP POLICY IF EXISTS p_audit_read ON org_token_audit;
CREATE POLICY p_audit_read ON org_token_audit FOR SELECT
  USING (kb_principal_is_admin() OR is_team_lead(team_id));
DROP POLICY IF EXISTS p_rollup_read ON org_spend_rollup;
CREATE POLICY p_rollup_read ON org_spend_rollup FOR SELECT
  USING (kb_principal_is_admin() OR is_team_lead(team_id));

-- kb_team_lead: self-read (own grants, so is_team_lead can evaluate) + admin manage.
DROP POLICY IF EXISTS p_teamlead_self ON kb_team_lead;
CREATE POLICY p_teamlead_self ON kb_team_lead FOR SELECT
  USING (identity_key = current_setting('aimee.principal', true) OR kb_principal_is_admin());
DROP POLICY IF EXISTS p_teamlead_admin_write ON kb_team_lead;
CREATE POLICY p_teamlead_admin_write ON kb_team_lead FOR INSERT WITH CHECK (kb_principal_is_admin());
DROP POLICY IF EXISTS p_teamlead_admin_mod ON kb_team_lead;
CREATE POLICY p_teamlead_admin_mod ON kb_team_lead FOR UPDATE USING (kb_principal_is_admin());
DROP POLICY IF EXISTS p_teamlead_admin_del ON kb_team_lead;
CREATE POLICY p_teamlead_admin_del ON kb_team_lead FOR DELETE USING (kb_principal_is_admin());

-- org_pricing_add_version: admin-gated, monotonic, atomic. Advisory xact lock per
-- model serializes concurrent admins so versions are gap-free; the pointer upsert
-- creates the pointer on first insert (no pre-existing row to FOR UPDATE).
CREATE OR REPLACE FUNCTION org_pricing_add_version(
  p_provider TEXT, p_model TEXT,
  p_input NUMERIC, p_output NUMERIC, p_cache_read NUMERIC, p_cache_write NUMERIC
) RETURNS BIGINT
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE v BIGINT;
BEGIN
  IF NOT kb_principal_is_admin() THEN
    RAISE EXCEPTION 'org_pricing_add_version: admin only' USING ERRCODE = '42501';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtext('orgprice:' || p_model));
  SELECT COALESCE(max(version), 0) + 1 INTO v FROM org_model_pricing WHERE billable_model = p_model;
  INSERT INTO org_model_pricing(provider, billable_model, version,
      input_usd_per_mtok, output_usd_per_mtok, cache_read_usd_per_mtok, cache_write_usd_per_mtok)
    VALUES (p_provider, p_model, v, p_input, p_output, p_cache_read, p_cache_write);
  INSERT INTO org_model_pricing_current(billable_model, version) VALUES (p_model, v)
    ON CONFLICT (billable_model) DO UPDATE SET version = EXCLUDED.version, updated_at = pg_now_text();
  RETURN v;
END; $$;

ALTER TABLE org_token_audit ALTER COLUMN estimated_cost_usd TYPE NUMERIC(38,10);
ALTER TABLE org_spend_rollup ALTER COLUMN cost_usd TYPE NUMERIC(38,10);


-- org_pricing_current(model) -> current version (admin/definer only). Egress paths
-- do NOT call this; they call org_token_estimate_cost. Returns 0 if unpriced.
CREATE OR REPLACE FUNCTION org_pricing_current_version(p_model TEXT) RETURNS BIGINT
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT COALESCE((SELECT version FROM org_model_pricing_current WHERE billable_model = p_model), 0);
$$;

-- org_token_estimate_cost: the ONLY pricing surface the egress path touches. Reads
-- the pinned immutable price row as the definer (owner, bypasses ENABLE-not-FORCE
-- RLS) and returns ONLY the NUMERIC cost — never the raw per-mtok prices. If the
-- (model, version) row is absent, returns NULL (caller must handle unpriced).
CREATE OR REPLACE FUNCTION org_token_estimate_cost(
  p_model TEXT, p_version BIGINT,
  p_prompt BIGINT, p_completion BIGINT, p_cache_read BIGINT, p_cache_write BIGINT
) RETURNS NUMERIC
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public AS $$
DECLARE p org_model_pricing%ROWTYPE;
BEGIN
  SELECT * INTO p FROM org_model_pricing WHERE billable_model = p_model AND version = p_version;
  IF NOT FOUND THEN RETURN NULL; END IF;
  RETURN (p_prompt::numeric      * p.input_usd_per_mtok
        + p_completion::numeric   * p.output_usd_per_mtok
        + p_cache_read::numeric    * p.cache_read_usd_per_mtok
        + p_cache_write::numeric   * p.cache_write_usd_per_mtok) / 1000000.0;
END; $$;

-- org_token_audit_start: idempotent insert. On (origin_cert_cn, request_id) conflict
-- it does NOT insert; it reads the bound row back and REJECTS if the immutable triple
-- (team, project, billable_model, pricing_version) differs (uniqueness alone can't
-- enforce triple equality). Returns the row id.
CREATE OR REPLACE FUNCTION org_token_audit_start(
  p_request_id TEXT, p_origin_cn TEXT, p_actor_issuer TEXT, p_actor_subject TEXT,
  p_team BIGINT, p_project BIGINT, p_billable_model TEXT, p_pricing_version BIGINT,
  p_session TEXT, p_delegation TEXT
) RETURNS BIGINT
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE rid BIGINT; ex org_token_audit%ROWTYPE;
BEGIN
  INSERT INTO org_token_audit(request_id, origin_cert_cn, actor_issuer, actor_subject,
      team_id, project_id, billable_model, pricing_version, session_id, delegation_id, state)
    VALUES (p_request_id, p_origin_cn, p_actor_issuer, p_actor_subject,
      p_team, p_project, p_billable_model, p_pricing_version, p_session, p_delegation, 'started')
    ON CONFLICT (origin_cert_cn, request_id) DO NOTHING
    RETURNING id INTO rid;
  IF rid IS NOT NULL THEN RETURN rid; END IF;
  SELECT * INTO ex FROM org_token_audit WHERE origin_cert_cn = p_origin_cn AND request_id = p_request_id;
  IF ex.team_id         IS DISTINCT FROM p_team
  OR ex.project_id      IS DISTINCT FROM p_project
  OR ex.billable_model  IS DISTINCT FROM p_billable_model
  OR ex.pricing_version IS DISTINCT FROM p_pricing_version THEN
    RAISE EXCEPTION 'org_token_audit_start: replay of (%,%) with mismatched attributes',
      p_origin_cn, p_request_id USING ERRCODE = '23505';
  END IF;
  RETURN ex.id;
END; $$;

-- org_token_audit_settle: state-checked terminal settle + same-txn rollup delta.
-- The UPDATE ... WHERE state IN ('started','indeterminate') is the concurrency
-- primitive: a concurrent/second settle of an already-terminal row matches no row
-- (returns false), so the rollup delta is applied exactly once. Rollup is written
-- ONLY for realized terminal states (not 'indeterminate'), so an indeterminate ->
-- settled reconciliation contributes exactly once (no double-count).
CREATE OR REPLACE FUNCTION org_token_audit_settle(
  p_origin_cn TEXT, p_request_id TEXT, p_state TEXT, p_served_model TEXT,
  p_prompt BIGINT, p_completion BIGINT, p_cache_read BIGINT, p_cache_write BIGINT,
  p_cost NUMERIC, p_day TEXT
) RETURNS BOOLEAN
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE r org_token_audit%ROWTYPE;
BEGIN
  IF p_state NOT IN ('settled_success','settled_denied','settled_failed','indeterminate') THEN
    RAISE EXCEPTION 'org_token_audit_settle: bad terminal state %', p_state USING ERRCODE = '22023';
  END IF;
  UPDATE org_token_audit
     SET state = p_state, served_model = p_served_model,
         prompt_tokens = p_prompt, completion_tokens = p_completion,
         cache_read_tokens = p_cache_read, cache_write_tokens = p_cache_write,
         estimated_cost_usd = p_cost, settled_at = pg_now_text()
   WHERE origin_cert_cn = p_origin_cn AND request_id = p_request_id
     AND state IN ('started','indeterminate')
   RETURNING * INTO r;
  IF NOT FOUND THEN RETURN false; END IF;
  IF p_state IN ('settled_success','settled_denied','settled_failed') THEN
    INSERT INTO org_spend_rollup(team_id, project_id, billable_model, day,
        prompt_tokens, completion_tokens, cache_read_tokens, cache_write_tokens, cost_usd, row_count)
      VALUES (r.team_id, r.project_id, r.billable_model, p_day,
        p_prompt, p_completion, p_cache_read, p_cache_write, p_cost, 1)
      ON CONFLICT (team_id, (COALESCE(project_id, 0)), billable_model, day) DO UPDATE
        SET prompt_tokens     = org_spend_rollup.prompt_tokens     + EXCLUDED.prompt_tokens,
            completion_tokens = org_spend_rollup.completion_tokens + EXCLUDED.completion_tokens,
            cache_read_tokens = org_spend_rollup.cache_read_tokens + EXCLUDED.cache_read_tokens,
            cache_write_tokens= org_spend_rollup.cache_write_tokens+ EXCLUDED.cache_write_tokens,
            cost_usd          = org_spend_rollup.cost_usd          + EXCLUDED.cost_usd,
            row_count         = org_spend_rollup.row_count         + 1,
            updated_at        = pg_now_text();
  END IF;
  RETURN true;
END; $$;

-- P3b ORG SPEND REPORTING (tiered-llm-p3b). Read-only authorized aggregation over
-- org_spend_rollup — the authoritative reporting source (maintained in the P3a settle
-- txn; rollup-ONLY, no ledger variant, so there is no rollup-vs-ledger drift contract).
-- SECURITY DEFINER so it bypasses ENABLE-not-FORCE RLS to aggregate, but the admin/lead
-- predicate is enforced INTERNALLY *before* any aggregate touches a row — the FUNCTION
-- itself is the authz gate (the table RLS it bypasses is defense-in-depth for the
-- runtime's direct SELECT, not for this path). Fail-closed order, one RAISE surface:
--   (1) date validation: p_since/p_until must be ISO 'YYYY-MM-DD', cast validly to
--       ::date (catches a well-formed-but-invalid calendar date like 2026-13-40), and
--       p_since <= p_until, else RAISE 22007 with a 'bad date' message;
--   (2) principal: p_team IS NULL (org-wide) requires kb_principal_is_admin() EXPLICITLY
--       (never relying on is_team_lead(NULL) being false); a concrete p_team requires
--       admin OR is_team_lead(p_team). Else RAISE 42501 'not authorized'.
-- Only AFTER both gates pass does it aggregate. cost_usd stays NUMERIC end-to-end (the C
-- layer reads it as TEXT, never a float) so finance export loses no precision. The C
-- layer derives the total + per-project breakdown from these grouped rows (ONE authz
-- path). NO org_spend_query_audit variant (deferred with an explicit watermark).
CREATE OR REPLACE FUNCTION org_spend_query(
  p_team BIGINT, p_project BIGINT, p_since TEXT, p_until TEXT
) RETURNS TABLE(
  team_id BIGINT, project_id BIGINT, billable_model TEXT,
  prompt_tokens BIGINT, completion_tokens BIGINT,
  cache_read_tokens BIGINT, cache_write_tokens BIGINT,
  cost_usd NUMERIC, calls BIGINT
)
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public AS $$
BEGIN
  -- (1) Strict date validation FIRST — fail closed before authz or any aggregate.
  IF p_since IS NULL OR p_until IS NULL
     OR p_since !~ '^\d{4}-\d{2}-\d{2}$' OR p_until !~ '^\d{4}-\d{2}-\d{2}$' THEN
    RAISE EXCEPTION 'org_spend_query: bad date format (want YYYY-MM-DD)' USING ERRCODE = '22007';
  END IF;
  -- Cast to ::date to reject a well-formed-but-invalid calendar date; normalize any
  -- cast SQLSTATE (22007 invalid_datetime_format / 22008 datetime_field_overflow) onto
  -- the single 'bad date' RAISE surface the C layer maps to the baddate sentinel.
  BEGIN
    PERFORM p_since::date, p_until::date;
  EXCEPTION WHEN invalid_datetime_format OR datetime_field_overflow THEN
    RAISE EXCEPTION 'org_spend_query: bad date value' USING ERRCODE = '22007';
  END;
  IF p_since::date > p_until::date THEN
    RAISE EXCEPTION 'org_spend_query: bad date range (since after until)' USING ERRCODE = '22007';
  END IF;

  -- (2) Principal authz. NULL team = org-wide -> admin ONLY (explicit); a concrete
  -- team -> admin OR that team's lead. is_team_lead(NULL) returns false (documented),
  -- but the NULL path never reaches it — admin is required explicitly.
  IF p_team IS NULL THEN
    IF NOT kb_principal_is_admin() THEN
      RAISE EXCEPTION 'org_spend_query: not authorized (org-wide report is admin-only)'
        USING ERRCODE = '42501';
    END IF;
  ELSE
    IF NOT (kb_principal_is_admin() OR is_team_lead(p_team)) THEN
      RAISE EXCEPTION 'org_spend_query: not authorized (not admin or lead of team %)', p_team
        USING ERRCODE = '42501';
    END IF;
  END IF;

  -- (3) Aggregate. Reached ONLY once both gates pass. Grouped by (team, project, model)
  -- so an org-wide (p_team IS NULL) admin report preserves the team dimension — two
  -- teams' rows for the same (project, model) never merge. 'calls' is the summed rollup
  -- row_count. Lexicographic BETWEEN is valid for the zero-padded ISO 'day' TEXT column.
  RETURN QUERY
    SELECT r.team_id, r.project_id, r.billable_model,
           SUM(r.prompt_tokens)::bigint, SUM(r.completion_tokens)::bigint,
           SUM(r.cache_read_tokens)::bigint, SUM(r.cache_write_tokens)::bigint,
           SUM(r.cost_usd)::numeric, SUM(r.row_count)::bigint
      FROM org_spend_rollup r
     WHERE r.day BETWEEN p_since AND p_until
       AND (p_team IS NULL OR r.team_id = p_team)
       AND (p_project IS NULL OR r.project_id = p_project)
     GROUP BY r.team_id, r.project_id, r.billable_model
     ORDER BY r.team_id, r.project_id NULLS LAST, r.billable_model;
END; $$;

-- These SECURITY DEFINER functions are never PUBLIC; EXECUTE is granted to the
-- runtime role out of band in schema_grants.sql (hardened tier only).
REVOKE ALL ON FUNCTION org_pricing_add_version(TEXT,TEXT,NUMERIC,NUMERIC,NUMERIC,NUMERIC) FROM PUBLIC;
REVOKE ALL ON FUNCTION org_pricing_current_version(TEXT) FROM PUBLIC;
REVOKE ALL ON FUNCTION org_token_estimate_cost(TEXT,BIGINT,BIGINT,BIGINT,BIGINT,BIGINT) FROM PUBLIC;
REVOKE ALL ON FUNCTION org_token_audit_start(TEXT,TEXT,TEXT,TEXT,BIGINT,BIGINT,TEXT,BIGINT,TEXT,TEXT) FROM PUBLIC;
REVOKE ALL ON FUNCTION org_token_audit_settle(TEXT,TEXT,TEXT,TEXT,BIGINT,BIGINT,BIGINT,BIGINT,NUMERIC,TEXT) FROM PUBLIC;
REVOKE ALL ON FUNCTION org_spend_query(BIGINT,BIGINT,TEXT,TEXT) FROM PUBLIC;

-- ============================================================================
-- P10 KB CREDENTIAL VAULT (tiered-llm-p10 slice 2). The kb org vault's ciphertext
-- store: envelope-encrypted secrets (a per-credential DEK AES-KW-wrapped under a
-- custody-derived KEK, secret AES-256-GCM'd under the DEK). Stores ONLY ciphertext
-- — never a plaintext key, never the KEK (that lives behind custody, off-DB).
--
-- Reuses two proven substrates:
--   * P1 tenancy (kb_team, kb_team_membership, kb_principal_is_admin, aimee.principal)
--     for team-scoped RLS;
--   * P3a's version-pointer discipline (immutable version rows + a current-version
--     pointer advanced atomically inside a SECURITY DEFINER writer under an advisory
--     xact lock), so rotation later is purely additive (no in-place mutate migration).
--
-- RLS posture: ENABLE (not FORCE) ROW LEVEL SECURITY — mirrors P3a. The owner-scoped
-- SECURITY DEFINER functions bypass RLS to read/write; the non-owner NOBYPASSRLS
-- runtime role's DIRECT table reads stay tenant-filtered (tenant sees only team_id IN
-- its memberships; platform-scoped team_id IS NULL rows are admin-only) — this is the
-- ciphertext-at-rest / invariant-#10 boundary (a DB dump or a direct runtime connection
-- yields no cross-tenant plaintext, and org-key CONFIDENTIALITY ultimately rests on the
-- custody KEK, which never enters Postgres). The SECURITY DEFINER function API is the
-- trusted-service read/write path; per-REQUEST tenant authorization (which principal a
-- given request may touch) is enforced at the service layer — the slice-3 kb_vault
-- accessor and the later use-in-place primitive — NOT by these functions. This is the
-- P7 model: crypto per-slot isolation + service-enforced access + ciphertext-at-rest
-- RLS. This slice stores NO keys — plumbing + tests only (P7 §3: the file-custody kb
-- vault is single-instance dev mode; the CA-key-in-vault activation fails closed on a
-- hardened/multi-instance deployment until the external-anchor + seal slice lands).
-- ============================================================================

-- org_vault_salt: ONE row per vault principal. `salt` seeds the custody KEK; a single
-- `kek_check` verifier per principal (NOT per secret) lets unlock prove a derived KEK
-- is correct without a guess-a-KEK oracle. kek_check stays '' until the first unlock
-- establishes it (the AES-KW wrap of a fixed sentinel under the KEK).
CREATE TABLE IF NOT EXISTS org_vault_salt (
  principal  TEXT PRIMARY KEY CHECK (char_length(principal) BETWEEN 1 AND 600),
  salt       BYTEA NOT NULL,
  kek_check  BYTEA NOT NULL DEFAULT '',
  created_at TEXT NOT NULL DEFAULT (pg_now_text())
);

-- org_vault_secret: IMMUTABLE envelope-encrypted credential version rows. team_id
-- NULL = platform-scoped (e.g. the kb CA key, slice 3); NOT NULL = a team-scoped
-- tenant secret. The AEAD AAD binds (principal|agent|cred|version), so a restored
-- older-version ciphertext cannot be presented as current — the AAD itself refuses it.
-- A new version is a NEW row (never an in-place mutate). Slice 2 writes version 1.
CREATE TABLE IF NOT EXISTS org_vault_secret (
  id          BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  principal   TEXT NOT NULL CHECK (char_length(principal) BETWEEN 1 AND 600),
  team_id     BIGINT REFERENCES kb_team(id) ON DELETE CASCADE,
  agent       TEXT NOT NULL DEFAULT '',
  cred        TEXT NOT NULL DEFAULT '',
  version     BIGINT NOT NULL CHECK (version >= 1),
  wrapped_dek BYTEA NOT NULL,
  nonce       BYTEA NOT NULL,
  ciphertext  BYTEA NOT NULL,
  tag         BYTEA NOT NULL,
  created_at  TEXT NOT NULL DEFAULT (pg_now_text()),
  UNIQUE(principal, agent, cred, version)
);
ALTER TABLE org_vault_secret ADD COLUMN IF NOT EXISTS hwm_attestation BYTEA;
CREATE INDEX IF NOT EXISTS idx_org_vault_secret_team ON org_vault_secret(team_id);
CREATE INDEX IF NOT EXISTS idx_org_vault_secret_slot ON org_vault_secret(principal, agent, cred);

-- org_vault_current: the current-version pointer per (principal, agent, cred) slot,
-- advanced atomically with the new immutable row inside org_vault_put(). The FK
-- guarantees the pointer always names a real version row.
CREATE TABLE IF NOT EXISTS org_vault_current (
  principal  TEXT NOT NULL,
  agent      TEXT NOT NULL DEFAULT '',
  cred       TEXT NOT NULL DEFAULT '',
  version    BIGINT NOT NULL,
  updated_at TEXT NOT NULL DEFAULT (pg_now_text()),
  PRIMARY KEY (principal, agent, cred),
  FOREIGN KEY (principal, agent, cred, version)
    REFERENCES org_vault_secret(principal, agent, cred, version)
);

-- ENABLE (not FORCE) RLS on all three, mirroring P3a: the owner-scoped SECURITY
-- DEFINER functions bypass RLS to read/write, while the non-owner NOBYPASSRLS runtime
-- role's DIRECT table reads stay tenant-filtered by the SELECT policies below.
-- missing_ok=true on current_setting yields NULL -> no rows (fail-closed) when a GUC
-- is unset.
DO $$
DECLARE t TEXT;
BEGIN
  FOREACH t IN ARRAY ARRAY['org_vault_salt','org_vault_secret','org_vault_current']
  LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
  END LOOP;
END $$;

-- org_vault_secret reads. Two permissive SELECT policies OR together:
--   (1) tenant read: a caller sees ONLY team-scoped rows (team_id IS NOT NULL) whose
--       team is in its own memberships — platform-scoped rows (team_id IS NULL) fail
--       the `team_id IS NOT NULL` clause and are thus NEVER a tenant read;
--   (2) admin read: an org-admin sees all rows, incl. the platform-scoped CA key —
--       the ONLY read path to a team_id IS NULL row.
DROP POLICY IF EXISTS p_vault_secret_tenant_read ON org_vault_secret;
CREATE POLICY p_vault_secret_tenant_read ON org_vault_secret FOR SELECT
  USING (team_id IS NOT NULL
         AND team_id IN (SELECT team FROM kb_team_membership
                         WHERE identity_key = current_setting('aimee.principal', true)));
DROP POLICY IF EXISTS p_vault_secret_admin_read ON org_vault_secret;
CREATE POLICY p_vault_secret_admin_read ON org_vault_secret FOR SELECT
  USING (kb_principal_is_admin());
-- org_vault_secret writes: no direct DML path. Under ENABLE-not-FORCE the owner-run
-- SECURITY DEFINER writers bypass RLS, and the runtime role holds no direct INSERT/
-- UPDATE/DELETE grant (schema_grants.sql REVOKE) — so no write policy is needed.

-- org_vault_current + org_vault_salt: the pointer + salt/verifier carry no ciphertext,
-- only version numbers / KEK-check bytes. Direct reads are admin-only (the backend
-- reads them through the SECURITY DEFINER helpers); writes go through the owner-run
-- definers, which bypass RLS under ENABLE — no write policy needed.
DROP POLICY IF EXISTS p_vault_current_admin_read ON org_vault_current;
CREATE POLICY p_vault_current_admin_read ON org_vault_current FOR SELECT
  USING (kb_principal_is_admin());
DROP POLICY IF EXISTS p_vault_salt_admin_read ON org_vault_salt;
CREATE POLICY p_vault_salt_admin_read ON org_vault_salt FOR SELECT
  USING (kb_principal_is_admin());

-- P7 whole-vault maintenance admission barrier.  This singleton is owned by the
-- database owner and deliberately has no RLS policy or runtime table API.  Later
-- orchestration slices will add narrowly scoped transitions which take FOR UPDATE;
-- steady-state entrypoints retain a conflicting FOR SHARE lock until commit.
CREATE TABLE IF NOT EXISTS kb_vault_control (
  singleton        SMALLINT PRIMARY KEY DEFAULT 1 CHECK (singleton = 1),
  sealed           BOOLEAN NOT NULL DEFAULT false,
  seal_epoch       BIGINT NOT NULL DEFAULT 1 CHECK (seal_epoch > 0),
  maintenance_kind TEXT NOT NULL DEFAULT '' CHECK (char_length(maintenance_kind) <= 64),
  maintenance_id   TEXT NOT NULL DEFAULT '' CHECK (char_length(maintenance_id) <= 200),
  fencing_token    BIGINT NOT NULL DEFAULT 1 CHECK (fencing_token > 0),
  last_opened_rewrap_fence BIGINT NOT NULL DEFAULT 0,
  updated_at       TEXT NOT NULL DEFAULT (pg_now_text()),
  CHECK ((maintenance_kind = '') = (maintenance_id = '')),
  CHECK (sealed OR (maintenance_kind = '' AND maintenance_id = ''))
);
INSERT INTO kb_vault_control(singleton) VALUES (1) ON CONFLICT (singleton) DO NOTHING;
ALTER TABLE kb_vault_control ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE kb_vault_control FROM PUBLIC;

-- Narrow startup seam: runtime may synchronize the process-local primary epoch
-- without receiving direct table access and without requiring the vault open.
CREATE OR REPLACE FUNCTION org_vault_control_startup_status()
RETURNS TABLE(seal_epoch BIGINT,sealed BOOLEAN)
LANGUAGE plpgsql VOLATILE SECURITY DEFINER
SET search_path=pg_catalog,public,pg_temp AS $$
BEGIN
  PERFORM pg_advisory_xact_lock_shared(-7046029254386353131::BIGINT);
  RETURN QUERY SELECT c.seal_epoch,c.sealed
    FROM public.kb_vault_control AS c
   WHERE c.singleton=1 FOR SHARE;
END
$$;
REVOKE ALL ON FUNCTION org_vault_control_startup_status() FROM PUBLIC;

CREATE OR REPLACE FUNCTION org_vault_control_require_open() RETURNS BIGINT
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = public AS $$
DECLARE v_epoch BIGINT; v_sealed BOOLEAN; v_kind TEXT; v_id TEXT;
BEGIN
  PERFORM pg_advisory_xact_lock_shared(-7046029254386353131::BIGINT);
  SELECT seal_epoch,sealed,maintenance_kind,maintenance_id
    INTO v_epoch,v_sealed,v_kind,v_id
    FROM kb_vault_control WHERE singleton=1 FOR SHARE;
  IF NOT FOUND OR v_sealed OR v_kind<>'' OR v_id<>'' THEN
    RAISE EXCEPTION 'org_vault_control: sealed' USING ERRCODE='55000';
  END IF;
  RETURN v_epoch;
END; $$;
REVOKE ALL ON FUNCTION org_vault_control_require_open() FROM PUBLIC;

-- Owner/orchestrator-only writer gate.  It deliberately mutates nothing; later
-- reseal slices must acquire this lock before their atomic control-row UPDATE.
-- The fixed 64-bit key is shared only with org_vault_control_require_open.
CREATE OR REPLACE FUNCTION org_vault_control_lock_exclusive() RETURNS BIGINT
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = public AS $$
DECLARE v_epoch BIGINT;
BEGIN
  PERFORM pg_advisory_xact_lock(-7046029254386353131::BIGINT);
  SELECT seal_epoch INTO v_epoch FROM kb_vault_control WHERE singleton=1 FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'org_vault_control: missing' USING ERRCODE='55000';
  END IF;
  RETURN v_epoch;
END; $$;
REVOKE ALL ON FUNCTION org_vault_control_lock_exclusive() FROM PUBLIC;

-- org_vault_salt_ensure: insert the principal's salt row if absent, return the effective
-- salt (idempotent; the first writer wins so two concurrent unlocks converge on one salt).
CREATE OR REPLACE FUNCTION org_vault_salt_ensure(p_principal TEXT, p_salt BYTEA) RETURNS BYTEA
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE s BYTEA;
BEGIN
  PERFORM org_vault_control_require_open();
  INSERT INTO org_vault_salt(principal, salt) VALUES (p_principal, p_salt)
    ON CONFLICT (principal) DO NOTHING;
  SELECT salt INTO s FROM org_vault_salt WHERE principal = p_principal;
  RETURN s;
END; $$;

-- org_vault_salt_read: an existing principal's salt, or NULL if none (no create) — the
-- readonly path so a rekey against a non-existent principal fails closed.
CREATE OR REPLACE FUNCTION org_vault_salt_read(p_principal TEXT) RETURNS BYTEA
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT salt FROM org_vault_salt WHERE principal = p_principal;
$$;

-- org_vault_kek_check_read: the principal's KEK verifier. NULL = no salt row (unlock
-- called before salt); ''::bytea = a salt row whose verifier is not yet established.
CREATE OR REPLACE FUNCTION org_vault_kek_check_read(p_principal TEXT) RETURNS BYTEA
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT kek_check FROM org_vault_salt WHERE principal = p_principal;
$$;

-- org_vault_kek_check_set: establish the KEK verifier for a principal on FIRST unlock.
-- The UPDATE is conditional on kek_check still being '' (unset), so two concurrent
-- first-unlocks cannot clobber each other — only the first writer, while the verifier
-- is still empty, wins. The caller re-reads the stored verifier afterwards to confirm
-- its KEK matches the winner's (see vault_pg_unlock_check).
CREATE OR REPLACE FUNCTION org_vault_kek_check_set(p_principal TEXT, p_check BYTEA) RETURNS VOID
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
BEGIN
  PERFORM org_vault_control_require_open();
  UPDATE org_vault_salt SET kek_check = p_check
   WHERE principal = p_principal AND kek_check = '';
END; $$;

-- org_vault_put: append an immutable version row + advance the pointer atomically. The
-- advisory xact lock per slot serializes writers so versions are gap-free. p_team_id
-- NULL = platform-scoped. p_expected_version is the version the caller AAD-bound the
-- ciphertext to; if a concurrent write already advanced the slot (expected <> max+1)
-- the function RAISES (serialization_failure) so a stale-AAD ciphertext is never stored
-- — the loser retries. Returns the version written.
CREATE OR REPLACE FUNCTION org_vault_put(
  p_principal TEXT, p_team_id BIGINT, p_agent TEXT, p_cred TEXT, p_expected_version BIGINT,
  p_wrapped_dek BYTEA, p_nonce BYTEA, p_ciphertext BYTEA, p_tag BYTEA
) RETURNS BIGINT
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE v BIGINT; v_rot BOOLEAN := false;
BEGIN
  PERFORM org_vault_control_require_open();
  PERFORM pg_advisory_xact_lock(hashtext('orgvault:' || p_principal || '|' || p_agent || '|' || p_cred));
  IF to_regclass('public.org_vault_rotation') IS NOT NULL THEN
    EXECUTE 'SELECT EXISTS(SELECT 1 FROM org_vault_rotation WHERE principal=$1 AND agent=$2 '
            'AND cred=$3 AND state<>''retired'')'
      INTO v_rot USING p_principal,p_agent,p_cred;
  END IF;
  IF v_rot THEN
    RAISE EXCEPTION 'org_vault_put: active rotation conflict' USING ERRCODE='40001';
  END IF;
  SELECT COALESCE(max(version), 0) + 1 INTO v FROM org_vault_secret
    WHERE principal = p_principal AND agent = p_agent AND cred = p_cred;
  IF p_expected_version IS NOT NULL AND p_expected_version <> v THEN
    RAISE EXCEPTION 'org_vault_put: version race for (%,%,%) expected % got %',
      p_principal, p_agent, p_cred, p_expected_version, v USING ERRCODE = '40001';
  END IF;
  INSERT INTO org_vault_secret(principal, team_id, agent, cred, version,
      wrapped_dek, nonce, ciphertext, tag)
    VALUES (p_principal, p_team_id, p_agent, p_cred, v,
      p_wrapped_dek, p_nonce, p_ciphertext, p_tag);
  INSERT INTO org_vault_current(principal, agent, cred, version)
    VALUES (p_principal, p_agent, p_cred, v)
    ON CONFLICT (principal, agent, cred)
      DO UPDATE SET version = EXCLUDED.version, updated_at = pg_now_text();
  RETURN v;
END; $$;

-- org_vault_get_current: the current version's envelope for a slot (empty set if the
-- slot has no current pointer) — the backend use-path read.
CREATE OR REPLACE FUNCTION org_vault_get_current(p_principal TEXT, p_agent TEXT, p_cred TEXT)
RETURNS TABLE(version BIGINT, wrapped_dek BYTEA, nonce BYTEA, ciphertext BYTEA, tag BYTEA)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT s.version, s.wrapped_dek, s.nonce, s.ciphertext, s.tag
    FROM org_vault_current c
    JOIN org_vault_secret s
      ON s.principal = c.principal AND s.agent = c.agent AND s.cred = c.cred AND s.version = c.version
   WHERE c.principal = p_principal AND c.agent = p_agent AND c.cred = p_cred;
$$;

-- org_vault_has: the current version of a slot (>=1), or 0 if it has none.
CREATE OR REPLACE FUNCTION org_vault_has(p_principal TEXT, p_agent TEXT, p_cred TEXT) RETURNS BIGINT
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT COALESCE((SELECT version FROM org_vault_current
                   WHERE principal = p_principal AND agent = p_agent AND cred = p_cred), 0);
$$;

-- org_vault_list: the (agent, cred) slots that currently exist for a principal.
CREATE OR REPLACE FUNCTION org_vault_list(p_principal TEXT)
RETURNS TABLE(agent TEXT, cred TEXT)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT agent, cred FROM org_vault_current WHERE principal = p_principal ORDER BY agent, cred;
$$;

-- org_vault_list_principals: distinct principals with at least one current slot.
CREATE OR REPLACE FUNCTION org_vault_list_principals()
RETURNS TABLE(principal TEXT)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT DISTINCT principal FROM org_vault_current ORDER BY principal;
$$;

-- org_vault_delete: drop a slot (its pointer + every version row). Pointer first so the
-- version rows are no longer referenced by the FK.
CREATE OR REPLACE FUNCTION org_vault_delete(p_principal TEXT, p_agent TEXT, p_cred TEXT) RETURNS VOID
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE v_rot BOOLEAN := false;
BEGIN
  PERFORM org_vault_control_require_open();
  PERFORM pg_advisory_xact_lock(hashtext('orgvault:'||p_principal||'|'||p_agent||'|'||p_cred));
  IF to_regclass('public.org_vault_rotation') IS NOT NULL THEN
    EXECUTE 'SELECT EXISTS(SELECT 1 FROM org_vault_rotation WHERE principal=$1 AND agent=$2 '
            'AND cred=$3 AND state<>''retired'')'
      INTO v_rot USING p_principal,p_agent,p_cred;
  END IF;
  IF v_rot THEN
    RAISE EXCEPTION 'org_vault_delete: active rotation conflict' USING ERRCODE='40001';
  END IF;
  DELETE FROM org_vault_current WHERE principal = p_principal AND agent = p_agent AND cred = p_cred;
  DELETE FROM org_vault_secret  WHERE principal = p_principal AND agent = p_agent AND cred = p_cred;
END; $$;

-- org_vault_current_wraps: (agent, cred, version, wrapped_dek) for every current slot of
-- a principal — the rekey read-side (re-wrap each DEK under a new KEK; ciphertext untouched).
CREATE OR REPLACE FUNCTION org_vault_current_wraps(p_principal TEXT)
RETURNS TABLE(agent TEXT, cred TEXT, version BIGINT, wrapped_dek BYTEA)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT s.agent, s.cred, s.version, s.wrapped_dek
    FROM org_vault_current c
    JOIN org_vault_secret s
      ON s.principal = c.principal AND s.agent = c.agent AND s.cred = c.cred AND s.version = c.version
   WHERE c.principal = p_principal;
$$;

-- org_vault_rewrap: replace the wrapped_dek of one current version row (rekey write-side;
-- nonce/ciphertext/tag untouched — a re-wrap, not a re-encrypt).
CREATE OR REPLACE FUNCTION org_vault_rewrap(
  p_principal TEXT, p_agent TEXT, p_cred TEXT, p_version BIGINT, p_wrapped_dek BYTEA
) RETURNS VOID
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE v_rot BOOLEAN := false;
BEGIN
  PERFORM org_vault_control_require_open();
  PERFORM pg_advisory_xact_lock(hashtext('orgvault:'||p_principal||'|'||p_agent||'|'||p_cred));
  IF to_regclass('public.org_vault_rotation') IS NOT NULL THEN
    EXECUTE 'SELECT EXISTS(SELECT 1 FROM org_vault_rotation WHERE principal=$1 AND agent=$2 '
            'AND cred=$3 AND state<>''retired'')'
      INTO v_rot USING p_principal,p_agent,p_cred;
  END IF;
  IF v_rot THEN
    RAISE EXCEPTION 'org_vault_rewrap: active rotation conflict' USING ERRCODE='40001';
  END IF;
  UPDATE org_vault_secret SET wrapped_dek = p_wrapped_dek
   WHERE principal = p_principal AND agent = p_agent AND cred = p_cred AND version = p_version;
END; $$;

-- P7 §8: durable, anchor-authoritative per-credential rotation. A staged N+1
-- is inert until the external custody anchor has atomically advanced N -> N+1;
-- only org_vault_rotation_finalize then moves the database pointer. The external
-- CAS is deliberately outside these transactions, and recovery classifies the
-- signed anchor read before deciding whether to retry CAS or finalize.
CREATE TABLE IF NOT EXISTS org_vault_rotation (
  id              BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  key_id          TEXT NOT NULL CHECK (char_length(key_id) BETWEEN 1 AND 600),
  principal       TEXT NOT NULL CHECK (char_length(principal) BETWEEN 1 AND 600),
  team_id         BIGINT REFERENCES kb_team(id) ON DELETE CASCADE,
  agent           TEXT NOT NULL DEFAULT '' CHECK (char_length(agent) <= 255),
  cred            TEXT NOT NULL DEFAULT '' CHECK (char_length(cred) <= 255),
  from_version    BIGINT NOT NULL CHECK (from_version >= 1),
  to_version      BIGINT NOT NULL CHECK (to_version = from_version + 1),
  state           TEXT NOT NULL CHECK (state IN
                    ('provision','staged','probed','activating','activated','revoked','retired','failed')),
  compromise      BOOLEAN NOT NULL DEFAULT false,
  hwm_attestation BYTEA,
  old_vendor_ref  TEXT NOT NULL DEFAULT '' CHECK (char_length(old_vendor_ref) <= 512),
  new_vendor_ref  TEXT NOT NULL DEFAULT '' CHECK (char_length(new_vendor_ref) <= 512),
  revoke_receipt  TEXT NOT NULL DEFAULT '' CHECK (char_length(revoke_receipt) <= 512),
  failure_phase   TEXT NOT NULL DEFAULT '' CHECK (char_length(failure_phase) <= 32),
  claim_owner     TEXT NOT NULL DEFAULT '' CHECK (char_length(claim_owner) <= 200),
  claim_token     BIGINT NOT NULL DEFAULT 0 CHECK (claim_token >= 0),
  claim_until     TIMESTAMPTZ,
  last_error      TEXT NOT NULL DEFAULT '' CHECK (char_length(last_error) <= 1000),
  created_at      TEXT NOT NULL DEFAULT (pg_now_text()),
  updated_at      TEXT NOT NULL DEFAULT (pg_now_text()),
  UNIQUE(principal, agent, cred, to_version)
);
-- CREATE TABLE IF NOT EXISTS does not evolve an existing generated CHECK.
ALTER TABLE org_vault_rotation DROP CONSTRAINT IF EXISTS org_vault_rotation_state_check;
ALTER TABLE org_vault_rotation ADD CONSTRAINT org_vault_rotation_state_check CHECK (state IN
  ('provision','staged','probed','activating','activated','revoked','retired','failed'));
ALTER TABLE org_vault_rotation ADD COLUMN IF NOT EXISTS old_vendor_ref TEXT NOT NULL DEFAULT '';
ALTER TABLE org_vault_rotation ADD COLUMN IF NOT EXISTS new_vendor_ref TEXT NOT NULL DEFAULT '';
ALTER TABLE org_vault_rotation ADD COLUMN IF NOT EXISTS revoke_receipt TEXT NOT NULL DEFAULT '';
ALTER TABLE org_vault_rotation ADD COLUMN IF NOT EXISTS failure_phase TEXT NOT NULL DEFAULT '';
ALTER TABLE org_vault_rotation ADD COLUMN IF NOT EXISTS claim_owner TEXT NOT NULL DEFAULT '';
ALTER TABLE org_vault_rotation ADD COLUMN IF NOT EXISTS claim_token BIGINT NOT NULL DEFAULT 0;
ALTER TABLE org_vault_rotation ADD COLUMN IF NOT EXISTS claim_until TIMESTAMPTZ;
-- Keep upgraded databases equivalent to fresh installs: CREATE TABLE IF NOT EXISTS
-- does not add the new column constraints to an existing P7 core table.
ALTER TABLE org_vault_rotation DROP CONSTRAINT IF EXISTS org_vault_rotation_old_vendor_ref_check;
ALTER TABLE org_vault_rotation ADD CONSTRAINT org_vault_rotation_old_vendor_ref_check
  CHECK (char_length(old_vendor_ref) <= 512);
ALTER TABLE org_vault_rotation DROP CONSTRAINT IF EXISTS org_vault_rotation_new_vendor_ref_check;
ALTER TABLE org_vault_rotation ADD CONSTRAINT org_vault_rotation_new_vendor_ref_check
  CHECK (char_length(new_vendor_ref) <= 512);
ALTER TABLE org_vault_rotation DROP CONSTRAINT IF EXISTS org_vault_rotation_revoke_receipt_check;
ALTER TABLE org_vault_rotation ADD CONSTRAINT org_vault_rotation_revoke_receipt_check
  CHECK (char_length(revoke_receipt) <= 512);
ALTER TABLE org_vault_rotation DROP CONSTRAINT IF EXISTS org_vault_rotation_failure_phase_check;
ALTER TABLE org_vault_rotation ADD CONSTRAINT org_vault_rotation_failure_phase_check
  CHECK (char_length(failure_phase) <= 32);
ALTER TABLE org_vault_rotation DROP CONSTRAINT IF EXISTS org_vault_rotation_claim_owner_check;
ALTER TABLE org_vault_rotation ADD CONSTRAINT org_vault_rotation_claim_owner_check
  CHECK (char_length(claim_owner) <= 200);
ALTER TABLE org_vault_rotation DROP CONSTRAINT IF EXISTS org_vault_rotation_claim_token_check;
ALTER TABLE org_vault_rotation ADD CONSTRAINT org_vault_rotation_claim_token_check
  CHECK (claim_token >= 0);
CREATE UNIQUE INDEX IF NOT EXISTS idx_org_vault_rotation_active_slot
  ON org_vault_rotation(principal, agent, cred)
  WHERE state <> 'retired';
CREATE UNIQUE INDEX IF NOT EXISTS idx_org_vault_rotation_active_key
  ON org_vault_rotation(key_id)
  WHERE state <> 'retired';
CREATE INDEX IF NOT EXISTS idx_org_vault_rotation_team ON org_vault_rotation(team_id);
ALTER TABLE org_vault_rotation ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS p_vault_rotation_read ON org_vault_rotation;
CREATE POLICY p_vault_rotation_read ON org_vault_rotation FOR SELECT
  USING (kb_principal_is_admin() OR
         (team_id IS NOT NULL AND team_id IN
          (SELECT team FROM kb_team_membership
            WHERE identity_key = current_setting('aimee.principal', true))));

CREATE OR REPLACE FUNCTION org_vault_rotation_authorized(p_actor TEXT,p_team_id BIGINT)
RETURNS BOOLEAN
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT p_actor=current_setting('aimee.principal',true)
     AND (kb_principal_is_admin() OR
          (p_team_id IS NOT NULL AND p_team_id IN
           (SELECT team FROM kb_team_membership
             WHERE identity_key=current_setting('aimee.principal',true))));
$$;

CREATE OR REPLACE FUNCTION org_vault_rotation_start(
  p_actor TEXT, p_key_id TEXT, p_principal TEXT, p_team_id BIGINT,
  p_agent TEXT, p_cred TEXT, p_from_version BIGINT, p_compromise BOOLEAN
) RETURNS BIGINT
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE v_id BIGINT; v_cur BIGINT; v_team BIGINT; v_row org_vault_rotation%ROWTYPE;
BEGIN
  IF COALESCE(p_actor,'') = '' OR COALESCE(p_key_id,'') = '' OR
     COALESCE(p_principal,'') = '' OR p_from_version IS NULL OR
     p_from_version < 1 OR p_from_version = 9223372036854775807 THEN
    RAISE EXCEPTION 'org_vault_rotation_start: invalid input' USING ERRCODE = '22023';
  END IF;
  IF NOT org_vault_rotation_authorized(p_actor,p_team_id) THEN
    RAISE EXCEPTION 'org_vault_rotation_start: not authorized' USING ERRCODE='42501';
  END IF;
  PERFORM org_vault_control_require_open();
  PERFORM pg_advisory_xact_lock(hashtext(
    'orgvault:' || p_principal || '|' || COALESCE(p_agent,'') || '|' || COALESCE(p_cred,'')));
  SELECT c.version,s.team_id INTO v_cur,v_team FROM org_vault_current c
    JOIN org_vault_secret s ON s.principal=c.principal AND s.agent=c.agent AND
      s.cred=c.cred AND s.version=c.version
   WHERE c.principal=p_principal AND c.agent=COALESCE(p_agent,'') AND c.cred=COALESCE(p_cred,'');
  IF v_cur IS NULL OR v_cur <> p_from_version THEN
    RAISE EXCEPTION 'org_vault_rotation_start: current version mismatch' USING ERRCODE = '40001';
  END IF;
  IF v_team IS DISTINCT FROM p_team_id THEN
    RAISE EXCEPTION 'org_vault_rotation_start: principal/team mismatch' USING ERRCODE='42501';
  END IF;
  IF EXISTS(SELECT 1 FROM org_vault_rotation WHERE principal=p_principal AND
      agent=COALESCE(p_agent,'') AND cred=COALESCE(p_cred,'') AND key_id<>p_key_id) OR
     EXISTS(SELECT 1 FROM org_vault_rotation WHERE key_id=p_key_id AND
      (principal<>p_principal OR agent<>COALESCE(p_agent,'') OR cred<>COALESCE(p_cred,''))) THEN
    RAISE EXCEPTION 'org_vault_rotation_start: key binding conflict' USING ERRCODE='40001';
  END IF;
  SELECT * INTO v_row FROM org_vault_rotation
   WHERE principal=p_principal AND agent=COALESCE(p_agent,'') AND cred=COALESCE(p_cred,'')
     AND state <> 'retired' FOR UPDATE;
  IF FOUND THEN
    IF v_row.key_id=p_key_id AND v_row.from_version=p_from_version AND
       v_row.team_id IS NOT DISTINCT FROM p_team_id AND
       v_row.compromise=COALESCE(p_compromise,false) THEN
      RETURN v_row.id;
    END IF;
    RAISE EXCEPTION 'org_vault_rotation_start: active rotation conflict' USING ERRCODE = '40001';
  END IF;
  BEGIN
    INSERT INTO org_vault_rotation(key_id,principal,team_id,agent,cred,from_version,to_version,
        state,compromise)
      VALUES(p_key_id,p_principal,p_team_id,COALESCE(p_agent,''),COALESCE(p_cred,''),
        p_from_version,p_from_version+1,'provision',COALESCE(p_compromise,false))
      RETURNING id INTO v_id;
  EXCEPTION WHEN unique_violation THEN
    RAISE EXCEPTION 'org_vault_rotation_start: concurrent key binding conflict'
      USING ERRCODE='40001';
  END;
  PERFORM kb_audit_worm_append('kb',p_actor,'vault.rotation.start',p_key_id,'allow',
    json_build_object('rotation_id',v_id,'from_version',p_from_version,
                      'to_version',p_from_version+1,'compromise',COALESCE(p_compromise,false))::text);
  RETURN v_id;
END; $$;

CREATE OR REPLACE FUNCTION org_vault_rotation_stage(
  p_actor TEXT, p_rotation_id BIGINT, p_wrapped_dek BYTEA, p_nonce BYTEA,
  p_ciphertext BYTEA, p_tag BYTEA
) RETURNS BIGINT
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE r org_vault_rotation%ROWTYPE; v_match BOOLEAN;
BEGIN
  IF COALESCE(p_actor,'')='' OR p_rotation_id IS NULL OR p_wrapped_dek IS NULL OR
     p_nonce IS NULL OR p_ciphertext IS NULL OR p_tag IS NULL THEN
    RAISE EXCEPTION 'org_vault_rotation_stage: invalid input' USING ERRCODE = '22023';
  END IF;
  SELECT * INTO r FROM org_vault_rotation WHERE id=p_rotation_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'org_vault_rotation_stage: unknown rotation'; END IF;
  IF NOT org_vault_rotation_authorized(p_actor,r.team_id) THEN
    RAISE EXCEPTION 'org_vault_rotation_stage: not authorized' USING ERRCODE='42501';
  END IF;
  PERFORM org_vault_control_require_open();
  PERFORM pg_advisory_xact_lock(hashtext('orgvault:'||r.principal||'|'||r.agent||'|'||r.cred));
  SELECT * INTO r FROM org_vault_rotation WHERE id=p_rotation_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'org_vault_rotation_stage: unknown rotation'; END IF;
  IF r.state='staged' THEN
    SELECT EXISTS(SELECT 1 FROM org_vault_secret s WHERE s.principal=r.principal AND
      s.agent=r.agent AND s.cred=r.cred AND s.version=r.to_version AND
      s.wrapped_dek=p_wrapped_dek AND s.nonce=p_nonce AND s.ciphertext=p_ciphertext AND s.tag=p_tag)
      INTO v_match;
    IF NOT v_match THEN RAISE EXCEPTION 'org_vault_rotation_stage: replay payload mismatch'; END IF;
    RETURN r.to_version;
  END IF;
  IF r.state<>'provision' THEN
    RAISE EXCEPTION 'org_vault_rotation_stage: invalid state %',r.state USING ERRCODE='40001';
  END IF;
  INSERT INTO org_vault_secret(principal,team_id,agent,cred,version,wrapped_dek,nonce,ciphertext,tag)
    VALUES(r.principal,r.team_id,r.agent,r.cred,r.to_version,p_wrapped_dek,p_nonce,p_ciphertext,p_tag);
  UPDATE org_vault_rotation SET state='staged',updated_at=pg_now_text() WHERE id=r.id;
  PERFORM kb_audit_worm_append('kb',p_actor,'vault.rotation.stage',r.key_id,'allow',
    json_build_object('rotation_id',r.id,'version',r.to_version)::text);
  RETURN r.to_version;
END; $$;

CREATE OR REPLACE FUNCTION org_vault_rotation_transition(
  p_actor TEXT, p_rotation_id BIGINT, p_expected TEXT, p_next TEXT, p_error TEXT
) RETURNS VOID
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE r org_vault_rotation%ROWTYPE;
BEGIN
  IF COALESCE(p_actor,'')='' OR COALESCE(p_expected,'')='' OR COALESCE(p_next,'')='' OR
     char_length(COALESCE(p_error,''))>1000 THEN
    RAISE EXCEPTION 'org_vault_rotation_transition: invalid input' USING ERRCODE='22023';
  END IF;
  IF NOT ((p_expected='staged' AND p_next='probed') OR
      (p_expected='probed' AND p_next='activating') OR
      (p_expected='activated' AND p_next='revoked') OR
      (p_expected='revoked' AND p_next='retired') OR
      (p_next='failed' AND p_expected IN ('provision','staged'))) THEN
    RAISE EXCEPTION 'org_vault_rotation_transition: invalid requested transition % -> %',
      p_expected,p_next USING ERRCODE='22023';
  END IF;
  SELECT * INTO r FROM org_vault_rotation WHERE id=p_rotation_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'org_vault_rotation_transition: unknown rotation'; END IF;
  IF NOT org_vault_rotation_authorized(p_actor,r.team_id) THEN
    RAISE EXCEPTION 'org_vault_rotation_transition: not authorized' USING ERRCODE='42501';
  END IF;
  PERFORM org_vault_control_require_open();
  PERFORM pg_advisory_xact_lock(hashtext('orgvault:'||r.principal||'|'||r.agent||'|'||r.cred));
  SELECT * INTO r FROM org_vault_rotation WHERE id=p_rotation_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'org_vault_rotation_transition: unknown rotation'; END IF;
  IF r.state=p_next THEN RETURN; END IF;
  IF r.state<>p_expected THEN
    RAISE EXCEPTION 'org_vault_rotation_transition: invalid transition % -> %',r.state,p_next
      USING ERRCODE='40001';
  END IF;
  UPDATE org_vault_rotation SET state=p_next,last_error=COALESCE(p_error,''),
    updated_at=pg_now_text() WHERE id=r.id;
  PERFORM kb_audit_worm_append('kb',p_actor,'vault.rotation.'||p_next,r.key_id,
    CASE WHEN p_next='failed' THEN 'deny' ELSE 'allow' END,
    json_build_object('rotation_id',r.id,'from_state',p_expected,'to_state',p_next,
                      'has_error',COALESCE(p_error,'')<>'')::text);
END; $$;

CREATE OR REPLACE FUNCTION org_vault_rotation_finalize(
  p_actor TEXT, p_rotation_id BIGINT, p_hwm_attestation BYTEA
) RETURNS VOID
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE r org_vault_rotation%ROWTYPE; v_cur BIGINT; v_att BYTEA;
BEGIN
  IF COALESCE(p_actor,'')='' OR p_hwm_attestation IS NULL OR octet_length(p_hwm_attestation)=0 THEN
    RAISE EXCEPTION 'org_vault_rotation_finalize: invalid input' USING ERRCODE='22023';
  END IF;
  SELECT * INTO r FROM org_vault_rotation WHERE id=p_rotation_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'org_vault_rotation_finalize: unknown rotation'; END IF;
  IF NOT org_vault_rotation_authorized(p_actor,r.team_id) THEN
    RAISE EXCEPTION 'org_vault_rotation_finalize: not authorized' USING ERRCODE='42501';
  END IF;
  PERFORM org_vault_control_require_open();
  PERFORM pg_advisory_xact_lock(hashtext('orgvault:'||r.principal||'|'||r.agent||'|'||r.cred));
  SELECT * INTO r FROM org_vault_rotation WHERE id=p_rotation_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'org_vault_rotation_finalize: unknown rotation'; END IF;
  IF r.state='activated' THEN
    SELECT version INTO v_cur FROM org_vault_current WHERE principal=r.principal AND
      agent=r.agent AND cred=r.cred;
    IF v_cur=r.to_version AND r.hwm_attestation=p_hwm_attestation THEN RETURN; END IF;
    RAISE EXCEPTION 'org_vault_rotation_finalize: replay mismatch' USING ERRCODE='40001';
  END IF;
  IF r.state<>'activating' THEN
    RAISE EXCEPTION 'org_vault_rotation_finalize: invalid state %',r.state USING ERRCODE='40001';
  END IF;
  UPDATE org_vault_secret SET hwm_attestation=p_hwm_attestation
   WHERE principal=r.principal AND agent=r.agent AND cred=r.cred AND version=r.to_version
   RETURNING hwm_attestation INTO v_att;
  IF v_att IS NULL THEN RAISE EXCEPTION 'org_vault_rotation_finalize: staged row missing'; END IF;
  UPDATE org_vault_current SET version=r.to_version,updated_at=pg_now_text()
   WHERE principal=r.principal AND agent=r.agent AND cred=r.cred AND version=r.from_version;
  IF NOT FOUND THEN
    SELECT version INTO v_cur FROM org_vault_current WHERE principal=r.principal AND
      agent=r.agent AND cred=r.cred;
    IF v_cur<>r.to_version THEN
      RAISE EXCEPTION 'org_vault_rotation_finalize: current pointer conflict' USING ERRCODE='40001';
    END IF;
  END IF;
  UPDATE org_vault_rotation SET state='activated',hwm_attestation=p_hwm_attestation,
    updated_at=pg_now_text() WHERE id=r.id;
  PERFORM kb_audit_worm_append('kb',p_actor,'vault.rotation.activate',r.key_id,'allow',
    json_build_object('rotation_id',r.id,'version',r.to_version)::text);
END; $$;

-- The ops slice extends the TABLE return shape. PostgreSQL cannot change OUT
-- parameters through CREATE OR REPLACE, so an in-place P7-core upgrade must
-- drop this read facade before recreating it with the extended non-secret row.
DROP FUNCTION IF EXISTS org_vault_rotation_get(BIGINT);
CREATE OR REPLACE FUNCTION org_vault_rotation_get(p_rotation_id BIGINT)
RETURNS TABLE(id BIGINT,key_id TEXT,principal TEXT,team_id BIGINT,agent TEXT,cred TEXT,
  from_version BIGINT,to_version BIGINT,state TEXT,compromise BOOLEAN,hwm_attestation BYTEA,
  last_error TEXT,old_vendor_ref TEXT,new_vendor_ref TEXT,revoke_receipt TEXT,
  failure_phase TEXT,claim_owner TEXT,claim_token BIGINT,claim_until TIMESTAMPTZ)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT r.id,r.key_id,r.principal,r.team_id,r.agent,r.cred,r.from_version,r.to_version,
         r.state,r.compromise,r.hwm_attestation,r.last_error,r.old_vendor_ref,r.new_vendor_ref,
         r.revoke_receipt,r.failure_phase,r.claim_owner,r.claim_token,r.claim_until
    FROM org_vault_rotation r
   WHERE r.id=p_rotation_id
     AND (kb_principal_is_admin() OR
          (r.team_id IS NOT NULL AND r.team_id IN
           (SELECT team FROM kb_team_membership
             WHERE identity_key=current_setting('aimee.principal',true))));
$$;

CREATE OR REPLACE FUNCTION org_vault_rotation_claim(
  p_actor TEXT,p_rotation_id BIGINT,p_expected TEXT,p_owner TEXT,p_ttl_seconds INTEGER
) RETURNS BIGINT
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE r org_vault_rotation%ROWTYPE; v_token BIGINT;
BEGIN
  IF COALESCE(p_actor,'')='' OR COALESCE(p_expected,'')='' OR COALESCE(p_owner,'')='' OR
     char_length(p_owner)>200 OR p_ttl_seconds NOT BETWEEN 5 AND 300 THEN
    RAISE EXCEPTION 'org_vault_rotation_claim: invalid input' USING ERRCODE='22023';
  END IF;
  SELECT * INTO r FROM org_vault_rotation WHERE id=p_rotation_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'org_vault_rotation_claim: unknown rotation'; END IF;
  IF NOT org_vault_rotation_authorized(p_actor,r.team_id) THEN
    RAISE EXCEPTION 'org_vault_rotation_claim: not authorized' USING ERRCODE='42501';
  END IF;
  PERFORM org_vault_control_require_open();
  PERFORM pg_advisory_xact_lock(hashtext('orgvault:'||r.principal||'|'||r.agent||'|'||r.cred));
  SELECT * INTO r FROM org_vault_rotation WHERE id=p_rotation_id FOR UPDATE;
  IF r.state<>p_expected THEN
    RAISE EXCEPTION 'org_vault_rotation_claim: state conflict' USING ERRCODE='40001';
  END IF;
  IF r.claim_owner<>'' AND r.claim_until>clock_timestamp() THEN
    RAISE EXCEPTION 'org_vault_rotation_claim: already claimed' USING ERRCODE='40001';
  END IF;
  IF r.claim_token=9223372036854775807 THEN
    RAISE EXCEPTION 'org_vault_rotation_claim: token exhausted' USING ERRCODE='22003';
  END IF;
  UPDATE org_vault_rotation SET claim_owner=p_owner,claim_token=claim_token+1,
    claim_until=clock_timestamp()+make_interval(secs=>p_ttl_seconds),updated_at=pg_now_text()
    WHERE id=r.id RETURNING claim_token INTO v_token;
  PERFORM kb_audit_worm_append('kb',p_actor,'vault.rotation.claim',r.key_id,'allow',
    json_build_object('rotation_id',r.id,'state',r.state,'claim_token',v_token)::text);
  RETURN v_token;
END; $$;

CREATE OR REPLACE FUNCTION org_vault_rotation_heartbeat(
  p_actor TEXT,p_rotation_id BIGINT,p_owner TEXT,p_token BIGINT,p_ttl_seconds INTEGER
) RETURNS BOOLEAN
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE r org_vault_rotation%ROWTYPE;
BEGIN
  IF COALESCE(p_actor,'')='' OR COALESCE(p_owner,'')='' OR p_token<1 OR
     p_ttl_seconds NOT BETWEEN 5 AND 300 THEN
    RAISE EXCEPTION 'org_vault_rotation_heartbeat: invalid input' USING ERRCODE='22023';
  END IF;
  SELECT * INTO r FROM org_vault_rotation WHERE id=p_rotation_id;
  IF NOT FOUND OR NOT org_vault_rotation_authorized(p_actor,r.team_id) THEN
    RAISE EXCEPTION 'org_vault_rotation_heartbeat: not authorized' USING ERRCODE='42501';
  END IF;
  PERFORM org_vault_control_require_open();
  UPDATE org_vault_rotation SET claim_until=clock_timestamp()+make_interval(secs=>p_ttl_seconds),
    updated_at=pg_now_text() WHERE id=p_rotation_id AND claim_owner=p_owner AND
    claim_token=p_token AND claim_until>clock_timestamp();
  IF FOUND THEN
    PERFORM kb_audit_worm_append('kb',p_actor,'vault.rotation.heartbeat',r.key_id,'allow',
      json_build_object('rotation_id',r.id,'claim_token',p_token)::text);
  END IF;
  RETURN FOUND;
END; $$;

CREATE OR REPLACE FUNCTION org_vault_rotation_release(
  p_actor TEXT,p_rotation_id BIGINT,p_owner TEXT,p_token BIGINT
) RETURNS BOOLEAN
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE r org_vault_rotation%ROWTYPE;
BEGIN
  IF COALESCE(p_actor,'')='' OR COALESCE(p_owner,'')='' OR p_token IS NULL OR p_token<1 THEN
    RAISE EXCEPTION 'org_vault_rotation_release: invalid input' USING ERRCODE='22023';
  END IF;
  SELECT * INTO r FROM org_vault_rotation WHERE id=p_rotation_id;
  IF NOT FOUND OR NOT org_vault_rotation_authorized(p_actor,r.team_id) THEN
    RAISE EXCEPTION 'org_vault_rotation_release: not authorized' USING ERRCODE='42501';
  END IF;
  PERFORM org_vault_control_require_open();
  UPDATE org_vault_rotation SET claim_owner='',claim_until=NULL,updated_at=pg_now_text()
    WHERE id=p_rotation_id AND claim_owner=p_owner AND claim_token=p_token;
  IF FOUND THEN
    PERFORM kb_audit_worm_append('kb',p_actor,'vault.rotation.release',r.key_id,'allow',
      json_build_object('rotation_id',r.id,'claim_token',p_token)::text);
  END IF;
  RETURN FOUND;
END; $$;

CREATE OR REPLACE FUNCTION org_vault_rotation_checkpoint_old_ref(
  p_actor TEXT,p_rotation_id BIGINT,p_owner TEXT,p_token BIGINT,p_old_ref TEXT
) RETURNS VOID
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE r org_vault_rotation%ROWTYPE;
BEGIN
  IF COALESCE(p_actor,'')='' OR COALESCE(p_owner,'')='' OR p_token IS NULL OR p_token<1 OR
     COALESCE(p_old_ref,'')='' OR char_length(p_old_ref)>512 THEN
    RAISE EXCEPTION 'org_vault_rotation_checkpoint_old_ref: invalid ref' USING ERRCODE='22023';
  END IF;
  SELECT * INTO r FROM org_vault_rotation WHERE id=p_rotation_id;
  IF NOT FOUND OR NOT org_vault_rotation_authorized(p_actor,r.team_id) THEN
    RAISE EXCEPTION 'org_vault_rotation_checkpoint_old_ref: not authorized' USING ERRCODE='42501';
  END IF;
  PERFORM org_vault_control_require_open();
  SELECT * INTO r FROM org_vault_rotation WHERE id=p_rotation_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'org_vault_rotation_checkpoint_old_ref: not authorized' USING ERRCODE='42501';
  END IF;
  IF r.state<>'provision' OR r.claim_owner<>p_owner OR r.claim_token<>p_token OR
     r.claim_until<=clock_timestamp() THEN
    RAISE EXCEPTION 'org_vault_rotation_checkpoint_old_ref: stale claim' USING ERRCODE='40001';
  END IF;
  IF r.old_vendor_ref<>'' AND r.old_vendor_ref<>p_old_ref THEN
    RAISE EXCEPTION 'org_vault_rotation_checkpoint_old_ref: replay mismatch' USING ERRCODE='40001';
  END IF;
  UPDATE org_vault_rotation SET old_vendor_ref=p_old_ref,updated_at=pg_now_text() WHERE id=r.id;
  PERFORM kb_audit_worm_append('kb',p_actor,'vault.rotation.old_ref',r.key_id,'allow',
    json_build_object('rotation_id',r.id,'claim_token',p_token)::text);
END; $$;

CREATE OR REPLACE FUNCTION org_vault_rotation_stage_claimed(
  p_actor TEXT,p_rotation_id BIGINT,p_owner TEXT,p_token BIGINT,p_new_ref TEXT,
  p_wrapped_dek BYTEA,p_nonce BYTEA,p_ciphertext BYTEA,p_tag BYTEA
) RETURNS BIGINT
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE r org_vault_rotation%ROWTYPE; v_version BIGINT;
BEGIN
  IF COALESCE(p_actor,'')='' OR COALESCE(p_owner,'')='' OR p_token IS NULL OR p_token<1 OR
     COALESCE(p_new_ref,'')='' OR char_length(p_new_ref)>512 OR p_wrapped_dek IS NULL OR
     octet_length(p_wrapped_dek)<>40 OR p_nonce IS NULL OR octet_length(p_nonce)<>12 OR
     p_ciphertext IS NULL OR octet_length(p_ciphertext) NOT BETWEEN 1 AND 4096 OR
     p_tag IS NULL OR octet_length(p_tag)<>16 THEN
    RAISE EXCEPTION 'org_vault_rotation_stage_claimed: invalid ref' USING ERRCODE='22023';
  END IF;
  SELECT * INTO r FROM org_vault_rotation WHERE id=p_rotation_id;
  IF NOT FOUND OR NOT org_vault_rotation_authorized(p_actor,r.team_id) THEN
    RAISE EXCEPTION 'org_vault_rotation_stage_claimed: not authorized' USING ERRCODE='42501';
  END IF;
  PERFORM org_vault_control_require_open();
  IF r.state<>'provision' OR r.old_vendor_ref='' OR r.claim_owner<>p_owner OR
     r.claim_token<>p_token OR r.claim_until<=clock_timestamp() THEN
    RAISE EXCEPTION 'org_vault_rotation_stage_claimed: stale claim' USING ERRCODE='40001';
  END IF;
  v_version := org_vault_rotation_stage(p_actor,p_rotation_id,p_wrapped_dek,p_nonce,p_ciphertext,p_tag);
  SELECT * INTO r FROM org_vault_rotation WHERE id=p_rotation_id FOR UPDATE;
  IF NOT FOUND OR r.state<>'staged' OR r.claim_owner<>p_owner OR r.claim_token<>p_token OR
     r.claim_until<=clock_timestamp() THEN
    RAISE EXCEPTION 'org_vault_rotation_stage_claimed: stale claim' USING ERRCODE='40001';
  END IF;
  UPDATE org_vault_rotation SET new_vendor_ref=p_new_ref,claim_owner='',claim_until=NULL,
    updated_at=pg_now_text() WHERE id=p_rotation_id;
  RETURN v_version;
END; $$;

CREATE OR REPLACE FUNCTION org_vault_rotation_probe_admit(
  p_actor TEXT,p_rotation_id BIGINT,p_owner TEXT,p_token BIGINT,p_operation_key TEXT
) RETURNS TABLE(version BIGINT,wrapped_dek BYTEA,nonce BYTEA,ciphertext BYTEA,tag BYTEA)
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE r org_vault_rotation%ROWTYPE;
BEGIN
  IF COALESCE(p_actor,'')='' OR COALESCE(p_owner,'')='' OR p_token IS NULL OR p_token<1 OR
     COALESCE(p_operation_key,'')='' OR char_length(p_operation_key)>200 THEN
    RAISE EXCEPTION 'org_vault_rotation_probe_admit: invalid operation key' USING ERRCODE='22023';
  END IF;
  SELECT * INTO r FROM org_vault_rotation WHERE id=p_rotation_id;
  IF NOT FOUND OR NOT org_vault_rotation_authorized(p_actor,r.team_id) THEN
    RAISE EXCEPTION 'org_vault_rotation_probe_admit: not authorized' USING ERRCODE='42501';
  END IF;
  PERFORM org_vault_control_require_open();
  SELECT * INTO r FROM org_vault_rotation WHERE id=p_rotation_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'org_vault_rotation_probe_admit: not authorized' USING ERRCODE='42501';
  END IF;
  IF r.state<>'staged' OR r.claim_owner<>p_owner OR r.claim_token<>p_token OR
     r.claim_until<=clock_timestamp() THEN
    RAISE EXCEPTION 'org_vault_rotation_probe_admit: stale claim' USING ERRCODE='40001';
  END IF;
  IF NOT EXISTS(SELECT 1 FROM kb_audit_event WHERE action='vault.rotation.probe_use' AND
      subject=p_operation_key) THEN
    PERFORM kb_audit_worm_append('kb',p_actor,'vault.rotation.probe_use',p_operation_key,'allow',
      json_build_object('rotation_id',r.id,'version',r.to_version)::text);
  END IF;
  RETURN QUERY SELECT s.version,s.wrapped_dek,s.nonce,s.ciphertext,s.tag
    FROM org_vault_secret s WHERE s.principal=r.principal AND s.agent=r.agent AND
      s.cred=r.cred AND s.version=r.to_version AND s.hwm_attestation IS NULL;
END; $$;

CREATE OR REPLACE FUNCTION org_vault_rotation_transition_claimed(
  p_actor TEXT,p_rotation_id BIGINT,p_owner TEXT,p_token BIGINT,p_expected TEXT,p_next TEXT,
  p_receipt TEXT
) RETURNS VOID
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE r org_vault_rotation%ROWTYPE;
BEGIN
  IF COALESCE(p_actor,'')='' OR COALESCE(p_owner,'')='' OR p_token IS NULL OR p_token<1 OR
     COALESCE(p_expected,'')='' OR COALESCE(p_next,'')='' OR
     char_length(COALESCE(p_receipt,''))>512 THEN
    RAISE EXCEPTION 'org_vault_rotation_transition_claimed: receipt too long' USING ERRCODE='22023';
  END IF;
  SELECT * INTO r FROM org_vault_rotation WHERE id=p_rotation_id;
  IF NOT FOUND OR NOT org_vault_rotation_authorized(p_actor,r.team_id) THEN
    RAISE EXCEPTION 'org_vault_rotation_transition_claimed: not authorized' USING ERRCODE='42501';
  END IF;
  PERFORM org_vault_control_require_open();
  IF r.state<>p_expected OR r.claim_owner<>p_owner OR r.claim_token<>p_token OR
     r.claim_until<=clock_timestamp() THEN
    RAISE EXCEPTION 'org_vault_rotation_transition_claimed: stale claim' USING ERRCODE='40001';
  END IF;
  IF p_expected='activated' AND p_next='revoked' AND COALESCE(p_receipt,'')='' THEN
    RAISE EXCEPTION 'org_vault_rotation_transition_claimed: revoke evidence required'
      USING ERRCODE='22023';
  END IF;
  IF p_expected='revoked' AND p_next='retired' AND r.revoke_receipt='' THEN
    RAISE EXCEPTION 'org_vault_rotation_transition_claimed: revoke evidence missing'
      USING ERRCODE='40001';
  END IF;
  PERFORM org_vault_rotation_transition(p_actor,p_rotation_id,p_expected,p_next,'');
  SELECT * INTO r FROM org_vault_rotation WHERE id=p_rotation_id FOR UPDATE;
  IF NOT FOUND OR r.state<>p_next OR r.claim_owner<>p_owner OR r.claim_token<>p_token OR
     r.claim_until<=clock_timestamp() THEN
    RAISE EXCEPTION 'org_vault_rotation_transition_claimed: stale claim' USING ERRCODE='40001';
  END IF;
  UPDATE org_vault_rotation SET revoke_receipt=CASE WHEN COALESCE(p_receipt,'')=''
      THEN revoke_receipt ELSE p_receipt END,claim_owner='',claim_until=NULL,updated_at=pg_now_text()
    WHERE id=p_rotation_id;
END; $$;

CREATE OR REPLACE FUNCTION org_vault_rotation_fail_claimed(
  p_actor TEXT,p_rotation_id BIGINT,p_owner TEXT,p_token BIGINT,p_expected TEXT,p_phase TEXT,
  p_error TEXT
) RETURNS VOID
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE r org_vault_rotation%ROWTYPE;
BEGIN
  IF COALESCE(p_actor,'')='' OR COALESCE(p_owner,'')='' OR p_token IS NULL OR p_token<1 OR
     p_expected NOT IN ('provision','staged') OR p_phase NOT IN ('provision','probe') OR
     char_length(COALESCE(p_error,''))>1000 THEN
    RAISE EXCEPTION 'org_vault_rotation_fail_claimed: invalid phase' USING ERRCODE='22023';
  END IF;
  SELECT * INTO r FROM org_vault_rotation WHERE id=p_rotation_id;
  IF NOT FOUND OR NOT org_vault_rotation_authorized(p_actor,r.team_id) THEN
    RAISE EXCEPTION 'org_vault_rotation_fail_claimed: not authorized' USING ERRCODE='42501';
  END IF;
  PERFORM org_vault_control_require_open();
  IF r.state<>p_expected OR r.claim_owner<>p_owner OR r.claim_token<>p_token OR
     r.claim_until<=clock_timestamp() THEN
    RAISE EXCEPTION 'org_vault_rotation_fail_claimed: stale claim' USING ERRCODE='40001';
  END IF;
  PERFORM org_vault_rotation_transition(p_actor,p_rotation_id,p_expected,'failed',p_error);
  SELECT * INTO r FROM org_vault_rotation WHERE id=p_rotation_id FOR UPDATE;
  IF NOT FOUND OR r.state<>'failed' OR r.claim_owner<>p_owner OR r.claim_token<>p_token OR
     r.claim_until<=clock_timestamp() THEN
    RAISE EXCEPTION 'org_vault_rotation_fail_claimed: stale claim' USING ERRCODE='40001';
  END IF;
  UPDATE org_vault_rotation SET failure_phase=p_phase,claim_owner='',claim_until=NULL,
    updated_at=pg_now_text() WHERE id=p_rotation_id;
END; $$;

CREATE OR REPLACE FUNCTION org_vault_rotation_remediate(
  p_actor TEXT,p_rotation_id BIGINT,p_owner TEXT,p_token BIGINT,p_anchor_version BIGINT,
  p_evidence TEXT
) RETURNS VOID
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE r org_vault_rotation%ROWTYPE; v_cur BIGINT; v_bad BOOLEAN;
BEGIN
  IF COALESCE(p_actor,'')='' OR COALESCE(p_owner,'')='' OR p_token IS NULL OR p_token<1 OR
     p_anchor_version IS NULL OR COALESCE(p_evidence,'')='' OR char_length(p_evidence)>512 THEN
    RAISE EXCEPTION 'org_vault_rotation_remediate: evidence required' USING ERRCODE='22023';
  END IF;
  SELECT * INTO r FROM org_vault_rotation WHERE id=p_rotation_id;
  IF NOT FOUND OR NOT org_vault_rotation_authorized(p_actor,r.team_id) THEN
    RAISE EXCEPTION 'org_vault_rotation_remediate: not authorized' USING ERRCODE='42501';
  END IF;
  PERFORM org_vault_control_require_open();
  SELECT * INTO r FROM org_vault_rotation WHERE id=p_rotation_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'org_vault_rotation_remediate: not authorized' USING ERRCODE='42501';
  END IF;
  IF r.state<>'failed' OR r.claim_owner<>p_owner OR r.claim_token<>p_token OR
     r.claim_until<=clock_timestamp() OR p_anchor_version<>r.from_version THEN
    RAISE EXCEPTION 'org_vault_rotation_remediate: unsafe state' USING ERRCODE='40001';
  END IF;
  SELECT version INTO v_cur FROM org_vault_current WHERE principal=r.principal AND
    agent=r.agent AND cred=r.cred;
  IF v_cur<>r.from_version THEN
    RAISE EXCEPTION 'org_vault_rotation_remediate: current pointer changed' USING ERRCODE='40001';
  END IF;
  SELECT EXISTS(SELECT 1 FROM org_vault_secret WHERE principal=r.principal AND agent=r.agent AND
    cred=r.cred AND version=r.to_version AND hwm_attestation IS NOT NULL) INTO v_bad;
  IF v_bad THEN
    RAISE EXCEPTION 'org_vault_rotation_remediate: staged row is attested' USING ERRCODE='40001';
  END IF;
  DELETE FROM org_vault_secret WHERE principal=r.principal AND agent=r.agent AND cred=r.cred AND
    version=r.to_version AND hwm_attestation IS NULL;
  UPDATE org_vault_rotation SET state='retired',revoke_receipt=p_evidence,claim_owner='',
    claim_until=NULL,updated_at=pg_now_text() WHERE id=r.id;
  PERFORM kb_audit_worm_append('kb',p_actor,'vault.rotation.remediate',r.key_id,'allow',
    json_build_object('rotation_id',r.id,'failure_phase',r.failure_phase)::text);
END; $$;

-- These SECURITY DEFINER functions are never PUBLIC; EXECUTE is granted to the runtime
-- role out of band in schema_grants.sql (hardened tier only).
REVOKE ALL ON FUNCTION org_vault_salt_ensure(TEXT,BYTEA) FROM PUBLIC;
REVOKE ALL ON FUNCTION org_vault_salt_read(TEXT) FROM PUBLIC;
REVOKE ALL ON FUNCTION org_vault_kek_check_read(TEXT) FROM PUBLIC;
REVOKE ALL ON FUNCTION org_vault_kek_check_set(TEXT,BYTEA) FROM PUBLIC;
REVOKE ALL ON FUNCTION org_vault_put(TEXT,BIGINT,TEXT,TEXT,BIGINT,BYTEA,BYTEA,BYTEA,BYTEA) FROM PUBLIC;
REVOKE ALL ON FUNCTION org_vault_get_current(TEXT,TEXT,TEXT) FROM PUBLIC;
REVOKE ALL ON FUNCTION org_vault_has(TEXT,TEXT,TEXT) FROM PUBLIC;
REVOKE ALL ON FUNCTION org_vault_list(TEXT) FROM PUBLIC;
REVOKE ALL ON FUNCTION org_vault_list_principals() FROM PUBLIC;
REVOKE ALL ON FUNCTION org_vault_delete(TEXT,TEXT,TEXT) FROM PUBLIC;
REVOKE ALL ON FUNCTION org_vault_current_wraps(TEXT) FROM PUBLIC;
REVOKE ALL ON FUNCTION org_vault_rewrap(TEXT,TEXT,TEXT,BIGINT,BYTEA) FROM PUBLIC;
REVOKE ALL ON FUNCTION org_vault_rotation_authorized(TEXT,BIGINT) FROM PUBLIC;
REVOKE ALL ON FUNCTION org_vault_rotation_start(TEXT,TEXT,TEXT,BIGINT,TEXT,TEXT,BIGINT,BOOLEAN) FROM PUBLIC;
REVOKE ALL ON FUNCTION org_vault_rotation_stage(TEXT,BIGINT,BYTEA,BYTEA,BYTEA,BYTEA) FROM PUBLIC;
REVOKE ALL ON FUNCTION org_vault_rotation_transition(TEXT,BIGINT,TEXT,TEXT,TEXT) FROM PUBLIC;
REVOKE ALL ON FUNCTION org_vault_rotation_finalize(TEXT,BIGINT,BYTEA) FROM PUBLIC;
REVOKE ALL ON FUNCTION org_vault_rotation_get(BIGINT) FROM PUBLIC;
REVOKE ALL ON FUNCTION org_vault_rotation_claim(TEXT,BIGINT,TEXT,TEXT,INTEGER) FROM PUBLIC;
REVOKE ALL ON FUNCTION org_vault_rotation_heartbeat(TEXT,BIGINT,TEXT,BIGINT,INTEGER) FROM PUBLIC;
REVOKE ALL ON FUNCTION org_vault_rotation_release(TEXT,BIGINT,TEXT,BIGINT) FROM PUBLIC;
REVOKE ALL ON FUNCTION org_vault_rotation_checkpoint_old_ref(TEXT,BIGINT,TEXT,BIGINT,TEXT) FROM PUBLIC;
